        maintenance = new MaintenanceManager(this);
        serverControls = new ServerControlManager(this);
        adminSpy = new AdminSpyManager(this);
        adminSecurity = new AdminSecurityManager(this);
        afk = new AfkManager(this);
        startMessages = new StartMessageManager(this);
        watchlist = new WatchlistManager(this);
        announcements = new AnnouncementManager(this);
        duty = new DutyManager(this);
        restartManager = new RestartManager(this);
