        reconnectGuard = new ReconnectGuard(this);
        warps = new WarpManager(this);
        antiSpam = new AntiSpamManager(this);
        crossplayUpdates = new CrossplayUpdateManager(this);
        expansion = new SuiteExpansion(this);
        worldTrimmer = new WorldTrimManager(this);
        adminQuality = new AdminQualityManager(this);
        powerTools = new AdminPowerToolsManager(this);
        funFeatures = new FunFeaturesManager(this);
        nicknames = new NicknameManager(this);
