        activityIntelligence = new ActivityIntelligence(this);
        nativeScoreboard = new NativeScoreboardManager(this);
        playerData = new PlayerDataManager(this);
        openAi = new OpenAiIntegration(this);
        try { accountLinks = new AccountLinkManager(this); } catch (java.io.IOException e) { throw new IllegalStateException("Discord-Verknüpfungen konnten nicht sicher geladen werden",e); }
        community = new PlayerCommunityManager(this);
        LiveMenus.configure(this);Bukkit.getPluginManager().registerEvents(new LiveMenus(),this);
        Bukkit.getPluginManager().registerEvents(community, this);
        for(PlayerProfile p:database.sortedProfiles())community.importLegacy(p.uuid,new ArrayList<>(p.recentActions),p.internalBanUntil,p.internalBanReason,p.internalMuteUntil,p.internalMuteReason);
        community.start();
        try { pointsEconomy = new PointsEconomy(this); } catch(Exception e) { throw new IllegalStateException("Punkte/Shop-Datenbank konnte nicht sicher geöffnet werden",e); }
        Bukkit.getServicesManager().register(eu.simplexsmp.adminsuite.api.SimplexPointsApi.class,pointsEconomy,this,org.bukkit.plugin.ServicePriority.Normal);
        communityMenus = new CommunityMenus(this);
        shop = new SimplexShop(this);
        deliveries = new QuickDelivery(this);
        Bukkit.getPluginManager().registerEvents(communityMenus,this);
        Bukkit.getPluginManager().registerEvents(shop,this);
        Bukkit.getPluginManager().registerEvents(deliveries,this);
        deliveries.start(); register("shop"); register("delivery"); register("spcurrency");
        register("simplexprofile"); register("feedback");
        serverStatistics = new ServerStatistics(this);
        luckPerms = new LuckPermsBridge(this);
        playerCommands = new PlayerCommandManager(this);
        Bukkit.getPluginManager().registerEvents(playerCommands, this);
        staffWorkspace = new StaffWorkspace(this, luckPerms);
        bedrockMenus = createBedrockMenus();
        if(community!=null)for(Player p:Bukkit.getOnlinePlayers())community.admitted(p);
        altDetection.start();
        // The activity listener runs before the legacy AFK listener so only credible input
        // can clear AFK state or advance point time.
        Bukkit.getPluginManager().registerEvents(adminRuntime, this);
        itemCleanup = new LegacyItemCleanup(this);
        Bukkit.getPluginManager().registerEvents(itemCleanup, this);
        Bukkit.getPluginManager().registerEvents(adminUpdate, this);
        Bukkit.getPluginManager().registerEvents(activityIntelligence, this);
        primeConfigAudit();
        moderationControl = new ModerationControl(this);
        moderationControl.start();
        Bukkit.getPluginManager().registerEvents(moderationControl, this);
        Bukkit.getPluginManager().registerEvents(this, this);
        Bukkit.getPluginManager().registerEvents(new RelayEvents(this), this);
        Bukkit.getPluginManager().registerEvents(vpnProtection, this);
        Bukkit.getPluginManager().registerEvents(adminQuality, this);
        Bukkit.getPluginManager().registerEvents(powerTools, this);
        Bukkit.getPluginManager().registerEvents(funFeatures, this);
