            int seconds;
            try { seconds = is(args[1], "off", "aus", "0") ? 0 : Integer.parseInt(args[1]); }
            catch (Exception ignored) { return usage(sender, "/" + label + " slowmode <0-120>"); }
            serverControls.setSlowmode(sender.getName(), Math.max(0, Math.min(120, seconds)));
