    private boolean isAnimalLike(Entity entity) {
        if (entity == null || entity.getType() == null) return false;
        String n = entity.getType().name().toLowerCase(Locale.ROOT);
        return n.contains("cow") || n.contains("pig") || n.contains("sheep") || n.contains("chicken") || n.contains("horse") || n.contains("cat") || n.contains("wolf") || n.contains("rabbit") || n.contains("fox") || n.contains("bee") || n.contains("villager") || n.contains("goat") || n.contains("camel") || n.contains("frog") || n.contains("turtle");
    }

    private boolean isVillagerLike(Entity entity) {
        if (entity == null || entity.getType() == null) return false;
        return entity.getType() == EntityType.VILLAGER || entity.getType() == EntityType.WANDERING_TRADER || entity.getType().name().toLowerCase(Locale.ROOT).contains("villager");
    }

    private boolean isVehicleOrRideable(Entity entity) {
        if (entity == null || entity.getType() == null) return false;
        String name = entity.getType().name();
        return containsAnyIgnoreCase(name, "BOAT", "MINECART", "HORSE", "DONKEY", "MULE", "CAMEL", "PIG", "STRIDER", "LLAMA");
    }

    private boolean containsPlayerMention(String message) {
        if (message == null || message.isBlank()) return false;
        return Pattern.compile("(?i)(?<![A-Za-z0-9_])@[A-Za-z0-9_]{1,16}(?![A-Za-z0-9_])").matcher(message).find();
    }

    private boolean isEdibleMaterial(ItemStack item) {
        if (item == null || item.getType() == null) return false;
        try {
            Object value = item.getType().getClass().getMethod("isEdible").invoke(item.getType());
            if (value instanceof Boolean) return (Boolean) value;
        } catch (Throwable ignored) { }
        String name = item.getType().name();
        return containsAnyIgnoreCase(name, "APPLE", "BREAD", "CARROT", "POTATO", "BEEF", "PORKCHOP", "CHICKEN", "MUTTON", "RABBIT", "COD", "SALMON", "COOKIE", "MELON", "BERRIES", "CHORUS_FRUIT", "STEW", "SOUP", "PIE", "CAKE", "HONEY_BOTTLE", "DRIED_KELP");
    }

    private String inventoryTypeName(Inventory inventory) {
        if (inventory == null) return "";
        StringBuilder result = new StringBuilder(inventory.getClass().getSimpleName().toUpperCase(Locale.ROOT));
        try {
            Object type = inventory.getClass().getMethod("getType").invoke(inventory);
            if (type != null) result.append(' ').append(String.valueOf(type).toUpperCase(Locale.ROOT));
        } catch (Throwable ignored) { }
        return result.toString();
    }

    private static boolean containsAnyIgnoreCase(String value, String... needles) {
        String normalized = value == null ? "" : value.toUpperCase(Locale.ROOT);
        for (String needle : needles) if (normalized.contains(needle.toUpperCase(Locale.ROOT))) return true;
        return false;
    }


    private boolean isReportableTarget(Player reporter, PlayerProfile target) {
        if (reporter == null || target == null || reporter.getUniqueId().equals(target.uuid)) return false;
        long window = Math.max(1L, getConfig().getLong("reports.eligible-hours", 24L)) * 60L * 60L * 1000L;
        return target.lastSeen > 0L && System.currentTimeMillis() - target.lastSeen <= window;
    }

    private List<PlayerProfile> reportableProfiles(Player reporter) {
        return reportableProfiles(reporter, null);
    }

    private List<PlayerProfile> reportableProfiles(Player reporter, String query) {
        List<PlayerProfile> result = new ArrayList<>();
        for (Player online : Bukkit.getOnlinePlayers()) database.touch(online);
        String needle = query == null ? "" : sanitizeText(query, 64).trim().toLowerCase(Locale.ROOT);
        if (needle.isEmpty()) return result;
        for (PlayerProfile profile : database.sortedProfiles()) {
            if (!isReportableTarget(reporter, profile)) continue;
            boolean matches = profile.name.toLowerCase(Locale.ROOT).contains(needle);
            if (!matches) {
                synchronized (profile.previousNames) {
                    for (String previousName : profile.previousNames) {
                        if (previousName != null && previousName.toLowerCase(Locale.ROOT).contains(needle)) { matches = true; break; }
                    }
                }
            }
            if (matches) result.add(profile);
        }
        result.sort(Comparator
                .comparingInt((PlayerProfile profile) -> {
                    String lower = profile.name.toLowerCase(Locale.ROOT);
                    if (lower.equals(needle)) return 0;
                    if (lower.startsWith(needle)) return 1;
                    return 2;
                })
                .thenComparing(profile -> profile.name, String.CASE_INSENSITIVE_ORDER));
        return result;
    }

    private String staffReportCategory(String category) {
        if (category == null || category.isBlank()) return "Nicht angegeben";
        String normalized = category.trim().toLowerCase(Locale.ROOT);
        if (normalized.equals("chat abuse / insults") || normalized.equals("chat / beleidigung")) return "Chat / Beleidigung";
        if (normalized.equals("griefing / theft") || normalized.equals("griefing / diebstahl")) return "Griefing / Diebstahl";
        if (normalized.equals("cheating / exploits")) return "Cheating / Exploits";
        if (normalized.equals("pvp harassment") || normalized.equals("pvp / belästigung")) return "PvP / Belästigung";
        if (normalized.equals("spam / advertising") || normalized.equals("spam / werbung")) return "Spam / Werbung";
        if (normalized.equals("other") || normalized.equals("sonstiges")) return "Sonstiges";
        return category;
    }

    private void openReportMenu(Player player) {
        if (getConfig().getBoolean("floodgate.prefer-bedrock-forms", true) && bedrockMenus.isBedrock(player) && bedrockMenus.openReport(player)) return;
        openReportSearch(player);
    }

    private void openReportSearch(Player reporter) {
        ReportBlock block = reports.blockFor(reporter.getUniqueId());
        if (block != null) {
            reporter.closeInventory();
            reporter.sendMessage(playerUiText(reporter, prefix() + "You are blocked from using the report system. Reason: " + block.reason));
            return;
        }
        Inventory inv = LiveMenus.create(new SuiteMenu("report-search", null, 0, null, null), 27, color(playerUiText(reporter,"&8Report a player")));
        fill(inv);
        inv.setItem(11, item(Material.NAME_TAG, "&eSearch by player name",
                "&7Enter any part of the player's name.",
                "&7Only players seen within the last &f" + getConfig().getLong("reports.eligible-hours", 24L) + " hours &7can appear.",
                "&7Click to enter a partial name."));
        inv.setItem(15, item(Material.WRITABLE_BOOK, "&bHow reporting works",
                "&7Search first, select the matching player,",
                "&7choose a reason and describe what happened.",
                "&7False or abusive reports may lead to a block."));
        inv.setItem(22, item(Material.BARRIER, "&cClose", "&7Close the report menu."));
        localizePublicInventory(reporter,inv); LiveMenus.show(reporter,inv);
    }

    private void beginReport(Player reporter, PlayerProfile target) {
        if (!isReportableTarget(reporter, target)) {
            reporter.sendMessage(playerUiText(reporter, prefix() + "This player is no longer inside the allowed reporting window."));
            openReportSearch(reporter);
            return;
        }
        ReportDraft draft = new ReportDraft(target.uuid, target.name);
        draft.includeEvidence = getConfig().getBoolean("reports.default-include-evidence", true);
        reportDrafts.put(reporter.getUniqueId(), draft);
        openReportCompose(reporter);
    }

    private void openReportPlayers(Player reporter, String query, int requestedPage) {
        ReportBlock block = reports.blockFor(reporter.getUniqueId());
        if (block != null) {
            reporter.closeInventory();
            reporter.sendMessage(playerUiText(reporter, prefix() + "You are blocked from using the report system. Reason: " + block.reason));
            return;
        }
        String cleanQuery = sanitizeText(query, 64).trim();
        int minimumLength = Math.max(1, getConfig().getInt("reports.minimum-search-length", 1));
        if (cleanQuery.length() < minimumLength) {
            reporter.sendMessage(playerUiText(reporter, prefix() + "Enter at least " + minimumLength + " character" + (minimumLength == 1 ? "" : "s") + " of the player's name."));
            openReportSearch(reporter);
            return;
        }
        List<PlayerProfile> players = reportableProfiles(reporter, cleanQuery);
        reportSelectionViews.put(reporter.getUniqueId(), players.stream().map(profile -> profile.uuid).collect(Collectors.toList()));
        int maxPage = Math.max(0, (players.size() - 1) / 45);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("report-select", null, page, null, cleanQuery), 54, color(playerUiText(reporter,"&8Report search: &f") + shortenText(cleanQuery, 20)));
        ItemStack reportGlass = item(Material.GRAY_STAINED_GLASS_PANE, " ");
        for (int slot = 45; slot < 54; slot++) inv.setItem(slot, reportGlass);
        if (page > 0) inv.setItem(45, item(Material.ARROW, "&ePrevious page", "&7Current page: &f" + (page + 1)));
        inv.setItem(49, item(Material.BARRIER, "&cClose", "&7Close the report menu."));
        if (page < maxPage) inv.setItem(53, item(Material.ARROW, "&eNext page", "&7Maximum page: &f" + (maxPage + 1)));
        inv.setItem(47, item(Material.WRITABLE_BOOK, "&eSearch information",
                "&7Search: &f" + cleanQuery,
                "&7Matches: &f" + players.size(),
                "&7Only players seen within the last &f" + getConfig().getLong("reports.eligible-hours", 24L) + " hours&7."));
        inv.setItem(48, item(Material.NAME_TAG, "&eNew search", "&7Enter another partial player name."));
        for (int i = 0; i < 45; i++) {
            int index = page * 45 + i;
            if (index >= players.size()) break;
            PlayerProfile target = players.get(index);
            boolean online = Bukkit.getPlayer(target.uuid) != null;
            ItemStack skull = item(Material.PLAYER_HEAD, (online ? "&a" : "&e") + target.name,
                    online ? "&aCurrently online" : "&eRecently online",
                    "&7Eligible for reporting within the configured time window.",
                    "&7Click to report this player.");
            Player onlinePlayer = Bukkit.getPlayer(target.uuid);
            if (onlinePlayer != null) applySkull(skull, onlinePlayer);
            inv.setItem(i, skull);
        }
        if (players.isEmpty()) inv.setItem(22, item(Material.BARRIER, "&cNo matching player found",
                "&7No eligible player matched &f" + cleanQuery + "&7.",
                "&7Try another part of the name."));
        localizePublicInventory(reporter,inv); LiveMenus.show(reporter,inv);
    }

    private void openReportCompose(Player reporter) {
        ReportDraft draft = reportDrafts.get(reporter.getUniqueId());
        if (draft == null) { openReportMenu(reporter); return; }
        PlayerProfile target = database.get(draft.target);
        if (target == null || !isReportableTarget(reporter, target)) {
            reportDrafts.remove(reporter.getUniqueId());
            reporter.sendMessage(playerUiText(reporter, prefix() + "The selected player can no longer be reported."));
            openReportSearch(reporter);
            return;
        }
        Inventory inv = LiveMenus.create(new SuiteMenu("report-compose", target.uuid, 0, null, null), 54, color(playerUiText(reporter,"&8Create report: &f") + target.name));
        fill(inv);
        inv.setItem(4, item(Material.PLAYER_HEAD, "&e" + target.name,
                "&7Category: &f" + (draft.category == null ? "Not selected" : draft.category),
                "&7Description: &f" + (draft.details.isEmpty() ? "Not entered" : shortenText(draft.details, 80))));
        Material[] icons = {Material.PAPER, Material.CHEST, Material.DIAMOND_PICKAXE, Material.IRON_SWORD, Material.WRITABLE_BOOK, Material.MAP};
        for (int i = 0; i < PUBLIC_REPORT_CATEGORIES.length; i++) {
            String category = PUBLIC_REPORT_CATEGORIES[i];
            boolean selected = category.equals(draft.category);
            inv.setItem(10 + i, item(icons[i], (selected ? "&a✔ " : "&e") + category,
                    selected ? "&aSelected" : "&7Click to select this category."));
        }
        inv.setItem(22, item(Material.WRITABLE_BOOK, "&eDescribe the incident",
                draft.details.isEmpty() ? "&7No description entered yet." : "&f" + shortenText(draft.details, 100),
                "&7Click and type the description in chat."));
        inv.setItem(24, item(draft.includeEvidence ? Material.LIME_DYE : Material.GRAY_DYE,
                draft.includeEvidence ? "&aEvidence snapshot enabled" : "&7Evidence snapshot disabled",
                "&7Only authorized staff can view saved evidence:",
                "&7last location, chat, actions, combat events",
                "&7and technical player information.",
                "&7Click to toggle."));
        inv.setItem(31, item(Material.EMERALD, "&aSubmit report",
                "&7The category and description will be validated.",
                "&7Reports are visible only to authorized staff."));
        inv.setItem(49, item(Material.BARRIER, "&cCancel", "&7Discard this report."));
        localizePublicInventory(reporter,inv); LiveMenus.show(reporter,inv);
    }

    private void submitReport(Player reporter) {
        if (!has(reporter, "simplexadminsuite.report")) {
            reporter.sendMessage(playerUiText(reporter, prefix() + "You do not have permission to use the report system."));
            reportDrafts.remove(reporter.getUniqueId());
            return;
        }
        ReportDraft draft = reportDrafts.get(reporter.getUniqueId());
        if (draft == null) { openReportMenu(reporter); return; }
        PlayerProfile target = database.get(draft.target);
        if (target == null || !isReportableTarget(reporter, target)) {
            reporter.sendMessage(playerUiText(reporter, prefix() + "The selected player can no longer be reported."));
            reportDrafts.remove(reporter.getUniqueId());
            openReportSearch(reporter);
            return;
        }
        if (draft.category == null || draft.category.isBlank()) {
            reporter.sendMessage(playerUiText(reporter, prefix() + "Select a report category first."));
            openReportCompose(reporter);
            return;
        }
        int minLength = Math.max(3, getConfig().getInt("reports.minimum-description-length", 8));
        if (draft.details == null || draft.details.trim().length() < minLength) {
            reporter.sendMessage(playerUiText(reporter, prefix() + "Describe the incident using at least " + minLength + " characters."));
            ask(reporter, target.uuid, "report-details", "Describe what happened. Type 'cancel' to return to the report.");
            return;
        }
        ReportCreateResult result = reports.create(reporter, target, draft);
        if (!result.success) {
            reporter.sendMessage(playerUiText(reporter, prefix() + result.message));
            openReportCompose(reporter);
            return;
        }
        reportDrafts.remove(reporter.getUniqueId());
        reporter.closeInventory();
        reporter.sendMessage(playerUiText(reporter, prefix() + "Your report was saved as report #" + result.report.id + ". Thank you for helping the server."));
        target.addAction("Report #" + result.report.id + " wurde gegen diesen Spieler erstellt");
        database.save(target);
        audit.log(reporter.getName(), target.uuid, "Report erstellt", "#" + result.report.id + " | " + draft.category);
        notifyStaffReport(result.report);
    }

    private void notifyStaffReport(ReportCase report) {
        String text = prefix() + color("&cNeuer Report #" + report.id + " &7gegen &f" + report.targetName + " &7von &f" + report.reporterName + "&7. Kategorie: &e" + staffReportCategory(report.category));
        for (Player player : Bukkit.getOnlinePlayers()) if (has(player, "simplexadminsuite.reports")) player.sendMessage(playerUiText(player, text));
    }

    private void openReports(Player admin, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.openreports")) return;
        if (!require(admin, "simplexadminsuite.admin") || !require(admin, "simplexadminsuite.reports")) return;
        List<ReportCase> list = reports.sortedReports();
        reportCaseViews.put(admin.getUniqueId(), list.stream().map(report -> report.id).collect(Collectors.toList()));
        int maxPage = Math.max(0, (list.size() - 1) / 45);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("reports", null, page, null, null), 54, color("&8Report-Zentrale &7Seite " + (page + 1)));
        fillBottom(inv, page, maxPage);
        inv.setItem(48, item(Material.WRITABLE_BOOK, "&cReport-Übersicht",
                "&7Offen: &f" + reports.count(ReportStatus.OPEN),
                "&7In Bearbeitung: &f" + reports.count(ReportStatus.IN_REVIEW),
                "&7Erledigt: &f" + reports.count(ReportStatus.RESOLVED),
                "&7Abgelehnt: &f" + reports.count(ReportStatus.REJECTED)));
        for (int i = 0; i < 45; i++) {
            int index = page * 45 + i;
            if (index >= list.size()) break;
            ReportCase report = list.get(index);
            Material icon = report.status == ReportStatus.OPEN ? Material.RED_DYE
                    : report.status == ReportStatus.IN_REVIEW ? Material.YELLOW_DYE
                    : report.status == ReportStatus.RESOLVED ? Material.LIME_DYE : Material.GRAY_DYE;
            inv.setItem(i, item(icon, statusColor(report.status) + "Report #" + report.id + " &f" + report.targetName,
                    "&7Status: &f" + report.status.label,
                    "&7Reporter: &f" + report.reporterName,
                    "&7Kategorie: &f" + staffReportCategory(report.category),
                    "&7Erstellt: &f" + time(report.createdAt),
                    "&7Klick für Fallakte."));
        }
        if (list.isEmpty()) inv.setItem(22, item(Material.LIME_DYE, "&aKeine Reports vorhanden", "&7Aktuell sind keine Fallakten gespeichert."));
        LiveMenus.show(admin,inv);
    }

