    private void openReportEvidence(Player admin, long id, String type, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.openreportevidence")) return;
        if (!require(admin, "simplexadminsuite.admin") || !require(admin, "simplexadminsuite.reports")) return;
        ReportCase report = reports.get(id);
        if (report == null) { openReports(admin, 0); return; }
        List<String> lines;
        String title;
        Material icon;
        if (type.equals("chat")) { lines = report.chatEvidence; title = "Chat-Beweise"; icon = Material.BOOK; }
        else if (type.equals("actions")) { lines = report.actionEvidence; title = "Aktions-Beweise"; icon = Material.MAP; }
        else if (type.equals("combat")) { lines = report.combatEvidence; title = "Kampf-Beweise"; icon = Material.IRON_SWORD; }
        else {
            lines = report.overviewLines();
            title = "Standort & Übersicht";
            icon = Material.COMPASS;
        }
        int maxPage = Math.max(0, (lines.size() - 1) / 45);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("report-evidence", report.targetUuid, page, String.valueOf(id), type), 54, color("&8" + title + " #" + id));
        fillBottom(inv, page, maxPage);
        int start = page * 45;
        for (int i = 0; i < 45; i++) {
            int index = start + i;
            if (index >= lines.size()) break;
            inv.setItem(i, item(icon, "&fEintrag " + (index + 1), splitLore(lines.get(index))));
        }
        if (lines.isEmpty()) inv.setItem(22, item(Material.BARRIER, "&7Keine Beweisdaten", "&7Der Reporter hat die optionale", "&7Beweissicherung nicht aktiviert."));
        LiveMenus.show(admin,inv);
    }

