    private void handleServerControlsClick(Player admin, int slot) {
        if(slot==36){moderationControl.chatMenu(admin);return;}
        if (slot == 31) { openMain(admin); return; }
        if (slot == 10) { if (!require(admin, "simplexadminsuite.chattoggle")) return; serverControls.setGlobalChatEnabled(admin.getName(), !serverControls.globalChatEnabled()); openServerControls(admin); }
        else if (slot == 11) { if (!require(admin, "simplexadminsuite.adminspy")) return; adminSpy.toggleSpy(admin); openServerControls(admin); }
        else if (slot == 12) openStartMessages(admin, 0);
        else if (slot == 13) openSecuritySettings(admin);
        else if (slot == 14) openStealthSettings(admin);
        else if (slot == 15) openAfkSettings(admin);
        else if (slot == 16) openMaintenance(admin);
        else if (slot == 17) openDiscordStatusSettings(admin);
    }

    void openDiscordConnectionSettings(Player admin){if(isBedrockClient(admin)&&bedrockMenus instanceof FloodgateBedrockMenus menus)menus.openDiscordStatusSettings(admin);else openDiscordStatusSettings(admin);}
