    private List<String> forensicLore(Map<String, Long> history, int limit, String label) {
        List<String> out = new ArrayList<>();
        List<Map.Entry<String, Long>> entries = sortedHistory(history, limit);
        if (entries.isEmpty()) { out.add("&7Keine Daten gespeichert."); return out; }
        int index = 1;
        for (Map.Entry<String, Long> entry : entries) {
            out.add("&7" + index + ". &f" + label + ": " + entry.getKey());
            out.add("&8   zuletzt " + time(entry.getValue()));
            index++;
        }
        return out;
    }

    private List<String> forensicPlain(Map<String, Long> history, int limit) {
        List<String> out = new ArrayList<>();
        for (Map.Entry<String, Long> entry : sortedHistory(history, limit)) {
            out.add(entry.getKey());
        }
        if (out.isEmpty()) out.add("Keine");
        return out;
    }

    private List<Map.Entry<String, Long>> sortedHistory(Map<String, Long> history, int limit) {
        List<Map.Entry<String, Long>> entries;
        synchronized (history) { entries = new ArrayList<>(history.entrySet()); }
        entries.sort(Map.Entry.<String,Long>comparingByValue().reversed());
        return entries.size() <= limit ? entries : new ArrayList<>(entries.subList(0, limit));
    }

    private List<String> namedForensicLine(String label, String rawValue) {
        return Arrays.asList("&7" + label + ":", "&f" + value(rawValue));
    }

    private String value(String value) { return value == null || value.isBlank() ? "Nicht verfügbar" : value; }
    private String numberOrDash(int value) { return value < 0 ? "-" : Integer.toString(value); }

    private void openDeviceHistory(Player admin, UUID targetUuid, int requestedPage, String requestedFilter, String requestedQuery) {
        if (!adminMenuAllowed(admin, "suite.opendevicehistory")) return;
        if (!require(admin, "simplexadminsuite.alts.identities")) return;
        PlayerProfile target = database.get(targetUuid);
        if (target == null) { menuNotice(admin,prefix() + "Spielerprofil nicht gefunden."); return; }
        String filter = normalizeDeviceFilter(requestedFilter);
        String query = sanitizeText(requestedQuery, 120);
        List<DeviceRecord> devices = altDetection.devices(target, filter, query);
        deviceViews.put(admin.getUniqueId(), devices.stream().map(record -> record.id).collect(Collectors.toList()));
        int maxPage = Math.max(0, (devices.size() - 1) / 45);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("device-list", target.uuid, page, filter, query), 54, color("&8Geräte: &f" + target.name));
        fillBottom(inv, page, maxPage);
        int start = page * 45;
        for (int slot = 0; slot < 45; slot++) {
            int index = start + slot;
            if (index >= devices.size()) break;
            DeviceRecord record = devices.get(index);
            inv.setItem(slot, item(record.platform.equals("BEDROCK") ? Material.ENDER_EYE : Material.REDSTONE,
                    (record.blocked ? "&c" : record.platform.equals("BEDROCK") ? "&b" : "&e") + deviceTitle(record),
                    "&7Typ: &f" + record.platform,
                    "&7ID: &f" + shortenText(record.id, 40),
                    "&7Modell/Client: &f" + value(record.model),
                    "&7OS: &f" + value(record.os),
                    "&7Letzte IP: &f" + value(record.lastIp),
                    "&7Gespeicherte IPs: &f" + record.ipHistory.size() + "/10",
                    "&7Zuletzt: &f" + time(record.lastSeen),
                    record.blocked ? "&cServerweit gesperrt" : "&aNicht gesperrt",
                    "&7Klick für alle Rohdaten."));
        }
        if (devices.isEmpty()) inv.setItem(22, item(Material.BARRIER, "&cKeine Geräte gefunden", "&7Passe Suche oder Filter an."));
        inv.setItem(47, item(Material.COMPARATOR, "&eFilter: &f" + deviceFilterLabel(filter), "&7Klick wechselt Alle / Bedrock / Java / Gesperrt."));
        inv.setItem(48, item(Material.NAME_TAG, "&eGeräte durchsuchen", query.isBlank() ? "&7Keine Suche aktiv." : "&7Aktuell: &f" + query, "&7Sucht in ID, Modell, OS, Version und IP."));
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zur Alt-Account-Akte."));
        inv.setItem(50, item(Material.PAPER, "&eSuche zurücksetzen", "&7Zeigt alle Geräte des aktuellen Filters."));
        inv.setItem(52, item(Material.LAVA_BUCKET, "&cAlle Gerätedaten löschen", "&7Löscht die vollständige Gerätehistorie", "&7dieses Spielers dauerhaft."));
        LiveMenus.show(admin,inv);
    }

    private void handleDeviceListClick(Player admin, SuiteMenu menu, int slot) {
        if (!require(admin, "simplexadminsuite.alts.identities")) return;
        if (slot == 45 && menu.page > 0) { openDeviceHistory(admin, menu.target, menu.page - 1, menu.history, menu.search); return; }
        if (slot == 53) { openDeviceHistory(admin, menu.target, menu.page + 1, menu.history, menu.search); return; }
        if (slot == 47) { openDeviceHistory(admin, menu.target, 0, nextDeviceFilter(menu.history), menu.search); return; }
        if (slot == 48) { ask(admin, menu.target, "device-search", "Schreibe Geräte-ID, Modell, OS, Version oder IP. 'abbrechen' bricht ab.", menu.history); return; }
        if (slot == 49) { openAltProfile(admin, menu.target); return; }
        if (slot == 50) { openDeviceHistory(admin, menu.target, 0, menu.history, ""); return; }
        if (slot == 52) {
            PlayerProfile target = database.get(menu.target); if (target == null) return;
            confirm(admin, new PendingAction("device-clear", target.uuid, "", ""), "Alle Gerätedaten löschen", target.name, "Alle gespeicherten Java- und Bedrock-Geräteprofile dauerhaft löschen?"); return;
        }
        if (slot < 0 || slot >= 45) return;
        List<String> ids = deviceViews.getOrDefault(admin.getUniqueId(), Collections.emptyList());
        int index = menu.page * 45 + slot;
        if (index < ids.size()) openDeviceDetail(admin, menu.target, ids.get(index));
    }

