        if (record.platform.equals("BEDROCK")) inv.setItem(30, item(record.blocked ? Material.LIME_DYE : Material.RED_DYE, record.blocked ? "&aGerät serverweit entsperren" : "&cGerät serverweit sperren", "&7Die Geräte-ID wird accountübergreifend", "&7auf dem gesamten Server blockiert."));
        inv.setItem(34, item(Material.REDSTONE, "&bErweiterte Gerätediagnose", "&7"+record.diagnostics.size()+" Zusatzfelder • Login und Sitzung", "&7Hardwareklasse, Grafik, Identitäten und Quelle.", "&7Klick für die vollständige Übersicht."));
        inv.setItem(35, item(Material.SPYGLASS, "&eManueller Account-/Gerätevergleich", "&7Zusätzliche Hinweise getrennt vom Alt-Score."));
        inv.setItem(32, item(Material.LAVA_BUCKET, "&cGerätedatensatz löschen", "&7Löscht nur die Historie dieses Profils.", "&7Globale Geräte-/IP-Sperren bleiben bestehen."));
