    private void handleDeviceDetailClick(Player admin, SuiteMenu menu, int slot) {
        PlayerProfile target = database.get(menu.target);
        DeviceRecord record = altDetection.device(target, menu.history);
        if (target == null || record == null) { openDeviceHistory(admin, menu.target, 0, "ALL", ""); return; }
        if (!require(admin,"simplexadminsuite.alts.identities")) return;
        if (slot == 49) { openDeviceHistory(admin, target.uuid, 0, "ALL", ""); return; }
        if (slot == 34 || slot == 35) { openDeviceDiagnostics(admin,target.uuid,record.id,0,slot==34?"fields":"compare"); return; }
        if (slot == 30 && record.platform.equals("BEDROCK")) {
            confirm(admin, new PendingAction("device-block", target.uuid, record.id, Boolean.toString(!record.blocked)), record.blocked ? "Gerät serverweit entsperren" : "Gerät serverweit sperren", target.name, record.id); return;
        }
        if (slot >= 18 && slot <= 27) {
            List<Map.Entry<String, Long>> recentIps = record.recentIps();
            int index = slot - 18;
            if (index < recentIps.size()) {
                String ip = recentIps.get(index).getKey();
                boolean blocked = altDetection.isIpBlocked(ip);
                confirm(admin, new PendingAction("ip-block", target.uuid, ip, Boolean.toString(!blocked)), blocked ? "IP serverweit entsperren" : "IP serverweit sperren", target.name, ip);
            }
            return;
        }
        if (slot == 32) confirm(admin, new PendingAction("device-delete", target.uuid, record.id, ""), "Gerätedatensatz löschen", target.name, record.id);
    }

    private void filterDiagnosticData(Map<String,String> fields) {
        if (!getConfig().getBoolean("device-diagnostics.enabled", true)) { fields.clear(); return; }
        if (!getConfig().getBoolean("device-diagnostics.cosmetics", true)) fields.keySet().removeAll(BedrockMetadata.COSMETICS);
        if (!getConfig().getBoolean("device-diagnostics.party", false)) fields.keySet().removeAll(BedrockMetadata.PARTY);
        if (!getConfig().getBoolean("device-diagnostics.misc", true)) fields.keySet().removeAll(BedrockMetadata.MISC);
    }

    private void captureOfficialAccountLink(Player player, PlayerProfile profile) {
        Plugin floodgate = Bukkit.getPluginManager().getPlugin("floodgate");
        if (floodgate == null) return;
        try {
            Class<?> type = Class.forName("org.geysermc.floodgate.api.FloodgateApi", true, floodgate.getClass().getClassLoader());
            Object api = type.getMethod("getInstance").invoke(null);
            Object bedrock = type.getMethod("getPlayer", UUID.class).invoke(api, player.getUniqueId());
            Object linked = BedrockMetadata.call(bedrock, "getLinkedPlayer");
            if (linked == null) return;
            String uuid = BedrockMetadata.read(linked, "getJavaUniqueId");
            if (!uuid.isBlank()) {
                UUID linkedId=UUID.fromString(uuid);
                if(securityHub!=null)try { if(securityHub.overrides.verifiedLink(player.getUniqueId(),linkedId)&&altDetection!=null)altDetection.markMatchCacheDirty(); }catch(java.io.IOException failure){getLogger().warning("Authentifizierte Account-Verknüpfung konnte nicht gespeichert werden");}
                profile.bedrockDiagnostics.put("linkedJavaUuid", uuid);
                String name = BedrockMetadata.read(linked, "getJavaUsername");
                if (!name.isBlank()) profile.bedrockDiagnostics.put("linkedJavaName", BedrockMetadata.clean(name));
            }
        } catch (ReflectiveOperationException | RuntimeException | LinkageError ignored) { }
    }

    void clientSecurityUpdateDiagnostics(Player player, PlayerProfile profile, Collection<String> channels) {
        if (player == null || profile == null || isBedrockClient(player) || !getConfig().getBoolean("device-diagnostics.java-options", true)) return;
        Map<String,String> fields = DeviceDiagnostics.javaOptions(player);
        fields.put("channelCount", Integer.toString(channels.size()));
        fields.put("channelSignature", DeviceDiagnostics.channelSignature(channels));
        fields.put("channelNamespaces", BedrockMetadata.clean(channels.stream().map(c -> c.contains(":") ? c.substring(0,c.indexOf(':')) : c).distinct().sorted().limit(40).collect(Collectors.joining(", "))));
        DeviceDiagnostics.merge(profile.javaDiagnostics, fields);
        if (altDetection != null) altDetection.updateJavaDeviceRecord(profile);
    }
    String clientSecurityDiagnosticsText(PlayerProfile profile) {
        return profile == null ? "Profil nicht gefunden." : String.join("\n", DeviceDiagnostics.lines(profile.javaDiagnostics))+("JAVA".equals(profile.clientPlatformValue())?"\n"+clientProbeData(profile.uniqueId()):"");
    }
    static final List<String> DIAGNOSTIC_SETTINGS = List.of("enabled","cosmetics","party","misc","session-refresh","java-options","comparisons");
    static String diagnosticSettingLabel(String setting) {
        return switch(setting) { case "enabled" -> "Bedrock-Zusatzdaten"; case "cosmetics" -> "Skin- und Profil-Metadaten"; case "party" -> "Party-Metadaten"; case "misc" -> "Editor- und Filter-Metadaten"; case "session-refresh" -> "Bedrock-Sitzungsaktualisierung"; case "java-options" -> "Java-Client-Einstellungen"; case "comparisons" -> "Manuelle Gerätevergleiche"; default -> setting; };
    }
    boolean diagnosticSettingEnabled(String setting) { return getConfig().getBoolean("device-diagnostics."+setting, !setting.equals("party")); }
    String setDiagnosticSetting(String actor, String setting, String value) {
        if (setting == null || setting.isBlank() || setting.equals("status")) return diagnosticSettingsText();
        if (!DIAGNOSTIC_SETTINGS.contains(setting)) return "Unbekannte Einstellung. Optionen: " + String.join(", ", DIAGNOSTIC_SETTINGS);
        if (!List.of("on","off","true","false").contains(value.toLowerCase(Locale.ROOT))) return "Nutze on oder off.";
        boolean active = value.equalsIgnoreCase("on") || value.equalsIgnoreCase("true");
        getConfig().set("device-diagnostics."+setting, active); saveConfig();
        audit.log(actor, null, "Gerätediagnose eingestellt", setting+"="+active);
        return diagnosticSettingsText();
    }
    String diagnosticSettingsText() {
        StringBuilder result = new StringBuilder("Gerätediagnose • Zusatzdaten ändern keine Alt-Scores oder automatischen Sperren.\n");
        for(String key:DIAGNOSTIC_SETTINGS) result.append(diagnosticSettingLabel(key)).append(": ").append(diagnosticSettingEnabled(key)?"AN":"AUS").append("\n");
        return result.append("Brücke übernimmt Einstellungen beim nächsten Heartbeat (bis zu 60 s); lokale Bridge-Abschaltungen bleiben vorrangig. Bereits gespeicherte Daten bleiben erhalten.").toString();
    }
    private boolean handleDeviceInfoCommand(CommandSender sender, String[] args) {
        if (!has(sender,"simplexadminsuite.alts.identities")) return deny(sender,"simplexadminsuite.alts.identities");
        if (args.length<2) return usage(sender,"/sas deviceinfo <Spieler|UUID> [Geräte-ID]");
        PlayerProfile profile = database.find(args[1]);
        if (profile == null) { sender.sendMessage(prefix()+"Spielerprofil nicht gefunden."); return true; }
        DeviceRecord record = selectDiagnosticDevice(profile,args.length>2?args[2]:"");
        if (record == null) { sender.sendMessage(prefix()+"Noch kein Geräteprofil gespeichert."); return true; }
        if (sender instanceof Player) openDeviceDiagnostics((Player)sender,profile.uuid,record.id,0,"fields");
        else for(String line:DeviceDiagnostics.lines(record.diagnostics)) sender.sendMessage(line);
        return true;
    }
    private DeviceRecord selectDiagnosticDevice(PlayerProfile profile, String id) {
        if (profile == null || altDetection == null) return null;
        if (id != null && !id.isBlank()) return altDetection.device(profile,id);
        return profile.devices.values().stream().max(Comparator.comparingLong(d -> d.lastSeen)).orElse(null);
    }
    private void openDeviceDiagnostics(Player admin, UUID uuid, String id, int requestedPage, String mode) {
        if (!adminMenuAllowed(admin,"suite.devicediagnostics") || !require(admin,"simplexadminsuite.alts.identities")) return;
        PlayerProfile profile=database.get(uuid); DeviceRecord record=altDetection.device(profile,id);
        if(profile==null||record==null) { openDeviceHistory(admin,uuid,0,"ALL",""); return; }
        if(consumeBedrockMenu(admin,()->bedrockMenus.openDeviceDiagnostics(admin,uuid,id,requestedPage,mode))) return;
        List<String> lines=diagnosticPageLines(profile,record,mode);
        int page=Math.max(0,Math.min(Math.max(0,(lines.size()-1)/36),requestedPage));
        Inventory inventory=LiveMenus.create(new SuiteMenu("device-extra",uuid,page,id,mode),54,color("&8Gerätediagnose: &f"+profile.name));
        fill(inventory);
        for(int i=page*36;i<Math.min(lines.size(),page*36+36);i++) {
            String line=lines.get(i); int colon=line.indexOf(':'); String label=colon<0?line:line.substring(0,colon);
            List<String> lore=splitLore(colon<0?line:line.substring(colon+1).trim());
            inventory.setItem(i-page*36,item(mode.equals("compare")?Material.SPYGLASS:diagnosticIcon(line),"&b"+shortenText(label,48),lore));
        }
        inventory.setItem(36,item(Material.WRITABLE_BOOK,"&eQuelle und Aktualität","&7Erfasst: &f"+time(DeviceDiagnostics.observed(record.diagnostics)),"&7Nicht erneut gemeldete Werte sind als historisch markiert.","&7Fehlende Felder werden nicht erfunden.","&cClientangaben sind keine Hardware-Bestätigung."));
        inventory.setItem(45,item(Material.ARROW,"&eVorherige Seite"));
        inventory.setItem(46,item(Material.COMPASS,"&bZusatzfelder"));
        inventory.setItem(47,item(Material.SPYGLASS,"&eManuell vergleichen","&7Netzwerk, Geräteprofil und offizielle Account-Verknüpfung.","&cKeine automatische Alt-Zuordnung oder Score-Änderung."));
        inventory.setItem(48,item(Material.CLOCK,"&dProfilverlauf","&7Bis zu acht Änderungen wichtiger Zusatzfelder."));
        inventory.setItem(49,item(Material.BARRIER,"&cZurück zu Gerätedetails"));
        inventory.setItem(51,item(Material.COMPARATOR,"&bErfassungseinstellungen","&7Öffnet die Java-/Bedrock-Diagnoseeinstellungen."));
        inventory.setItem(53,item(Material.ARROW,"&eNächste Seite"));
        LiveMenus.show(admin,inventory);
    }
    private Material diagnosticIcon(String line) {
        if(line.contains("Speicher")||line.contains("Sichtweite")) return Material.REDSTONE;
        if(line.contains("Grafik")||line.contains("Skin")||line.contains("Cape")||line.contains("Persona")) return Material.ENDER_EYE;
        if(line.contains("Join")||line.contains("Protokoll")) return Material.COMPASS;
        if(line.contains("ID")||line.contains("UUID")||line.contains("Format")) return Material.NAME_TAG;
        return Material.PAPER;
    }
    private List<String> diagnosticPageLines(PlayerProfile profile,DeviceRecord record,String mode) {
        if(mode.equals("compare")) return manualDeviceComparisons(profile,record);
        if(mode.equals("history")) {
            List<String> result=new ArrayList<>();
            for(int i=record.diagnosticHistory.size()-1;i>=0;i--) {
                Map<String,String> data=DeviceDiagnostics.decode(record.diagnosticHistory.get(i));
                result.add("Profilstand: "+time(DeviceDiagnostics.observed(data)));
                for(String key:List.of("memoryTier","maxViewDistance","platformType","loginGraphicsMode","profileHash","skinId","javaBrand","channelSignature")) if(data.containsKey(key)) result.add(DeviceDiagnostics.LABELS.get(key)+": "+data.get(key));
            }
            if(result.isEmpty()) result.add("Verlauf: Noch keine Änderungen wichtiger Zusatzfelder erfasst.");
            return result;
        }
        List<String> lines=new ArrayList<>(DeviceDiagnostics.lines(record.diagnostics));
        if(record.platform.equals("BEDROCK")) {
            lines.add("Live-Grafikmodus: Nur angezeigt, wenn Geyser ihn tatsächlich bereitstellt; sonst bleibt nur der Loginwert.");
            lines.add("TitleID / Microsoft-DeviceConfig: Durch die aktuelle Geyser-Extension-API nicht verfügbar.");
        } else lines.add("Java-Gerät: OS, CPU, RAM, MAC und Geräte-ID werden von Java Edition nicht übermittelt.");
        return lines;
    }
    private List<String> manualDeviceComparisons(PlayerProfile source,DeviceRecord record) {
        List<String> result=new ArrayList<>();
        if(!diagnosticSettingEnabled("comparisons")) return List.of("Vergleich: In den Erfassungseinstellungen deaktiviert.");
        result.add("Manuelle Prüfung: Übereinstimmungen sind Hinweise. Gemeinsame IPs und Geräteprofile beweisen keinen gemeinsamen Besitzer.");
        int count=0;
        for(PlayerProfile other:database.sortedProfiles()) {
            if(other.uuid.equals(source.uuid)) continue;
            LinkedHashSet<String> reasons=new LinkedHashSet<>();
            String linked=source.bedrockDiagnostics.getOrDefault("linkedJavaUuid","");
            if(linked.equals(other.uuid.toString())||other.bedrockDiagnostics.getOrDefault("linkedJavaUuid","").equals(source.uuid.toString())) reasons.add("gespeicherte offizielle Floodgate-Account-Verknüpfung");
            for(DeviceRecord candidate:other.devices.values()) {
                boolean same=record.platform.equals(candidate.platform);
                if(record.platform.equals("BEDROCK")&&candidate.platform.equals("BEDROCK")&&record.id.equals(candidate.id)) reasons.add("gleiche gemeldete Bedrock-Geräte-ID (bestehendes Signal)");
                if(!record.lastIp.isBlank()&&(record.lastIp.equals(candidate.lastIp)||candidate.ipHistory.containsKey(record.lastIp))) reasons.add("gemeinsame Netzwerkadresse (kein Gerätenachweis)");
                List<String> overlap=DeviceDiagnostics.overlap(record.diagnostics,candidate.diagnostics,same);
                boolean identifierMatch=List.of("platformUserId","profileHash").stream().anyMatch(k -> record.diagnostics.containsKey(k) && !record.diagnostics.get(k).isBlank() && !record.diagnostics.get(k).equals("0") && record.diagnostics.get(k).equals(candidate.diagnostics.get(k)));
                boolean modelMatch=same && record.platform.equals("BEDROCK") && !record.model.isBlank() && record.model.equals(candidate.model) && record.os.equals(candidate.os) && overlap.size()>=3;
                boolean channelMatch=same && record.platform.equals("JAVA") && source.javaRegisteredChannelsSnapshot().size()>=6 && other.javaRegisteredChannelsSnapshot().size()>=6 && record.diagnostics.containsKey("channelSignature") && record.diagnostics.get("channelSignature").equals(candidate.diagnostics.get("channelSignature"));
                if(!overlap.isEmpty() && (identifierMatch || modelMatch || channelMatch)) reasons.add("gemeinsame Zusatzfelder ["+String.join(", ",overlap)+"] (veränderlich/unverifiziert)");
            }
            if(!reasons.isEmpty()) { result.add(other.name+" ["+other.clientPlatform+"]: "+String.join("; ",reasons)); if(++count>=40) { result.add("Anzeige: Auf 40 Profile begrenzt; kein Score und keine automatische Verknüpfung."); break; } }
        }
        if(count==0) result.add("Ergebnis: Keine zusätzlichen Übereinstimmungen in den gespeicherten Profilen.");
        return result;
    }

    private String deviceIpText(DeviceRecord record) {
        if (record == null || record.ipHistory.isEmpty()) return "Keine";
        return record.recentIps().stream().map(Map.Entry::getKey).limit(10).collect(Collectors.joining(" | "));
    }

    private String deviceTitle(DeviceRecord record) {
        if (!record.model.isBlank()) return record.model;
        return record.platform.equals("BEDROCK") ? "Bedrock-Gerät" : "Java-Clientprofil";
    }

    private String normalizeDeviceFilter(String filter) {
        String value = filter == null ? "ALL" : filter.toUpperCase(Locale.ROOT);
        return Arrays.asList("ALL", "BEDROCK", "JAVA", "BLOCKED").contains(value) ? value : "ALL";
    }

    private String nextDeviceFilter(String filter) {
        String value = normalizeDeviceFilter(filter);
        if (value.equals("ALL")) return "BEDROCK";
        if (value.equals("BEDROCK")) return "JAVA";
        if (value.equals("JAVA")) return "BLOCKED";
        return "ALL";
    }

    private String deviceFilterLabel(String filter) {
        String value = normalizeDeviceFilter(filter);
        if (value.equals("BEDROCK")) return "Nur Bedrock";
        if (value.equals("JAVA")) return "Nur Java";
        if (value.equals("BLOCKED")) return "Nur gesperrte Geräte";
        return "Alle Geräte";
    }

