    private void handleSecuritySettingsClick(Player admin, int slot) {
        if (!require(admin, "simplexadminsuite.security")) return;
        if (slot == 31) { openServerControls(admin); return; }
        if (slot == 20) { startOwnPasswordChange(admin); return; }
        if (slot == 24) {
            if (!admin.isOp()) admin.sendMessage(prefix() + "Nur echte Server-Operatoren dürfen Passwörter anderer Admins verwalten.");
            else openPasswordAdmins(admin, 0);
            return;
        }
        if (!admin.isOp()) { admin.sendMessage(prefix() + "Nur echte Server-Operatoren dürfen die globale Admin-Sicherheit verändern."); return; }
        if (slot == 11) {
            getConfig().set("admin-security.enabled", !getConfig().getBoolean("admin-security.enabled", true)); saveConfig(); adminSecurity.reload(); openSecuritySettings(admin);
        } else if (slot == 13) {
            int current = getConfig().getInt("admin-security.max-attempts", 3); int next = current >= 5 ? 3 : current + 1;
            getConfig().set("admin-security.max-attempts", next); saveConfig(); adminSecurity.reload(); openSecuritySettings(admin);
        } else if (slot == 15) {
            long current = getConfig().getLong("admin-security.timeout-seconds", 90L); long next = current < 90 ? 90 : current < 120 ? 120 : current < 180 ? 180 : 60;
            getConfig().set("admin-security.timeout-seconds", next); saveConfig(); adminSecurity.reload(); openSecuritySettings(admin);
        }
    }

    private void openPasswordAdmins(Player operator, int requestedPage) {
        if (operator == null || !operator.isOp() || !require(operator, "simplexadminsuite.security")) return;
        List<StaffMember> members = staffWorkspace.members();
        List<UUID> view = members.stream().map(member -> member.uuid)
                .filter(uuid -> !operator.getUniqueId().equals(uuid)).collect(Collectors.toList());
        passwordAdminViews.put(operator.getUniqueId(), view);
        int maxPage = Math.max(0, (view.size() - 1) / 45);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("password-admins", null, page, null, null), 54, color("&8Admin-Passwörter"));
        fillBottom(inv, page, maxPage);
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zur Admin-Sicherheit."));
        for (int slot = 0; slot < 45; slot++) {
            int index = page * 45 + slot;
            if (index >= view.size()) break;
            UUID uuid = view.get(index);
            PlayerProfile profile = database.get(uuid);
            if (profile == null) continue;
            StaffMember member = null;
            for (StaffMember candidate : members) if (uuid.equals(candidate.uuid)) { member = candidate; break; }
            String source = member == null ? "Admin" : member.source;
            inv.setItem(slot, playerHead(profile, "&e" + profile.name,
                    "&7Zugriff: &f" + source,
                    "&7Passwort: &f" + (adminSecurity.hasPersonalPassword(uuid) ? "Persönlich" : "Allgemein"),
                    "&7Klick zum Verwalten."));
        }
        LiveMenus.show(operator,inv);
    }

    private void handlePasswordAdminsClick(Player operator, SuiteMenu menu, int slot) {
        if (!operator.isOp()) return;
        if (slot == 45 && menu.page > 0) { openPasswordAdmins(operator, menu.page - 1); return; }
        if (slot == 53) { openPasswordAdmins(operator, menu.page + 1); return; }
        if (slot == 49) { openSecuritySettings(operator); return; }
        if (slot < 0 || slot >= 45) return;
        List<UUID> view = passwordAdminViews.getOrDefault(operator.getUniqueId(), Collections.emptyList());
        int index = menu.page * 45 + slot;
        if (index < view.size()) openPasswordDetail(operator, view.get(index));
    }

