    private void handleAfkSettingsClick(Player admin, int slot) {
        if (!require(admin, "simplexadminsuite.afk")) return;
        if (slot == 31) { openServerControls(admin); return; }
        if (slot == 10) getConfig().set("afk.enabled", !getConfig().getBoolean("afk.enabled", true));
        else if (slot == 11) { long c=getConfig().getLong("afk.timeout-minutes",5L); getConfig().set("afk.timeout-minutes", c<10?10:c<15?15:c<30?30:5); }
        else if (slot == 12) getConfig().set("afk.show-in-player-list", !getConfig().getBoolean("afk.show-in-player-list", true));
        else if (slot == 13) getConfig().set("afk.show-above-name", !getConfig().getBoolean("afk.show-above-name", true));
        else if (slot == 14) getConfig().set("afk.kick-enabled", !getConfig().getBoolean("afk.kick-enabled", false));
        else if (slot == 15) { long c=getConfig().getLong("afk.kick-after-minutes",30L); getConfig().set("afk.kick-after-minutes", c<60?60:c<120?120:c<240?240:30); }
        else if (slot == 16) { long c=getConfig().getLong("afk.recent-chat-window-minutes",10L); getConfig().set("afk.recent-chat-window-minutes", c<15?15:c<30?30:c<60?60:10); }
        else if (slot == 22) getConfig().set("afk.mention-warning.enabled", !getConfig().getBoolean("afk.mention-warning.enabled", true));
        else { openAfkSettings(admin); return; }
        saveConfig(); audit.log(admin.getName(), admin.getUniqueId(), "AFK-Einstellungen", afk.status());
        menuNotice(admin,prefix() + "Die AFK-Einstellung wurde erfolgreich angewendet.");
        openAfkSettings(admin);
    }

