    private void openOperations(Player admin) {
        if (!adminMenuAllowed(admin, "suite.openoperations")) return;
        if (!require(admin, "simplexadminsuite.operations")) return;
        Inventory inv = LiveMenus.create(new SuiteMenu("operations", null, 0, null, null), 54, color("&8Einsatzleitstelle"));
        fill(inv);
        inv.setItem(4, item(Material.REDSTONE_BLOCK, "&cEinsatzleitstelle", "&7Zentrale Live-Steuerung für Staff.", "&7Öffentliche Systemmeldungen bleiben Englisch."));
        inv.setItem(10, item(Material.CLOCK, "&eChat-Slowmode", "&7Aktuell: &f" + serverControls.slowmodeSeconds() + " Sekunden", "&7Klick wechselt 0/3/5/10/20/30/60."));
        inv.setItem(11, item(serverControls.commandLockdownEnabled() ? Material.REDSTONE_TORCH : Material.COMPARATOR, "&cBefehls-Lockdown", "&7Status: " + (serverControls.commandLockdownEnabled() ? "&cAktiv" : "&aInaktiv"), "&7Nicht-Staff darf nur sichere Whitelist-Befehle nutzen."));
        inv.setItem(12, item(Material.PAPER, "&bÖffentlichen Chat leeren", "&7Sendet Leerzeilen und eine englische Systemmeldung."));
        inv.setItem(13, item(adminSpy.commandSpyEnabled(admin) ? Material.LIME_DYE : Material.GRAY_DYE, "&dBefehls-Spy", "&7Status: " + (adminSpy.commandSpyEnabled(admin) ? "&aAktiv" : "&cInaktiv"), "&7Sensible Passwortbefehle werden niemals gespiegelt."));
        inv.setItem(14, item(duty.active(admin) ? Material.LIME_DYE : Material.GRAY_DYE, "&6Staff-Dienst", "&7Dein Status: " + (duty.active(admin) ? "&aIm Dienst" : "&7Außer Dienst"), "&7Aktive Staff-Mitglieder: &f" + duty.activeCount()));
        inv.setItem(15, item(Material.SPYGLASS, "&eBeobachtungsliste", "&7Einträge: &f" + watchlist.size(), "&7Join-/Quit-Warnungen nur für Staff."));
        inv.setItem(16, item(Material.WRITABLE_BOOK, "&bAutomatische Ankündigungen", "&7Einträge: &f" + announcements.size(), "&7Öffentliche Texte müssen Englisch sein."));
        inv.setItem(19, item(Material.COMPARATOR, "&aServer-Diagnose", "&7Speicher, Profile, Reports, Staff und Modi."));
        inv.setItem(20, item(Material.MAP, "&6Diagnose exportieren", "&7Schreibt einen Zeitstempel-Bericht in", "&fplugins/SimplexAdminSuite/exports/."));
        if (has(admin, "simplexadminsuite.restart")) {
            int configuredRestartSeconds = Math.max(5, Math.min(300, getConfig().getInt("operations.restart.countdown-seconds", 30)));
            inv.setItem(21, item(restartManager.active() ? Material.CLOCK : Material.REDSTONE_BLOCK,
                    restartManager.active() ? "&eServer-Neustart läuft" : "&cServer neu starten",
                    restartManager.active() ? "&7Verbleibend: &f" + restartManager.remainingSeconds() + " Sekunden"
                            : "&7Startet einen bestätigten Countdown.",
                    "&7Öffentliche Meldungen, Titel und Actionbar", "&7bleiben Englisch. Countdown: &f" + configuredRestartSeconds + " Sekunden."));
        }
        inv.setItem(31, item(Material.BARRIER, "&cZurück", "&7Zurück zum Hauptmenü."));
        LiveMenus.show(admin,inv);
    }

    private void handleOperationsClick(Player admin, int slot) {
        if (!require(admin, "simplexadminsuite.operations")) return;
        if (slot == 10) {
            if (!require(admin, "simplexadminsuite.slowmode")) return;
            serverControls.cycleSlowmode(admin.getName());
            openOperations(admin);
        } else if (slot == 11) {
            if (!require(admin, "simplexadminsuite.commandlock")) return;
            serverControls.setCommandLockdown(admin.getName(), !serverControls.commandLockdownEnabled());
            openOperations(admin);
        } else if (slot == 12) {
            if (!require(admin, "simplexadminsuite.chatclear")) return;
            clearPublicChat(admin.getName());
            openOperations(admin);
        } else if (slot == 13) {
            if (!require(admin, "simplexadminsuite.commandspy")) return;
            adminSpy.toggleCommandSpy(admin);
            openOperations(admin);
        } else if (slot == 14) {
            if (!require(admin, "simplexadminsuite.duty")) return;
            duty.toggle(admin);
            openOperations(admin);
        } else if (slot == 15) openWatchlist(admin, 0);
        else if (slot == 16) openAnnouncements(admin, 0);
        else if (slot == 19) openDiagnostics(admin);
        else if (slot == 20) { File file = exportOperationsReport(admin.getName()); menuNotice(admin,prefix() + (file == null ? "Export fehlgeschlagen." : "Export erstellt: " + file.getAbsolutePath())); }
        else if (slot == 21) {
            if (!require(admin, "simplexadminsuite.restart")) return;
            if (restartManager.active()) {
                admin.sendMessage(prefix() + "Ein Neustart-Countdown läuft bereits: noch " + restartManager.remainingSeconds() + " Sekunden.");
                openOperations(admin);
                return;
            }
            int seconds = Math.max(5, Math.min(300, getConfig().getInt("operations.restart.countdown-seconds", 30)));
            confirm(admin, new PendingAction("server-restart", null, Integer.toString(seconds), ""),
                    "Server-Neustart bestätigen", "Gesamter Server",
                    "Nach " + seconds + " Sekunden wird der Paper-Server neu gestartet.");
        }
        else if (slot == 31 || slot == 49) openMain(admin);
    }

    private void clearPublicChat(String actor) {
        for (int i = 0; i < 80; i++) broadcastPublicText(" ");
        broadcastPublicText(prefix() + stripFormatting(getConfig().getString("operations.chat-cleared-message", "Public chat has been cleared by staff.")));
        audit.log(actor, null, "Chat geleert", "Öffentlichen Chat geleert");
    }

    private void openWatchlist(Player admin, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.openwatchlist")) return;
        if (!require(admin, "simplexadminsuite.watchlist")) return;
        List<WatchEntry> entries = watchlist.sorted();
        List<UUID> ids = entries.stream().map(e -> e.uuid).collect(Collectors.toList());
        watchlistViews.put(admin.getUniqueId(), ids);
        int maxPage = Math.max(0, (entries.size() - 1) / 45);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("watchlist", null, page, null, null), 54, color("&8Beobachtungsliste &7Seite " + (page + 1)));
        fillBottom(inv, page, maxPage);
        inv.setItem(48, item(Material.NAME_TAG, "&eSpieler hinzufügen", "&7Öffne ein Spielerprofil und nutze", "&7dort den Beobachtungs-Schalter."));
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zur Einsatzleitstelle."));
        for (int i = 0; i < 45; i++) {
            int index = page * 45 + i; if (index >= entries.size()) break;
            WatchEntry entry = entries.get(index);
            PlayerProfile profile = database.get(entry.uuid);
            inv.setItem(i, item(Bukkit.getPlayer(entry.uuid) == null ? Material.SPYGLASS : Material.REDSTONE_TORCH,
                    "&e" + (profile == null ? entry.lastKnownName : profile.name), "&7Grund: &f" + entry.reason,
                    "&7Hinzugefügt von: &f" + entry.addedBy, "&7Seit: &f" + time(entry.createdAt), "&cKlick zum Entfernen."));
        }
        LiveMenus.show(admin,inv);
    }

    private void handleWatchlistClick(Player admin, SuiteMenu menu, int slot) {
        if (slot == 45 && menu.page > 0) { openWatchlist(admin, menu.page - 1); return; }
        if (slot == 53) { openWatchlist(admin, menu.page + 1); return; }
        if (slot == 49) { openOperations(admin); return; }
        if (slot < 0 || slot >= 45) return;
        List<UUID> view = watchlistViews.getOrDefault(admin.getUniqueId(), Collections.emptyList());
        int index = menu.page * 45 + slot;
        if (index >= view.size()) return;
        UUID uuid = view.get(index); PlayerProfile target = database.get(uuid);
        confirm(admin, new PendingAction("watchlist-remove", uuid, "", ""), "Beobachtung beenden", target == null ? uuid.toString() : target.name, "Eintrag vollständig entfernen?");
    }

