    private void handleAnnouncementDetailClick(Player admin, SuiteMenu menu, int slot) {
        long id; try { id = Long.parseLong(menu.search); } catch (Exception ignored) { openAnnouncements(admin, menu.page); return; }
        if (slot == 11) { announcements.toggle(admin.getName(), id); openAnnouncementDetail(admin, id, menu.page); }
        else if (slot == 13) { announcements.sendNow(admin.getName(), id); openAnnouncementDetail(admin, id, menu.page); }
        else if (slot == 15) confirm(admin, new PendingAction("announcement-delete", null, Long.toString(id), ""), "Ankündigung löschen", "#" + id, "Eintrag unwiderruflich entfernen?");
        else if (slot == 31 || slot == 49) openAnnouncements(admin, menu.page);
    }

    private void openDiagnostics(Player admin) {
        if (!adminMenuAllowed(admin, "suite.opendiagnostics")) return;
        if (!require(admin, "simplexadminsuite.diagnostics")) return;
        Runtime rt = Runtime.getRuntime();
        long used = (rt.totalMemory() - rt.freeMemory()) / 1048576L;
        long max = rt.maxMemory() / 1048576L;
        Inventory inv = LiveMenus.create(new SuiteMenu("diagnostics", null, 0, null, null), 45, color("&8Server-Diagnose"));
        fill(inv);
        inv.setItem(10, item(Material.COMPARATOR, "&aLaufzeitdaten", "&7Online: &f" + Bukkit.getOnlinePlayers().size(), "&7Bedrock: &f" + bedrockMenus.onlineBedrockCount(), "&7Speicher: &f" + used + " / " + max + " MiB"));
        inv.setItem(11, item(Material.BOOKSHELF, "&bDatenbestand", "&7Suite-Profile: &f" + database.sortedProfiles().size(), "&7Historisch erkannte Accounts: &f" + expansion.knownProfileCount(), "&7Watchlist: &f" + watchlist.size(), "&7Ankündigungen: &f" + announcements.size()));
        inv.setItem(12, item(Material.WRITABLE_BOOK, "&cModeration", "&7Offene Reports: &f" + reports.openCount(), "&7Staff im Dienst: &f" + duty.activeCount(), "&7Wartung: " + (maintenance.isActive() ? "&cAktiv" : "&aInaktiv")));
        inv.setItem(13, item(Material.REDSTONE, "&eSchutzmodi", "&7Globaler Chat: " + (serverControls.globalChatEnabled() ? "&aAktiv" : "&cAus"), "&7Slowmode: &f" + serverControls.slowmodeSeconds() + "s", "&7Befehls-Lockdown: " + (serverControls.commandLockdownEnabled() ? "&cAktiv" : "&aAus")));
        inv.setItem(22, item(Material.MAP, "&6Diagnose exportieren", "&7Schreibt einen Bericht in den Export-Ordner."));
        inv.setItem(31, item(Material.BARRIER, "&cZurück", "&7Zurück zur Einsatzleitstelle."));
        LiveMenus.show(admin,inv);
    }

    private String diagnosticsText() {
        Runtime rt = Runtime.getRuntime();
        long used = (rt.totalMemory() - rt.freeMemory()) / 1048576L;
        long max = rt.maxMemory() / 1048576L;
        return "Online=" + Bukkit.getOnlinePlayers().size() + ", Profile=" + database.sortedProfiles().size() + ", Reports=" + reports.openCount()
                + ", Watchlist=" + watchlist.size() + ", Ankündigungen=" + announcements.size() + ", Duty=" + duty.activeCount()
                + ", Speicher=" + used + "/" + max + " MiB, Slowmode=" + serverControls.slowmodeSeconds() + "s, CommandLock=" + serverControls.commandLockdownEnabled();
    }

    private String operationsSummary() { return diagnosticsText() + ", " + serverControls.summary(); }

    private File exportOperationsReport(String actor) {
        try {
            File folder = new File(getDataFolder(), "exports"); if (!folder.exists()) folder.mkdirs();
            String safeStamp = new SimpleDateFormat("yyyyMMdd-HHmmss", Locale.GERMANY).format(new Date());
            File file = new File(folder, "operations-" + safeStamp + ".txt");
            List<String> lines = new ArrayList<>();
            lines.add("Simplex Admin Suite " + VERSION + " - Operations Export");
            lines.add("Created: " + stamp());
            lines.add("Created by: " + actor);
            lines.add("");
            lines.add(diagnosticsText());
            lines.add("Server controls: " + serverControls.summary());
            lines.add("Maintenance: " + maintenance.summary());
            lines.add("Watchlist: " + watchlist.summary());
            lines.add("Announcements: " + announcements.summary());
            lines.add("Duty: " + duty.summary());
            Files.write(file.toPath(), lines, StandardCharsets.UTF_8);
            audit.log(actor, null, "Diagnose exportiert", file.getName());
            return file;
        } catch (Exception error) {
            getLogger().warning("Diagnoseexport fehlgeschlagen: " + error.getMessage());
            return null;
        }
    }

    private List<World> loadedWorldsSorted() {
        List<World> worlds = new ArrayList<>(Bukkit.getWorlds());
        worlds.sort(Comparator.comparing(World::getName, String.CASE_INSENSITIVE_ORDER));
        return worlds;
    }

    private void openWorlds(Player admin) {
        if (!adminMenuAllowed(admin, "suite.openworlds")) return; openWorlds(admin, 0); }
    private void openWorlds(Player admin, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.openworlds")) return;
        if (!require(admin, "simplexadminsuite.worlds")) return;
        List<World> worlds = loadedWorldsSorted();
        List<String> names = worlds.stream().map(World::getName).collect(Collectors.toList());
        worldViews.put(admin.getUniqueId(), names);
        int maxPage = Math.max(0, (worlds.size() - 1) / 45), page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("worlds", null, page, null, null), 54, color("&8Weltenverwaltung &7" + (page + 1) + "/" + (maxPage + 1)));
        fillBottom(inv, page, maxPage);
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zum Hauptmenü."));
        for (int i = 0; i < 45; i++) {
            int index = page * 45 + i; if (index >= worlds.size()) break;
            World world = worlds.get(index);
            inv.setItem(i, item(MenuStyle.dimensionMaterial(world.getEnvironment()), "&a" + world.getName(),
                    "&7Dimension: &f" + world.getEnvironment().name(),
                    "&7Zeit: &f" + worldTimeText(world),
                    "&7Wetter: &f" + worldWeatherText(world),
                    "&7Schlafen: &f" + gameRuleValue(world, "playersSleepingPercentage", "100") + "%",
                    "&eKlick zum Verwalten."));
        }
        if (worlds.isEmpty()) inv.setItem(22, item(Material.BOOK, "&7Keine geladene Welt", "&7Der Server meldet aktuell keine Welten."));
        LiveMenus.show(admin,inv);
    }

    private void handleWorldsClick(Player admin, SuiteMenu menu, int slot) {
        List<String> view = worldViews.getOrDefault(admin.getUniqueId(), Collections.emptyList());
        int maxPage = Math.max(0, (view.size() - 1) / 45);
        if (slot == 45 && menu.page > 0) { openWorlds(admin, menu.page - 1); return; }
        if (slot == 53 && menu.page < maxPage) { openWorlds(admin, menu.page + 1); return; }
        if (slot == 49) { openMain(admin); return; }
        if (slot < 0 || slot >= 45) return;
        int index = menu.page * 45 + slot;
        if (index < view.size()) openWorldDetail(admin, view.get(index));
    }

    private void openWorldDetail(Player admin, String worldName) {
        if (!adminMenuAllowed(admin, "suite.openworlddetail")) return;
        if (!require(admin, "simplexadminsuite.worlds")) return;
        World world = Bukkit.getWorld(worldName);
        if (world == null) { menuNotice(admin,prefix() + "Die Welt ist nicht mehr geladen."); openWorlds(admin); return; }
        Inventory inv = LiveMenus.create(new SuiteMenu("world-detail", null, 0, worldName, null), 54, color("&8Welt: &f" + worldName));
        fill(inv);
        boolean daylight = Boolean.parseBoolean(gameRuleValue(world, "doDaylightCycle", "true"));
        boolean weatherCycle = Boolean.parseBoolean(gameRuleValue(world, "doWeatherCycle", "true"));
        boolean pvp = worldBoolean(world, "getPVP", true);
        boolean autosave = worldBoolean(world, "isAutoSave", true);
        inv.setItem(4, item(MenuStyle.dimensionMaterial(world.getEnvironment()), "&a" + worldName,
                "&7Dimension: &f" + world.getEnvironment().name(), "&7Zeit: &f" + worldTimeText(world), "&7Wetter: &f" + worldWeatherText(world), takeWorldNotice(admin)));
        inv.setItem(10, item(Material.CLOCK, "&eEchte Uhrzeit setzen", "&7Eingabe als &fHH:mm&7, z. B. 18:30.", "&7Wird automatisch in Minecraft-Ticks umgerechnet."));
        inv.setItem(11, item(daylight ? Material.LIME_DYE : Material.GRAY_DYE, "&eTageslicht-Zyklus", "&7Aktuell: " + (daylight ? "&aAktiv" : "&cAus"), "&7Klick zum Umschalten."));
        inv.setItem(12, item(Material.CLOCK, "&6Zeit-Voreinstellungen", "&7Klick wechselt: Morgen → Mittag → Abend → Nacht."));
        inv.setItem(14, item(Material.RED_BED, "&bSchlafquote", "&7Aktuell: &f" + gameRuleValue(world, "playersSleepingPercentage", "100") + "%", "&7"+WorldSettings.sleepSummary(world), "&eKlick: Voreinstellungen und genaue Anpassung."));
        inv.setItem(15, item(weatherCycle ? Material.LIME_DYE : Material.GRAY_DYE, "&bWetter-Zyklus", "&7Aktuell: " + (weatherCycle ? "&aAktiv" : "&cAus"), "&7Klick zum Umschalten."));
        inv.setItem(16, item(world.isThundering()?Material.LIGHTNING_ROD:world.hasStorm()?Material.WATER_BUCKET:Material.SUNFLOWER, "&bWetter umschalten", "&7Aktuell: &f" + worldWeatherText(world), "&7Klick: Klar → Regen → Gewitter."));
        inv.setItem(19, item(pvp ? Material.IRON_SWORD : Material.SHIELD, "&cPvP in dieser Welt", "&7Aktuell: " + (pvp ? "&aAktiv" : "&cAus"), "&7Klick zum Umschalten."));
        inv.setItem(20, item(autosave ? Material.CHEST : Material.GRAY_DYE, "&6Automatisches Speichern", "&7Aktuell: " + (autosave ? "&aAktiv" : "&cAus"), "&7Klick zum Umschalten."));
        inv.setItem(22, item(Material.COMPARATOR, "&dAlle Gamerules", "&7Live aus dieser Welt gelesen.", "&7Boolean- und Zahlenwerte bearbeitbar."));
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zur Weltenauswahl."));
        LiveMenus.show(admin,inv);
    }

    private void handleWorldDetailClick(Player admin, SuiteMenu menu, int slot) {
        String worldName = menu.history;
        World world = Bukkit.getWorld(worldName);
        if (world == null) { menuNotice(admin,prefix() + "Die Welt ist nicht mehr geladen."); openWorlds(admin); return; }
        if (slot == 49) { openWorlds(admin); return; }
        if(!worldEditable(admin,world))return;
        if (slot == 10) { ask(admin, null, "world-time", "Gib die echte Uhrzeit als HH:mm ein, z. B. 18:30. 'abbrechen' beendet die Eingabe.", worldName); return; }
        if (slot == 11) changeRule(admin,world,"doDaylightCycle",Boolean.toString(!Boolean.parseBoolean(gameRuleValue(world,"doDaylightCycle","true"))));
        else if(slot==12)cycleWorldTime(admin,world);
        else if(slot==14){openSleepingSettings(admin,world);return;}
        else if(slot==15)changeRule(admin,world,"doWeatherCycle",Boolean.toString(!Boolean.parseBoolean(gameRuleValue(world,"doWeatherCycle","true"))));
        else if(slot==16)cycleWeather(admin,world);
        else if(slot==19)changeWorldBoolean(admin,world,"getPVP","setPVP","PvP");
        else if(slot==20)changeWorldBoolean(admin,world,"isAutoSave","setAutoSave","Automatisches Speichern");
        else if(slot==22){openGameRules(admin,worldName,0);return;}
        else return;
        openWorldDetail(admin, worldName);
    }

    private void openSleepingSettings(Player admin,World world){
        if(!worldEditable(admin,world))return;
        List<AdminUpdateMenu.Button> items=new ArrayList<>();
        items.add(new AdminUpdateMenu.Button("Aktuelle Schlafquote",WorldSettings.sleepSummary(world),Material.RED_BED,()->openSleepingSettings(admin,world)));
        for(int percent:new int[]{0,10,25,50,75,100,101})items.add(new AdminUpdateMenu.Button(percent>100?"Nacht überspringen aus":percent+" %",percent==0?"Mindestens ein schlafender Spieler":percent>100?"Quote über 100 %":"Anteil der berücksichtigten Spieler",Material.RED_BED,()->{changeRule(admin,world,"playersSleepingPercentage",Integer.toString(percent));openSleepingSettings(admin,world);}));
        for(int delta:new int[]{-10,-1,1,10})items.add(new AdminUpdateMenu.Button((delta>0?"+":"")+delta+" Prozentpunkte","Aktuellen Wert anpassen",Material.COMPARATOR,()->{int current=parseInt(gameRuleValue(world,"playersSleepingPercentage","100"),100);long next=Math.max(0L,Math.min(Integer.MAX_VALUE,(long)current+delta));changeRule(admin,world,"playersSleepingPercentage",Long.toString(next));openSleepingSettings(admin,world);}));
        items.add(new AdminUpdateMenu.Button("Genauen Wert eingeben","0–100 %; über 100 % deaktiviert das Überspringen",Material.NAME_TAG,()->adminUpdate.prompt(admin,"Schlafquote in Prozent",gameRuleValue(world,"playersSleepingPercentage","100"),v->{changeRule(admin,world,"playersSleepingPercentage",v);openSleepingSettings(admin,world);})));
        items.add(AdminUpdateMenu.info("Letzte Änderung",takeWorldNotice(admin),Material.PAPER));
        items.add(new AdminUpdateMenu.Button("Zurück","Weltverwaltung",Material.ARROW,()->openWorldDetail(admin,world.getName())));
        adminUpdate.show(admin,"Schlafquote: "+world.getName(),items,0);
    }

    private void openGameRules(Player admin, String worldName, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.opengamerules")) return;
        if (!require(admin, "simplexadminsuite.worlds")) return;
        World world = Bukkit.getWorld(worldName); if (world == null) { openWorlds(admin); return; }
        List<String> rules = worldGameRules(world); gameRuleViews.put(admin.getUniqueId(), rules);
        int maxPage = Math.max(0, (rules.size() - 1) / 45), page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("gamerules", null, page, worldName, null), 54, color("&8Gamerules: &f" + worldName));
        fillBottom(inv, page, maxPage);
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zur Welt."));
        inv.setItem(48,item(Material.PAPER,"&eLetzte Änderung",takeWorldNotice(admin)));
        for (int i = 0; i < 45; i++) {
            int index = page * 45 + i; if (index >= rules.size()) break;
            String rule = rules.get(index), value = gameRuleValue(world, rule, "?");
            inv.setItem(i, item(value.equalsIgnoreCase("true") ? Material.LIME_DYE : value.equalsIgnoreCase("false") ? Material.RED_DYE : Material.COMPARATOR,
                    "&d" + rule, "&7Live-Wert: &f" + value,
                    value.equalsIgnoreCase("true") || value.equalsIgnoreCase("false") ? "&eKlick zum Umschalten." : "&eKlick zum Bearbeiten."));
        }
        LiveMenus.show(admin,inv);
    }

    private void handleGameRulesClick(Player admin, SuiteMenu menu, int slot) {
        String worldName = menu.history; World world = Bukkit.getWorld(worldName); if (world == null) { openWorlds(admin); return; }
        List<String> rules = gameRuleViews.getOrDefault(admin.getUniqueId(), Collections.emptyList());
        int maxPage = Math.max(0, (rules.size() - 1) / 45);
        if (slot == 45 && menu.page > 0) { openGameRules(admin, worldName, menu.page - 1); return; }
        if (slot == 53 && menu.page < maxPage) { openGameRules(admin, worldName, menu.page + 1); return; }
        if (slot == 49) { openWorldDetail(admin, worldName); return; }
        if (slot < 0 || slot >= 45) return;
        int index = menu.page * 45 + slot; if (index >= rules.size()) return;
        String rule = rules.get(index), current = gameRuleValue(world, rule, "");
        if (current.equalsIgnoreCase("true") || current.equalsIgnoreCase("false")) {
            String next = Boolean.toString(!Boolean.parseBoolean(current));
            changeRule(admin,world,rule,next);
            openGameRules(admin, worldName, menu.page);
        } else ask(admin, null, "gamerule-value", "Neuen Wert für " + rule + " eingeben. Aktuell: " + current + ". 'abbrechen' beendet die Eingabe.", worldName + "\n" + rule + "\n" + menu.page);
    }

    private String worldTimeText(World world) {
        long ticks = ((worldLong(world, "getTime", 0L) % 24000L) + 24000L) % 24000L;
        int minutes = (int) ((ticks * 60L / 1000L + 360L) % 1440L);
        return String.format(Locale.GERMANY, "%02d:%02d", minutes / 60, minutes % 60);
    }

    private boolean changeWorldTime(Player admin,World world,String value){
        if(!worldEditable(admin,world)){worldFeedback(admin,"Weltzeit",false,false);return false;}
        String before=worldTimeText(world);boolean ok=setWorldRealTime(world,value);
        worldFeedback(admin,ok?"Weltzeit: "+worldTimeText(world):"Weltzeit (HH:mm erforderlich oder Änderung abgelehnt)",ok,ok&&before.equals(worldTimeText(world)));
        return ok;
    }
    private boolean setWorldRealTime(World world, String value) {
        Matcher matcher = Pattern.compile("^(\\d{1,2}):(\\d{2})$").matcher(value == null ? "" : value.trim());
        if (!matcher.matches()) return false;
        int hour = parseInt(matcher.group(1), -1), minute = parseInt(matcher.group(2), -1);
        if (hour < 0 || hour > 23 || minute < 0 || minute > 59) return false;
        int realMinutes = hour * 60 + minute;
        long ticks = ((realMinutes - 360 + 1440) % 1440) * 1000L / 60L;
        try { if(Bukkit.getWorld(world.getUID())!=world)return false;world.setTime(ticks);return world.getTime()%24000L==ticks; }
        catch (Throwable ignored) { return false; }
    }

    private String worldWeatherText(World world) {
        if (worldBoolean(world, "isThundering", false)) return "Gewitter";
        if (worldBoolean(world, "hasStorm", false)) return "Regen";
        return "Klar";
    }

    private List<String> worldGameRules(World world) { return WorldSettings.names(); }
    private String gameRuleValue(World world,String rule,String fallback) { return WorldSettings.value(world,rule,fallback); }
    private boolean setGameRule(World world,String rule,String value) { return WorldSettings.set(world,rule,value); }
    private boolean changeRule(Player admin,World world,String rule,String value){
        if(!adminMenuAllowed(admin,"suite.world-change")||!require(admin,"simplexadminsuite.worlds"))return false;
        String before=gameRuleValue(world,rule,"");
        org.bukkit.GameRule<?> typed=WorldSettings.resolve(rule);
        if(typed==null||before.isBlank()){worldFeedback(admin,"Gamerule "+rule+" nicht verfügbar",false,false);return false;}
        try{value=String.valueOf(WorldSettings.parse(typed.getType(),value));}catch(IllegalArgumentException error){worldFeedback(admin,"Ungültiger Wert für "+rule,false,false);return false;}
        if(Bukkit.getWorld(world.getUID())!=world){worldFeedback(admin,"Gamerule "+rule,false,false);return false;}
        if(before.equalsIgnoreCase(value.trim())){worldFeedback(admin,"Gamerule "+rule+" = "+before,true,true);return true;}
        boolean ok=setGameRule(world,rule,value);
        worldFeedback(admin,"Gamerule "+rule+" = "+gameRuleValue(world,rule,"unbekannt"),ok,false);
        audit.log(admin.getName(),null,ok?"Gamerule geändert":"Gamerule abgelehnt",world.getName()+" | "+rule+"="+value);
        return ok;
    }
    private final Map<UUID,String> worldNotices=new HashMap<>();
    private String takeWorldNotice(Player admin){return worldNotices.getOrDefault(admin.getUniqueId(),"");}
    private void worldFeedback(Player admin,String detail,boolean ok,boolean unchanged){
        if(menuFeedback!=null){if(ok)menuFeedback.success(admin.getName());else menuFeedback.failure(admin.getName());}
        String text=!ok?"§cFehlgeschlagen: "+detail+". Der gewünschte Zustand wurde nicht bestätigt.":unchanged?"§eUnverändert: "+detail+".":"§aÜbernommen: "+detail+".";
        admin.sendMessage(prefix()+text);
        worldNotices.put(admin.getUniqueId(),text);
        audit.log(admin.getName(),null,"Weltenverwaltung",stripFormatting(text));
    }
    private boolean worldEditable(Player admin,World world){return adminMenuAllowed(admin,"suite.world-change")&&require(admin,"simplexadminsuite.worlds")&&world!=null&&Bukkit.getWorld(world.getUID())==world;}
    private void changeWorldBoolean(Player admin,World world,String getter,String setter,String label){
        if(!worldEditable(admin,world)){worldFeedback(admin,label,false,false);return;}
        boolean next=!worldBoolean(world,getter,true);
        try{World.class.getMethod(setter,boolean.class).invoke(world,next);worldFeedback(admin,label+": "+(next?"aktiv":"aus"),worldBoolean(world,getter,!next)==next,false);}
        catch(ReflectiveOperationException|RuntimeException error){worldFeedback(admin,label,false,false);}
    }
    private void cycleWeather(Player admin,World world){
        if(!worldEditable(admin,world)){worldFeedback(admin,"Wetter",false,false);return;}
        boolean storm=world.hasStorm(),thunder=world.isThundering();
        boolean nextStorm=!storm||!thunder,nextThunder=storm&&!thunder;
        try{world.setStorm(nextStorm);world.setThundering(nextThunder);worldFeedback(admin,"Wetter: "+worldWeatherText(world),world.hasStorm()==nextStorm&&world.isThundering()==nextThunder,false);}
        catch(RuntimeException error){worldFeedback(admin,"Wetter",false,false);}
    }
    private void cycleWorldTime(Player admin,World world){
        if(!worldEditable(admin,world)){worldFeedback(admin,"Weltzeit",false,false);return;}
        long now=world.getTime()%24000L,next=now<6000L?6000L:now<12000L?12000L:now<18000L?18000L:0L;
        try{world.setTime(next);worldFeedback(admin,"Weltzeit: "+worldTimeText(world),world.getTime()%24000L==next,false);}
        catch(RuntimeException error){worldFeedback(admin,"Weltzeit",false,false);}
    }

    private long worldLong(World world, String method, long fallback) {
        try { Object value = world.getClass().getMethod(method).invoke(world); return value instanceof Number ? ((Number) value).longValue() : fallback; }
        catch (Throwable ignored) { return fallback; }
    }

    private boolean worldBoolean(World world, String method, boolean fallback) {
        try { Object value = world.getClass().getMethod(method).invoke(world); return value instanceof Boolean ? (Boolean) value : fallback; }
        catch (Throwable ignored) { return fallback; }
    }

    private Object worldInvoke(World world, String method, Class<?>[] types, Object... args) {
        try { return world.getClass().getMethod(method, types).invoke(world, args); }
        catch (Throwable ignored) { return null; }
    }

    private int parseInt(String value, int fallback) { try { return Integer.parseInt(value.trim()); } catch (Exception ignored) { return fallback; } }

    private void openPublicWarps(Player player) { openPublicWarps(player, 0); }
    private void openPublicWarps(Player player, int requestedPage) {
        List<WarpPoint> list = warps.enabledSorted();
        publicWarpViews.put(player.getUniqueId(), list.stream().map(w -> w.id).collect(Collectors.toList()));
        int maxPage = Math.max(0, (list.size() - 1) / 45), page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("warps-public", null, page, null, null), 54, color("&8Server Warps"));
        fillBottom(inv, page, maxPage); inv.setItem(49, item(Material.BARRIER, "&cClose", "&7Close the warp menu."));
        for (int i = 0; i < 45; i++) {
            int index = page * 45 + i; if (index >= list.size()) break; WarpPoint warp = list.get(index);
            inv.setItem(i, item(warpIcon(warp), "&b" + warp.displayName, "&7" + warp.description, "&7Dimension: &f" + warp.dimension(), "&7Priority: &f" + warp.priority, "&eClick to teleport."));
        }
        if (list.isEmpty()) inv.setItem(22, item(Material.BOOK, "&7No server warps available", "&7Staff can add warps from the admin menu."));
        LiveMenus.show(player,inv);
    }

    private void handlePublicWarpsClick(Player player, SuiteMenu menu, int slot) {
        List<String> view = publicWarpViews.getOrDefault(player.getUniqueId(), Collections.emptyList()); int maxPage = Math.max(0, (view.size() - 1) / 45);
        if (slot == 45 && menu.page > 0) { openPublicWarps(player, menu.page - 1); return; }
        if (slot == 53 && menu.page < maxPage) { openPublicWarps(player, menu.page + 1); return; }
        if (slot == 49) { player.closeInventory(); return; }
        if (slot < 0 || slot >= 45) return; int index = menu.page * 45 + slot;
        if (index < view.size()) warps.teleport(player, view.get(index));
    }

