        inv.setItem(11, item(Material.COMPASS, "&ePosition aktualisieren", "&7Speichert deinen aktuellen Ort", "&7inklusive Welt/Dimension und Blickrichtung."));
        inv.setItem(12, item(Material.COMPARATOR, "&6Priorität ändern", "&7Aktuell: &f" + warp.priority, "&7Kleinere Werte stehen weiter oben."));
        inv.setItem(14, item(Material.WRITABLE_BOOK, "&bText bearbeiten", "&7Eingabe: Anzeigename | englische Beschreibung"));
