    private void handleWarpDetailClick(Player admin, SuiteMenu menu, int slot) {
        String id = menu.history; WarpPoint warp = warps.get(id); if (warp == null) { openWarpsAdmin(admin, menu.page); return; }
        if (slot == 40) { openWarpsAdmin(admin, menu.page); return; }
        if (slot == 10) { warps.teleport(admin, id); return; }
        if (slot == 11) { warps.updateLocation(id, admin.getLocation(), admin.getName()); menuNotice(admin,prefix() + "Die Position des Warps wurde erfolgreich aktualisiert."); openWarpDetail(admin, id, menu.page); return; }
        if (slot == 12) { ask(admin, null, "warp-priority", "Neue ganzzahlige Priorität eingeben. Kleinere Werte stehen weiter oben.", id + "\n" + menu.page); return; }
        if (slot == 14) { ask(admin, null, "warp-text", "Anzeigename | englische Beschreibung eingeben.", id + "\n" + menu.page); return; }
        if (slot == 15) { boolean next = !warp.enabled; warps.setEnabled(id, next, admin.getName()); menuNotice(admin,prefix() + "Der Warp wurde erfolgreich " + (next ? "aktiviert" : "deaktiviert") + "."); openWarpDetail(admin, id, menu.page); return; }
        if (slot == 16) confirm(admin, new PendingAction("delete-warp", null, id, Integer.toString(menu.page)), "Warp löschen", warp.displayName, "Diesen Server-Warp dauerhaft löschen?");
    }

    private Material warpIcon(WarpPoint warp) {
        if (warp == null) return Material.COMPASS;
        String dimension = warp.dimension().toLowerCase(Locale.ROOT);
        if (dimension.contains("nether")) return Material.BLAZE_ROD;
        if (dimension.contains("end")) return Material.ENDER_EYE;
        return Material.COMPASS;
    }

