    private void handleAntiSpamSettingsClick(Player admin, SuiteMenu menu, int slot) {
        if (slot == 40) { openMain(admin); return; }
        if (slot == 4) { antiSpam.setEnabled(!antiSpam.enabled(), admin.getName()); menuNotice(admin,prefix() + "Anti-Spam wurde erfolgreich " + (antiSpam.enabled() ? "aktiviert" : "deaktiviert") + "."); }
        else if (slot == 10) { antiSpam.cycleMinInterval(admin.getName()); menuNotice(admin,prefix() + "Der Mindestabstand wurde erfolgreich auf " + antiSpam.minIntervalMillis() + " ms gesetzt."); }
        else if (slot == 11) { antiSpam.cycleBurstLimit(admin.getName()); menuNotice(admin,prefix() + "Das Burst-Limit wurde erfolgreich auf " + antiSpam.burstLimit() + " gesetzt."); }
        else if (slot == 12) { antiSpam.setDuplicatesEnabled(!antiSpam.duplicatesEnabled(), admin.getName()); menuNotice(admin,prefix() + "Der Duplikat-Schutz wurde erfolgreich " + (antiSpam.duplicatesEnabled() ? "aktiviert" : "deaktiviert") + "."); }
        else if (slot == 13) { expansion.openKeywordAdminJava(admin); return; }
        else if (slot == 14) { antiSpam.setLinksBlocked(!antiSpam.linksBlocked(), admin.getName()); menuNotice(admin,prefix() + "Der Link-Filter wurde erfolgreich " + (antiSpam.linksBlocked() ? "aktiviert" : "deaktiviert") + "."); }
        else if (slot == 15) { openAntiSpamLog(admin, 0); return; }
        else if (slot == 16) { confirm(admin, new PendingAction("clear-antispam-log", null, "", ""), "Anti-Spam-Protokoll löschen", "Gesamtes Protokoll", "Alle Einträge dauerhaft entfernen?"); return; }
        else return;
        openAntiSpam(admin);
    }

    private void openAntiSpamLog(Player admin, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.openantispamlog")) return;
        List<AntiSpamLogEntry> list = antiSpam.logsNewest(); antiSpamLogViews.put(admin.getUniqueId(), list.stream().map(e -> e.id).collect(Collectors.toList()));
        int maxPage = Math.max(0, (list.size() - 1) / 45), page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("antispam-log", null, page, null, null), 54, color("&8Anti-Spam-Protokoll")); fillBottom(inv, page, maxPage);
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zu Anti-Spam."));
        for (int i = 0; i < 45; i++) { int index = page * 45 + i; if (index >= list.size()) break; AntiSpamLogEntry entry = list.get(index);
            List<String> lore = new ArrayList<>(); lore.add("&7Zeit: &f" + time(entry.createdAt)); lore.add("&7Grund: &f" + entry.reason); lore.addAll(splitLore(entry.message));
            inv.setItem(i, item(Material.PAPER, "&c" + entry.player, lore));
        }
        LiveMenus.show(admin,inv);
    }

    private void handleAntiSpamLogClick(Player admin, SuiteMenu menu, int slot) {
        int size = antiSpam.logsNewest().size(), maxPage = Math.max(0, (size - 1) / 45);
        if (slot == 45 && menu.page > 0) openAntiSpamLog(admin, menu.page - 1);
        else if (slot == 53 && menu.page < maxPage) openAntiSpamLog(admin, menu.page + 1);
        else if (slot == 49) openAntiSpam(admin);
    }

