    private String humanMillis(long millis) { long minutes=Math.max(0L,millis)/60000L; long days=minutes/1440L; long hours=(minutes%1440L)/60L; long mins=minutes%60L; return (days>0?days+"d ":"")+(hours>0?hours+"h ":"")+mins+"m"; }

