    private void openAltProfile(Player admin, UUID targetUuid, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.openaltprofile")) return;
        if (!require(admin, "simplexadminsuite.alts")) return;
        PlayerProfile target = database.get(targetUuid);
        if (target == null) { menuNotice(admin,prefix() + "Spielerprofil nicht gefunden."); return; }
        List<AdvancedAltDetection.AltMatch> matches = altDetection.matches(target, Integer.MAX_VALUE);
        int[] slots = new int[]{19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};
        int maxPage = Math.max(0, (matches.size() - 1) / slots.length);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("alt-profile", target.uuid, page, null, null), 54,
                color("&8Alt-Forensik: &f" + target.name));
        fill(inv);
        inv.setItem(4, playerHead(target, "&d" + target.name,
                "&7Client: &f" + target.clientSummary(),
                "&7Letzte Netzgruppe: &f" + (target.lastIpMasked.isEmpty() ? "Nicht erfasst" : target.lastIpMasked),
                "&7Forensisch verknüpft: &f" + matches.size(),
                "&7Seite: &f" + (page + 1) + "/" + (maxPage + 1),
                "&7Bridge: &f" + altDetection.bridgeStatus()));
        inv.setItem(10, item(Material.BOOK, "&bErfasste Signale",
                "&7IP-Historien: &f" + target.altIpHistory.size(),
                "&7Geräte-IDs: &f" + target.altDeviceHistory.size(),
                "&7XUID-Historien: &f" + target.altXuidHistory.size(),
                "&7Self-Signed-IDs: &f" + target.altSelfSignedHistory.size(),
                "&7Java-Brand: &f" + (target.javaClientBrand.isEmpty() ? "Nicht verfügbar" : target.javaClientBrand),
                "&7Java-Protokoll: &f" + (target.javaProtocolVersion < 0 ? "Nicht verfügbar" : target.javaProtocolVersion)));
        inv.setItem(12, item(Material.COMPASS, "&bGerätehistorie öffnen",
                "&7Gespeicherte Geräteprofile: &f" + target.devices.size(),
                "&7Modell: &f" + (target.bedrockDeviceModel.isEmpty() ? "Nicht verfügbar" : target.bedrockDeviceModel),
                "&7OS: &f" + (target.bedrockDeviceOs.isEmpty() ? target.clientDevice : target.bedrockDeviceOs),
                "&7Eingabe: &f" + target.clientInput,
                "&7UI: &f" + (target.bedrockUiProfile.isEmpty() ? "Nicht verfügbar" : target.bedrockUiProfile),
                "&7Klick zeigt alle Rohdaten, Filter und Sperren."));
        inv.setItem(16,item(Material.COMPASS,"&bRoh-IP & Standort","&7Kopieren, Diagnose und Spielerprofil"));
        inv.setItem(14, item(Material.MAP, "&eForensisches Deep-Link-Modell",
                "&7Direkt: Geräte-ID, XUID, Self-Signed, IP",
                "&7Transitiv: Konto → Gerät/IP → weiteres Konto",
                "&7Java und Bedrock werden über IP-Ketten verbunden",
                "&7Starke Identitätswege sind kaskadensicher",
                "&7IP-only/indirekt bleibt sichtbar, aber unsicher."));
        int startIndex = page * slots.length;
        for (int i = 0; i < slots.length; i++) {
            int index = startIndex + i;
            if (index >= matches.size()) break;
            AdvancedAltDetection.AltMatch match = matches.get(index);
            List<String> lore = new ArrayList<>();
            lore.add("&7Bewertung: &f" + match.score + " / " + match.level);
            lore.add("&7Kaskade erlaubt: " + (match.safeForCascade ? "&aJa" : "&cNein"));
            for (String evidence : match.evidence) lore.add("&8• &7" + evidence);
            lore.add("&7Klick öffnet dieses Profil.");
            inv.setItem(slots[i], playerHead(match.profile, (match.safeForCascade ? "&c" : "&e") + match.profile.name, lore.toArray(new String[0])));
        }
        if (matches.isEmpty()) inv.setItem(31, item(Material.LIME_DYE, "&aKeine verknüpften Alt-Accounts", "&7Für dieses Profil liegen aktuell", "&7keine direkten oder transitiven Signale vor."));
        if (page > 0) inv.setItem(18, item(Material.ARROW, "&e◀ Vorherige Seite", "&7Seite " + page + " öffnen."));
        if (page < maxPage) inv.setItem(26, item(Material.ARROW, "&eNächste Seite ▶", "&7Seite " + (page + 2) + " öffnen."));
        inv.setItem(45, item(Material.NAME_TAG, "&aKonten manuell verknüpfen", "&7Bestätigt eine bekannte Zuordnung", "&7nach Eingabe des zweiten Spielernamens."));
        inv.setItem(46, item(Material.PAPER, "&eTreffer ignorieren", "&7Markiert eine Fehlzuordnung dauerhaft", "&7nach Eingabe des anderen Spielernamens."));
        inv.setItem(47, item(Material.NETHERITE_AXE, "&cAlle sicher verknüpften bannen", "&7Fragt einen englischen Grund ab.", "&7Nutzt den vollständigen starken Deep-Link-Cluster."));
        inv.setItem(48, item(Material.CLOCK, "&cAlle sicher verknüpften tempbannen", "&7Eingabe: Dauer und englischer Grund.", "&7Beispiel: 7d Ban evasion"));
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zur Spielerverwaltung."));
        inv.setItem(50, item(Material.WRITABLE_BOOK, "&6Alle sicher verknüpften muten", "&7Fragt einen englischen Grund ab."));
        inv.setItem(51, item(Material.CLOCK, "&6Alle sicher verknüpften temporär muten", "&7Eingabe: Dauer und englischer Grund."));
        inv.setItem(52, item(Material.NETHERITE_AXE, "&4Ultrabann-System", "&7Persistente Identitätsgruppe verwalten,", "&7Evasion-Versuche sehen und zurücksetzen."));
        LiveMenus.show(admin,inv);
    }

    private void handleAltProfileClick(Player admin, SuiteMenu menu, int slot) {
        PlayerProfile target = database.get(menu.target);
        if (target == null || !require(admin, "simplexadminsuite.alts")) return;
        if (slot == 18 && menu.page > 0) { openAltProfile(admin, target.uuid, menu.page - 1); return; }
        if (slot == 26) { openAltProfile(admin, target.uuid, menu.page + 1); return; }
        if (slot == 49) { openPlayer(admin, target.uuid); return; }
        if (slot == 16) { openNetworkProfile(admin,target.uuid); return; }
        if (slot == 12) { openDeviceHistory(admin, target.uuid, 0, "ALL", ""); return; }
        if (slot == 45) { if (!require(admin, "simplexadminsuite.alts.link")) return; ask(admin, target.uuid, "alt-manual-link", "Schreibe den Namen des zugehörigen Kontos. 'abbrechen' beendet die Eingabe."); return; }
        if (slot == 46) { if (!require(admin, "simplexadminsuite.alts.link")) return; ask(admin, target.uuid, "alt-ignore-link", "Schreibe den Namen des falsch erkannten Kontos. 'abbrechen' beendet die Eingabe."); return; }
        if (slot == 47) { if (!require(admin, "simplexadminsuite.alts.cascade")) return; ask(admin, target.uuid, "alt-cascade-ban", "Schreibe den englischen Ban-Grund für alle sicher verknüpften Konten."); return; }
        if (slot == 48) { if (!require(admin, "simplexadminsuite.alts.cascade")) return; ask(admin, target.uuid, "alt-cascade-tempban", "Schreibe Dauer und englischen Grund, z. B. 7d Ban evasion."); return; }
        if (slot == 50) { if (!require(admin, "simplexadminsuite.alts.cascade")) return; ask(admin, target.uuid, "alt-cascade-mute", "Schreibe den englischen Mute-Grund für alle sicher verknüpften Konten."); return; }
        if (slot == 51) { if (!require(admin, "simplexadminsuite.alts.cascade")) return; ask(admin, target.uuid, "alt-cascade-tempmute", "Schreibe Dauer und englischen Grund, z. B. 1d Spam evasion."); return; }
        if (slot == 52) { openUltraProfile(admin, target.uuid); return; }
        int[] slots = new int[]{19,20,21,22,23,24,25,28,29,30,31,32,33,34,37,38,39,40,41,42,43};
        for (int i = 0; i < slots.length; i++) if (slot == slots[i]) {
            List<AdvancedAltDetection.AltMatch> matches = altDetection.matches(target, Integer.MAX_VALUE);
            int index = menu.page * slots.length + i;
            if (index < matches.size()) openAltProfile(admin, matches.get(index).profile.uuid, 0);
            return;
        }
    }

