    private void handleUltraProfileClick(Player admin, SuiteMenu menu, int slot) {
        PlayerProfile target = database.get(menu.target);
        if (target == null || !require(admin, "simplexadminsuite.ultraban.view")) return;
        if (slot == 49) { openPlayer(admin, target.uuid); return; }
        if (slot == 30) { if (moderationControl != null) moderationControl.banTarget(admin, target.uuid); return; }
        if (slot == 31) { openAltProfile(admin, target.uuid); return; }
        if (slot == 10) {
            if (!require(admin, "simplexadminsuite.ultraban")) return;
            moderationControl.banTarget(admin,target.uuid);
            return;
        }
        if (slot == 12) {
            if (!require(admin, "simplexadminsuite.ultraban.unban")) return;
            confirm(admin, new PendingAction("ultraunban", target.uuid, "", ""), "Ultrabann vollständig aufheben", target.name,
                    "Alle aktiven Ultrabann-Gruppen dieses Profils und ihre Identitätsanker deaktivieren?");
            return;
        }
        if (slot == 14) {
            for (String line : altDetection.evasionDetails(target, 12)) admin.sendMessage(color(line));
            openUltraProfile(admin, target.uuid);
            return;
        }
        if (slot == 16) {
            if (!require(admin, "simplexadminsuite.ultraban.reset")) return;
            confirm(admin, new PendingAction("ultrareset", target.uuid, "", ""), "Identitätsdaten vollständig zurücksetzen", target.name,
                    "Geräte-/IP-Historien, Alt-Verknüpfungen und Gruppenzuordnungen dieses Profils dauerhaft löschen?");
        }
    }

