    private void openRights(Player admin, UUID uuid) {
        if (!adminMenuAllowed(admin, "suite.openrights")) return; openRights(admin, uuid, 0); }

    private void openRights(Player admin, UUID uuid, int requestedPage) {
        if (!adminMenuAllowed(admin, "suite.openrights")) return;
        if (!require(admin, "simplexadminsuite.rights")) return;
        PlayerProfile target = database.get(uuid); if (target == null) return;
        int maxPage = Math.max(0, (RIGHTS.length - 1) / 45);
        int page = Math.max(0, Math.min(requestedPage, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("rights", uuid, page, null, null), 54,
                color("&8Rechte " + (page + 1) + "/" + (maxPage + 1) + ": &f" + target.name));
        fill(inv);
        int start = page * 45;
        for (int slot = 0; slot < 45; slot++) {
            int index = start + slot;
            if (index >= RIGHTS.length) break;
            String right = RIGHTS[index];
            boolean blocked = target.isBlocked(right);
            long temporaryUntil = target.temporaryBlockedUntil(right);
            String state = temporaryUntil > 0L ? "&6Temporär bis " + time(temporaryUntil) : blocked ? "&cDauerhaft gesperrt" : "&aErlaubt";
            inv.setItem(slot, item(blocked ? (temporaryUntil > 0L ? Material.ORANGE_DYE : Material.RED_DYE) : Material.LIME_DYE,
                    (blocked ? temporaryUntil > 0L ? "&6" : "&c" : "&a") + RIGHT_NAMES.getOrDefault(right, right),
                    "&7Schlüssel: &f" + right,
                    "&7Aktuell: " + state,
                    "&7Linksklick: dauerhaft umschalten.",
                    "&7Rechtsklick: temporär sperren."));
        }
        if (page > 0) inv.setItem(45, item(Material.ARROW, "&eVorherige Seite", "&7Zurück zu den vorherigen Rechten."));
        inv.setItem(47, item(Material.TOTEM_OF_UNDYING, "&aAlle Rechte erlauben", "&7Entfernt alle Sperren."));
        inv.setItem(48, item(powerTools != null && powerTools.altPolicyEnabled(target.uuid) ? Material.LIME_DYE : Material.ENDER_EYE,
                "&dAlt-Rechtevererbung", "&7Synchronisiert alle " + RIGHTS.length + " Rechte.",
                "&7Status: " + (powerTools != null && powerTools.altPolicyEnabled(target.uuid) ? "&aAktiv" : "&7Inaktiv")));
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zum Spieler."));
        int temporaryCount = target.temporaryBlockedRightsSnapshot().size();
        inv.setItem(50, item(Material.BOOK, "&6Rechteübersicht",
                "&7Gesamt: &f" + RIGHTS.length,
                "&7Gesperrt: &c" + target.blockedRights().size(),
                "&7Davon temporär: &6" + temporaryCount,
                "&7Erlaubt: &a" + Math.max(0, RIGHTS.length - target.blockedRights().size())));
        inv.setItem(51, item(Material.REDSTONE_BLOCK, "&cAlle Rechte sperren", "&7Setzt alle granularen Sperren aktiv."));
        if (page < maxPage) inv.setItem(53, item(Material.ARROW, "&eNächste Seite", "&7Weitere Rechte anzeigen."));
        LiveMenus.show(admin,inv);
    }

    private Integer rightsSlotIndex(int page, int slot) {
        if (slot < 0 || slot >= 45) return null;
        int index = page * 45 + slot;
        return index >= 0 && index < RIGHTS.length ? index : null;
    }

    private void openWarnings(Player admin, UUID uuid) {
        if (!adminMenuAllowed(admin, "suite.openwarnings")) return;
        if (!require(admin, "simplexadminsuite.warns")) return;
        PlayerProfile target = database.get(uuid); if (target == null) return;
        Inventory inv = LiveMenus.create(new SuiteMenu("warnings", uuid, 0, null, null), 54, color("&8Warnungen: &f" + target.name));
        fill(inv);
        inv.setItem(10, item(Material.WRITABLE_BOOK, "&eWarnung hinzufügen", "&7Speichert intern und versucht LiteBans /warn."));
        inv.setItem(12, item(Material.BOOK, "&bWarnungen anzeigen", "&7Intern gespeichert: &f" + target.warnings.size()));
        inv.setItem(14, item(Material.BARRIER, "&cWarnungen löschen", "&7Mit Bestätigung."));
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zum Spieler."));
        LiveMenus.show(admin,inv);
    }

