    private void openSnapshots(Player admin, UUID uuid) {
        if (!adminMenuAllowed(admin, "suite.opensnapshots")) return; openSnapshots(admin, uuid, 0); }

    private void openSnapshots(Player admin, UUID uuid, int page) {
        if (!adminMenuAllowed(admin, "suite.opensnapshots")) return;
        if (!require(admin, "simplexadminsuite.snapshots")) return;
        PlayerProfile target = database.get(uuid); if (target == null) return;
        File[] files = snapshotFiles(uuid);
        int maxPage = Math.max(0, (files.length - 1) / 45);
        page = Math.max(0, Math.min(page, maxPage));
        Inventory inv = LiveMenus.create(new SuiteMenu("snapshots", uuid, page, null, null), 54, color("&8Snapshots: &f" + target.name));
        fillBottom(inv, page, maxPage);
        inv.setItem(48, item(Material.ENDER_CHEST, "&dNeuen Snapshot erstellen", "&7Speichert Inventar, Rüstung, Enderchest,", "&7Level, Food, Health, Gamemode und Ort."));
        inv.setItem(49, item(Material.BARRIER, "&cZurück", "&7Zurück zum Spieler."));
        int start = page * 45;
        for (int i = 0; i < 45; i++) {
            int index = start + i;
            if (index >= files.length) break;
            File file = files[index];
            inv.setItem(i, item(Material.CLOCK, "&6" + readableSnapshotName(file.getName()), "&7Alter: &f" + ageText(file.lastModified()), "&7Datei: &f" + file.getName(), "&7Größe: &f" + file.length() + " Bytes", "&7Klick zum Wiederherstellen.", "&8Löschen: /sas snapshot delete " + target.name + " " + file.getName()));
        }
        if (files.length == 0) {
            inv.setItem(22, item(Material.BOOK, "&7Keine Snapshots vorhanden", "&7Erstelle unten über die Enderchest", "&7einen neuen Snapshot."));
        }
        LiveMenus.show(admin,inv);
    }

    private void openHistory(Player admin, UUID uuid, String type, int page, String search) {
        if (!adminMenuAllowed(admin, "suite.openhistory")) return;
        if (!require(admin, "simplexadminsuite.history")) return;
        PlayerProfile target = database.get(uuid); if (target == null) return;
        List<String> base = type.equals("chat") ? target.recentChat : type.equals("private") ? target.recentPrivateMessages : type.equals("combat") ? target.recentCombat : target.recentActions;
        List<String> data = new ArrayList<>();
        for (String line : base) if (search == null || line.toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT))) data.add(line);
        Collections.reverse(data);
        int maxPage = Math.max(0, (data.size() - 1) / 45);
        page = Math.max(0, Math.min(page, maxPage));
        String title = type.equals("chat") ? "&8Chat: &f" : type.equals("private") ? "&8Privatnachrichten: &f" : type.equals("combat") ? "&8Kampfverlauf: &f" : "&8Logs: &f";
        Inventory inv = LiveMenus.create(new SuiteMenu("history", uuid, page, type, search), 54, color(title + target.name));
        fillBottom(inv, page, maxPage);
        int start = page * 45;
        for (int i = 0; i < 45; i++) {
            int index = start + i;
            if (index >= data.size()) break;
            String line = data.get(index);
            Material icon = type.equals("combat") ? Material.IRON_SWORD : type.equals("private") ? Material.WRITABLE_BOOK : type.equals("chat") ? Material.PAPER : Material.MAP;
            inv.setItem(i, item(icon, "&fEintrag " + (index + 1), splitLore(line)));
        }
        LiveMenus.show(admin,inv);
    }

    private void confirm(Player player, PendingAction action, String title, String target, String question) {
        pendingActions.put(player.getUniqueId(), action);
        Inventory inv = LiveMenus.create(new SuiteMenu("confirm", action.target, 0, null, null), 36, color("&8Bestätigung"));
        fill(inv);
        inv.setItem(11, item(Material.LIME_DYE, "&aBestätigen", "&7" + title, "&7Ziel: &f" + target, "&7" + question));
        inv.setItem(15, item(Material.RED_DYE, "&cAbbrechen", "&7Aktion nicht ausführen."));
        inv.setItem(20, item(Material.LIME_DYE, "&aJa, ausführen", "&7Letzte Bestätigung."));
        inv.setItem(24, item(Material.RED_DYE, "&cNein", "&7Zurück."));
        LiveMenus.show(player,inv);
    }

    private void completePending(Player admin, PendingInput pending, String message) {
        asAdmin(admin.getName(),()->completeAuditedPending(admin,pending,message));
    }
    private void completeAuditedPending(Player admin, PendingInput pending, String message) {
        boolean cancelled = message.equalsIgnoreCase("abbrechen") || message.equalsIgnoreCase("cancel");
        if (pending.action.equals("world-time")) {
            World world = Bukkit.getWorld(pending.value);
            if (cancelled) { admin.sendMessage(prefix() + "Aktion abgebrochen."); if (world != null) openWorldDetail(admin, world.getName()); else openWorlds(admin); return; }
            if (world == null) { menuNotice(admin,prefix() + "Die Welt ist nicht mehr geladen."); openWorlds(admin); return; }
            if (!changeWorldTime(admin,world,message)) {openWorldDetail(admin,world.getName());return;}
            audit.log(admin.getName(), null, "Weltzeit geändert", world.getName() + "=" + worldTimeText(world)); openWorldDetail(admin, world.getName()); return;
        }
        if (pending.action.equals("gamerule-value")) {
            String[] data = pending.value.split("\n", -1); String worldName = data.length > 0 ? data[0] : "", rule = data.length > 1 ? data[1] : ""; int page = data.length > 2 ? parseInt(data[2], 0) : 0;
            World world = Bukkit.getWorld(worldName);
            if (cancelled) { admin.sendMessage(prefix() + "Aktion abgebrochen."); if (world != null) openGameRules(admin, worldName, page); else openWorlds(admin); return; }
            String clean = sanitizeText(message, 64);
            if (world == null || rule.isBlank() || !changeRule(admin, world, rule, clean)) { menuNotice(admin,prefix() + "Der Gamerule-Wert wurde abgelehnt oder die Welt ist nicht geladen."); if (world != null) openGameRules(admin, worldName, page); else openWorlds(admin); return; }
            openGameRules(admin, worldName, page); return;
        }
        if (pending.action.equals("warp-create")) {
            int page = parseInt(pending.value, 0); if (cancelled) { admin.sendMessage(prefix() + "Aktion abgebrochen."); openWarpsAdmin(admin, page); return; }
            String[] parts = message.split("\\|", 3); if (parts.length < 2) { menuNotice(admin,prefix() + "Ungültige Eingabe. Nutze: id | Anzeigename | englische Beschreibung."); openWarpsAdmin(admin, page); return; }
            String description = parts.length >= 3 ? parts[2] : "Server warp"; WarpPoint created = warps.create(parts[0], parts[1], description, admin.getLocation(), admin.getName());
            if (created == null) menuNotice(admin,prefix() + "Der Warp konnte nicht angelegt werden. Prüfe ID, Eindeutigkeit und Standort."); else menuNotice(admin,prefix() + "Der Warp " + created.displayName + " wurde erfolgreich angelegt."); openWarpsAdmin(admin, page); return;
        }
        if (pending.action.equals("warp-priority")) {
            String[] data = pending.value.split("\n", -1); String id = data.length > 0 ? data[0] : ""; int page = data.length > 1 ? parseInt(data[1], 0) : 0;
            if (cancelled) { admin.sendMessage(prefix() + "Aktion abgebrochen."); openWarpDetail(admin, id, page); return; }
            int priority = parseInt(message, Integer.MIN_VALUE); if (priority == Integer.MIN_VALUE || !warps.setPriority(id, priority, admin.getName())) menuNotice(admin,prefix() + "Die Priorität ist ungültig oder der Warp existiert nicht."); else menuNotice(admin,prefix() + "Die Warp-Priorität wurde erfolgreich auf " + priority + " gesetzt."); openWarpDetail(admin, id, page); return;
        }
        if (pending.action.equals("warp-text")) {
            String[] data = pending.value.split("\n", -1); String id = data.length > 0 ? data[0] : ""; int page = data.length > 1 ? parseInt(data[1], 0) : 0;
            if (cancelled) { admin.sendMessage(prefix() + "Aktion abgebrochen."); openWarpDetail(admin, id, page); return; }
            String[] parts = message.split("\\|", 2); if (parts.length < 2 || !warps.setText(id, parts[0], parts[1], admin.getName())) menuNotice(admin,prefix() + "Ungültige Eingabe oder Warp nicht gefunden. Nutze: Anzeigename | englische Beschreibung."); else menuNotice(admin,prefix() + "Name und Beschreibung wurden erfolgreich aktualisiert."); openWarpDetail(admin, id, page); return;
        }
        if (pending.action.startsWith("discord-bot-")) {
            if (cancelled) { admin.sendMessage(prefix() + "Aktion abgebrochen."); openDiscordStatusSettings(admin); return; }
            if (!has(admin, "simplexadminsuite.discordstatus")) { menuNotice(admin,prefix() + "Deine Berechtigung fehlt inzwischen."); return; }
            if ((pending.action.equals("discord-bot-vpn-role") || pending.action.equals("discord-bot-vpn-channel"))
                    && !has(admin, "simplexadminsuite.vpn.manage")) { menuNotice(admin,prefix() + "Deine VPN-Verwaltungsberechtigung fehlt inzwischen."); return; }
            String clean = message.trim();
            if (pending.action.equals("discord-bot-admin-roles") || pending.action.equals("discord-bot-read-roles")
                    || pending.action.equals("discord-bot-admin-channels")) {
                List<String> ids = new ArrayList<>();
                if (!clean.equals("-") && !clean.isBlank()) {
                    for (String part : clean.split("[,\\s]+")) {
                        if (!part.matches("\\d{15,22}")) { menuNotice(admin,prefix() + "Ungültige Discord-ID: " + sanitizeText(part, 30)); openDiscordStatusSettings(admin); return; }
                        if (!ids.contains(part)) ids.add(part);
                    }
                }
                String path = pending.action.equals("discord-bot-admin-roles") ? "discord-bot.admin.role-ids"
                        : pending.action.equals("discord-bot-read-roles") ? "discord-bot.admin.read-only-role-ids"
                        : "discord-bot.admin.allowed-channel-ids";
                getConfig().set(path, ids);
                saveConfig();
                audit.log(admin.getName(), null, "Discord-Adminzugriff aktualisiert", path + " • " + ids.size() + " IDs");
                menuNotice(admin,prefix() + "Discord-Adminliste wurde mit " + ids.size() + " ID(s) gespeichert.");
                openDiscordStatusSettings(admin);
                return;
            }
            if (pending.action.equals("discord-bot-admin-audit")) {
                if (clean.equals("-")) clean = "";
                if (!clean.isEmpty() && !clean.matches("\\d{15,22}")) { admin.sendMessage(prefix() + "Erwartet wird eine numerische Discord-Kanal-ID."); openDiscordStatusSettings(admin); return; }
                getConfig().set("discord-bot.admin.audit-channel-id", clean);
                saveConfig();
                menuNotice(admin,prefix() + "Discord-Admin-Auditkanal wurde gespeichert.");
                openDiscordStatusSettings(admin);
                return;
            }
            if (pending.action.equals("discord-bot-inline-prefix")) {
                if (clean.isBlank() || clean.length() > 20 || clean.chars().anyMatch(Character::isWhitespace)) {
                    admin.sendMessage(prefix() + "Der Präfix muss 1 bis 20 Zeichen lang sein und darf keine Leerzeichen enthalten.");
                    openDiscordStatusSettings(admin); return;
                }
                getConfig().set("discord-bot.admin.inline.prefix", clean);
                saveConfig();
                menuNotice(admin,prefix() + "Discord-Inline-Präfix wurde auf " + clean + " gesetzt.");
                openDiscordStatusSettings(admin);
                return;
            }
            String path;
            if (pending.action.equals("discord-bot-token")) {
                if (clean.length() < 20 || clean.contains(" ")) { menuNotice(admin,prefix() + "Der Bot-Token ist offensichtlich ungültig."); openDiscordStatusSettings(admin); return; }
                path = "discord-bot.token";
            } else {
                boolean optionalAlertId = pending.action.equals("discord-bot-alert-role") || pending.action.equals("discord-bot-alert-channel")
                        || pending.action.equals("discord-bot-vpn-role") || pending.action.equals("discord-bot-vpn-channel");
                if (optionalAlertId && clean.equals("-")) clean = "";
                if (!clean.isEmpty() && !clean.matches("\\d{15,22}")) { admin.sendMessage(prefix() + "Erwartet wird eine numerische Discord-ID mit 15 bis 22 Stellen."); openDiscordStatusSettings(admin); return; }
                path = pending.action.equals("discord-bot-guild") ? "discord-bot.guild-id"
                        : pending.action.equals("discord-bot-relay") ? "discord-bot.relay-channel-id"
                        : pending.action.equals("discord-bot-alert-role") ? "discord-bot.alerts.role-id"
                        : pending.action.equals("discord-bot-alert-channel") ? "discord-bot.alerts.channel-id"
                        : pending.action.equals("discord-bot-vpn-role") ? "discord-bot.vpn-log.role-id"
                        : pending.action.equals("discord-bot-vpn-channel") ? "discord-bot.vpn-log.channel-id" : "discord-bot.status-channel-id";
            }
            if (pending.action.equals("discord-bot-vpn-channel")) getConfig().set("discord-bot.vpn-log.enabled", !clean.isBlank());
            discordBot.setSecret(path, clean);
            menuNotice(admin,prefix() + "Discord-Bot-Einstellung wurde sicher gespeichert und die Verbindung neu geladen.");
            openDiscordStatusSettings(admin);
            return;
        }
        if (pending.action.equals("discord-status-url")) {
            if (message.equalsIgnoreCase("abbrechen") || message.equalsIgnoreCase("cancel")) { admin.sendMessage(prefix() + "Aktion abgebrochen."); openDiscordStatusSettings(admin); return; }
            if (!has(admin, "simplexadminsuite.discordstatus")) { menuNotice(admin,prefix() + "Deine Berechtigung fehlt inzwischen."); return; }
            if (!discordStatus.setWebhook(admin.getName(), message.trim())) {
                admin.sendMessage(prefix() + "Die URL ist kein gültiger Discord-Webhook. Erwartet wird https://discord.com/api/webhooks/…");
                openDiscordStatusSettings(admin);
                return;
            }
            menuNotice(admin,prefix() + "Webhook sicher gespeichert. Eine persistente Statusnachricht wird erstellt oder weiterverwendet.");
            openDiscordStatusSettings(admin);
            return;
        }
        if (pending.action.equals("maintenance-enable")) {
            if (message.equalsIgnoreCase("abbrechen") || message.equalsIgnoreCase("cancel")) { admin.sendMessage(prefix() + "Aktion abgebrochen."); openMaintenance(admin); return; }
            String reason = message.trim().equals("-") ? "" : sanitizeText(message, getConfig().getInt("maintenance.max-reason-length", 180));
            setMaintenanceMode(admin, true, reason);
            openMaintenance(admin);
            return;
        }
        if (pending.action.equals("report-search")) {
            if (message.equalsIgnoreCase("cancel") || message.equalsIgnoreCase("abbrechen")) {
                admin.sendMessage(prefix() + "Report search cancelled.");
                admin.closeInventory();
                return;
            }
            String query = sanitizeText(message, 64).trim();
            int minimumLength = Math.max(1, getConfig().getInt("reports.minimum-search-length", 1));
            if (query.length() < minimumLength) {
                admin.sendMessage(prefix() + "Enter at least " + minimumLength + " character" + (minimumLength == 1 ? "" : "s") + " of the player's name.");
                ask(admin, admin.getUniqueId(), "report-search", "Enter any part of the player's name. Type 'cancel' to close the report menu.");
                return;
            }
            openReportPlayers(admin, query, 0);
            return;
        }
        if (pending.action.equals("start-message")) {
            if (message.equalsIgnoreCase("abbrechen") || message.equalsIgnoreCase("cancel")) { openStartMessages(admin, 0); return; }
            if (!has(admin, "simplexadminsuite.startmessages")) { admin.sendMessage(prefix() + "Deine Berechtigung für Startnachrichten ist nicht mehr vorhanden."); return; }
            StartMessage created = startMessages.add(admin.getName(), message);
            menuNotice(admin,prefix() + (created == null ? "Die Nachricht war leer und wurde nicht gespeichert." : "Startnachricht #" + created.id + " wurde angelegt."));
            openStartMessages(admin, 0);
            return;
        }
        if (pending.action.equals("announcement-add")) {
            if (message.equalsIgnoreCase("abbrechen") || message.equalsIgnoreCase("cancel")) { openAnnouncements(admin, 0); return; }
            String[] split = message.trim().split("\s+", 2);
            if (split.length < 2) { admin.sendMessage(prefix() + "Nutze: <Minuten> <englischer Text>."); openAnnouncements(admin, 0); return; }
            int minutes; try { minutes = Integer.parseInt(split[0]); } catch (Exception error) { menuNotice(admin,prefix() + "Die Minutenanzahl ist ungültig."); openAnnouncements(admin, 0); return; }
            Announcement created = announcements.add(admin.getName(), split[1], minutes);
            menuNotice(admin,prefix() + (created == null ? "Ankündigung konnte nicht angelegt werden." : "Ankündigung #" + created.id + " wurde angelegt."));
            openAnnouncements(admin, 0);
            return;
        }
        if (pending.action.equals("device-search")) {
            if (cancelled) { openDeviceHistory(admin, pending.target, 0, pending.value, ""); return; }
            openDeviceHistory(admin, pending.target, 0, pending.value, sanitizeText(message, 120));
            return;
        }
        PlayerProfile target = database.get(pending.target);
        if (target == null) { menuNotice(admin,prefix() + "Spielerprofil nicht gefunden."); return; }
        if (message.equalsIgnoreCase("abbrechen") || message.equalsIgnoreCase("cancel")) {
            if (pending.action.equals("report-details")) admin.sendMessage(prefix() + "Report editing cancelled.");
            else admin.sendMessage(prefix() + "Aktion abgebrochen.");
            if (pending.action.equals("report-details")) openReportCompose(admin);
            else if (pending.action.equals("staff-message")) openStaffWorkspace(admin);
            else if (pending.action.startsWith("report-note:")) {
                try { openReportDetail(admin, Long.parseLong(pending.action.substring("report-note:".length()))); } catch (Exception ignored) { openReports(admin, 0); }
            } else if (pending.action.startsWith("temp-right:")) openRights(admin, target.uuid);
            else openPlayer(admin, target.uuid);
            return;
        }
        if (pending.action.equals("alt-manual-link") || pending.action.equals("alt-ignore-link")) {
            if (!has(admin, "simplexadminsuite.alts.link")) { admin.sendMessage(prefix() + "Deine Berechtigung für Alt-Verknüpfungen ist nicht mehr vorhanden."); return; }
            PlayerProfile other = database.find(sanitizeText(message, 80));
            if (other == null || other.uuid.equals(target.uuid)) {
                menuNotice(admin,prefix() + "Das zweite Spielerprofil wurde nicht gefunden oder entspricht dem Ausgangsprofil.");
                openAltProfile(admin, target.uuid);
                return;
            }
            if (pending.action.equals("alt-manual-link")) {
                altDetection.manualLink(admin.getName(), target, other);
                menuNotice(admin,prefix() + target.name + " und " + other.name + " wurden manuell verknüpft.");
            } else {
                altDetection.ignoreLink(admin.getName(), target, other);
                admin.sendMessage(prefix() + "Der Treffer zwischen " + target.name + " und " + other.name + " wird ignoriert.");
            }
            openAltProfile(admin, target.uuid);
            return;
        }
        if (pending.action.startsWith("temp-right:")) {
            if (!has(admin, "simplexadminsuite.rights")) { admin.sendMessage(prefix() + "Deine Rechte-Berechtigung ist nicht mehr vorhanden."); return; }
            String right = normalizeRight(pending.action.substring("temp-right:".length()));
            DurationValue duration = DurationValue.parse(message.trim());
            if (right == null || duration == null) {
                menuNotice(admin,prefix() + "Ungültige Dauer. Beispiele: 30m, 6h, 7d, 2w oder 1d12h.");
                openRights(admin, target.uuid);
                return;
            }
            setTemporaryRight(admin.getName(), target, right, message.trim(), duration.until(System.currentTimeMillis()));
            menuNotice(admin,prefix() + RIGHT_NAMES.getOrDefault(right, right) + " wurde für " + target.name + " für " + message.trim() + " gesperrt.");
            openRights(admin, target.uuid);
            return;
        }
        if (pending.action.equals("ultraban")) {
            if (!has(admin, "simplexadminsuite.ultraban")) { admin.sendMessage(prefix() + "Deine Ultrabann-Berechtigung ist nicht mehr vorhanden."); return; }
            String reason = sanitizeText(message, getConfig().getInt("punishments.max-reason-length", 240));
            if (reason.isBlank()) reason = "Ban evasion / identity-wide ban";
            confirm(admin, new PendingAction("ultraban", target.uuid, "", reason), "ULTRABANN bestätigen", target.name,
                    reason + " | Einschließlich starker Alt-Konten und aktueller gleicher IP-Konten");
            return;
        }
        if (pending.action.startsWith("alt-cascade-")) {
            if (!has(admin, "simplexadminsuite.alts.cascade")) { admin.sendMessage(prefix() + "Deine Berechtigung für Kaskadenstrafen ist nicht mehr vorhanden."); return; }
            String action = pending.action.substring("alt-cascade-".length());
            String duration = "";
            String reason = sanitizeText(message, getConfig().getInt("punishments.max-reason-length", 240));
            if (action.equals("tempban") || action.equals("tempmute")) {
                String[] parts = reason.split(" ", 2);
                duration = parts.length > 0 ? parts[0] : "1d";
                reason = parts.length > 1 ? parts[1] : "Ban evasion / linked account";
                if (!DurationValue.isValid(duration)) {
                    menuNotice(admin,prefix() + "Ungültige Dauer. Beispiele: 30m, 6h, 7d oder 2w.");
                    openAltProfile(admin, target.uuid);
                    return;
                }
            }
            if (reason.isBlank()) reason = action.contains("ban") ? "Ban evasion / linked account" : "Linked account punishment";
            confirm(admin, new PendingAction("alt-cascade-" + action, target.uuid, duration, reason),
                    "Verknüpfte Konten bestrafen", target.name,
                    (duration.isEmpty() ? "" : duration + " | ") + reason + " | Nur kaskadensichere Treffer");
            return;
        }
        if (pending.action.equals("watchlist-add")) {
            watchlist.add(admin.getName(), target, sanitizeText(message, getConfig().getInt("watchlist.max-reason-length", 240)));
            menuNotice(admin,prefix() + target.name + " wurde zur Beobachtungsliste hinzugefügt.");
            openPlayer(admin, target.uuid);
            return;
        }
        message = sanitizeText(message, Math.max(500, getConfig().getInt("punishments.max-reason-length", 240)));
        if (pending.action.equals("report-details")) {
            ReportDraft draft = reportDrafts.get(admin.getUniqueId());
            if (draft == null || !draft.target.equals(target.uuid)) { openReportMenu(admin); return; }
            draft.details = sanitizeText(message, getConfig().getInt("reports.max-description-length", 500));
            openReportCompose(admin);
            return;
        }
        if (pending.action.equals("staff-message")) {
            if (!has(admin, "simplexadminsuite.admin") || !has(admin, "simplexadminsuite.staffchat")) {
                admin.sendMessage(prefix() + "Deine Berechtigung für Staff-Nachrichten ist nicht mehr vorhanden.");
                return;
            }
            staffWorkspace.post(admin.getName(), admin.getUniqueId(), sanitizeText(message, getConfig().getInt("staff-workspace.max-message-length", 300)));
            openStaffWorkspace(admin);
            return;
        }
        if (pending.action.startsWith("report-note:")) {
            if (!has(admin, "simplexadminsuite.admin") || !has(admin, "simplexadminsuite.reports")) {
                admin.sendMessage(prefix() + "Deine Berechtigung für Report-Fallakten ist nicht mehr vorhanden.");
                return;
            }
            try {
                long id = Long.parseLong(pending.action.substring("report-note:".length()));
                reports.setStaffNote(id, admin.getName(), sanitizeText(message, getConfig().getInt("reports.max-staff-note-length", 500)));
                openReportDetail(admin, id);
            } catch (Exception error) { openReports(admin, 0); }
            return;
        }
        message = sanitizeText(message, getConfig().getInt("punishments.max-reason-length", 240));
        if (pending.action.equals("searchchat")) { openHistory(admin, target.uuid, "chat", 0, message); audit.log(admin.getName(), target.uuid, "Chat-Suche", message); return; }
        if (pending.action.equals("searchactions")) { openHistory(admin, target.uuid, "actions", 0, message); audit.log(admin.getName(), target.uuid, "Log-Suche", message); return; }
        if (pending.action.equals("note")) { addNote(admin, target, message); openNotes(admin, target.uuid); return; }
        if (pending.action.equals("warn")) { confirm(admin, new PendingAction("warn", target.uuid, "", message), "Warnung hinzufügen", target.name, message); return; }
        if (pending.action.equals("ban")) { confirm(admin, new PendingAction("ban", target.uuid, "", message), "Permanent bannen", target.name, message); return; }
        if (pending.action.equals("tempban")) {
            String[] parts = message.split(" ", 2);
            String duration = parts.length > 0 ? parts[0] : "1d";
            String reason = parts.length > 1 ? parts[1] : "No reason provided";
            if (!DurationValue.isValid(duration)) { menuNotice(admin,prefix() + "Ungültige Dauer. Beispiele: 30m, 6h, 7d, 2w oder 1d12h."); openPunish(admin, target.uuid); return; }
            confirm(admin, new PendingAction("tempban", target.uuid, duration, reason), "Temporär bannen", target.name, duration + " | " + reason);
            return;
        }
        if (pending.action.equals("mute")) { confirm(admin, new PendingAction("mute", target.uuid, "", message), "Stummschalten", target.name, message); return; }
        if (pending.action.equals("tempmute")) {
            String[] parts = message.split(" ", 2);
            String duration = parts.length > 0 ? parts[0] : "1d";
            String reason = parts.length > 1 ? parts[1] : "No reason provided";
            if (!DurationValue.isValid(duration)) { menuNotice(admin,prefix() + "Ungültige Dauer. Beispiele: 30m, 6h, 7d, 2w oder 1d12h."); openPunish(admin, target.uuid); return; }
            confirm(admin, new PendingAction("tempmute", target.uuid, duration, reason), "Temporär stummschalten", target.name, duration + " | " + reason);
            return;
        }
        if (pending.action.equals("kick")) { confirm(admin, new PendingAction("kick", target.uuid, "", message), "Kicken", target.name, message); }
    }

    private void executeConfirmed(Player admin, PendingAction action) {
        String a = action.action;
        if (a.equals("delete-warp")) {
            int page = parseInt(action.reason, 0); WarpPoint point = warps.get(action.value); boolean removed = warps.delete(action.value, admin.getName());
            menuNotice(admin,prefix() + (removed ? "Der Warp " + (point == null ? action.value : point.displayName) + " wurde erfolgreich gelöscht." : "Der Warp wurde nicht gefunden.")); openWarpsAdmin(admin, page); return;
        }
        if (a.equals("clear-antispam-log")) { antiSpam.clear(admin.getName()); menuNotice(admin,prefix() + "Das Anti-Spam-Protokoll wurde erfolgreich gelöscht."); openAntiSpam(admin); return; }
        if (a.equals("maintenance-enable-empty")) {
            setMaintenanceMode(admin, true, "");
            openMaintenance(admin);
            return;
        }
        if (a.equals("server-restart")) {
            if (!has(admin, "simplexadminsuite.restart")) {
                admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.restart.");
                openOperations(admin);
                return;
            }
            boolean started = restartManager.schedule(admin.getName());
            menuNotice(admin,prefix() + (started
                    ? "Der Server-Neustart wurde gestartet. Alle Spieler erhalten jetzt den englischen Countdown."
                    : "Ein Server-Neustart läuft bereits."));
            openOperations(admin);
            return;
        }
        if (a.equals("watchlist-remove")) {
            PlayerProfile target = database.get(action.target);
            watchlist.remove(admin.getName(), action.target);
            menuNotice(admin,prefix() + (target == null ? "Spieler" : target.name) + " wurde von der Beobachtungsliste entfernt.");
            if (target != null) openPlayer(admin, target.uuid); else openWatchlist(admin, 0);
            return;
        }
        if (a.equals("announcement-delete")) {
            long id; try { id = Long.parseLong(action.value); } catch (Exception ignored) { openAnnouncements(admin, 0); return; }
            announcements.remove(admin.getName(), id);
            menuNotice(admin,prefix() + "Ankündigung #" + id + " wurde gelöscht.");
            openAnnouncements(admin, 0);
            return;
        }
        if (a.equals("maintenance-disable")) {
            setMaintenanceMode(admin, false, "");
            openMaintenance(admin);
            return;
        }
        if (a.equals("reset-admin-password")) {
            if (!admin.isOp() || action.target == null) {
                admin.sendMessage(prefix() + "Nur echte Server-Operatoren dürfen Admin-Passwörter zurücksetzen.");
                openSecuritySettings(admin);
                return;
            }
            PlayerProfile passwordTarget = database.get(action.target);
            if (passwordTarget == null || !isStaffAccount(action.target)) {
                menuNotice(admin,prefix() + "Admin-Profil nicht gefunden.");
                openPasswordAdmins(admin, 0);
                return;
            }
            adminSecurity.resetPersonalPassword(action.target, admin.getName());
            menuNotice(admin,prefix() + "Das persönliche Passwort von " + passwordTarget.name + " wurde zurückgesetzt.");
            openPasswordDetail(admin, action.target);
            return;
        }
        if (a.equals("delete-start-message")) {
            long id;
            try { id = Long.parseLong(action.value); } catch (Exception error) { menuNotice(admin,prefix() + "Ungültige Startnachrichten-ID."); openStartMessages(admin, 0); return; }
            menuNotice(admin,prefix() + (startMessages.delete(id, admin.getName()) ? "Startnachricht #" + id + " wurde vollständig gelöscht." : "Startnachricht wurde nicht gefunden."));
            openStartMessages(admin, 0);
            return;
        }
        if (a.equals("delete-staff-message")) {
            long createdAt;
            try { createdAt = Long.parseLong(action.value); } catch (Exception error) { menuNotice(admin,prefix() + "Ungültige Nachrichten-ID."); openStaffMessages(admin, 0); return; }
            menuNotice(admin,prefix() + (staffWorkspace.delete(createdAt, admin.getName()) ? "Staff-Nachricht wurde vollständig gelöscht." : "Staff-Nachricht wurde nicht gefunden."));
            openStaffMessages(admin, 0);
            return;
        }
        if (a.equals("delete-report")) {
            long id;
            try { id = Long.parseLong(action.value); } catch (Exception error) { menuNotice(admin,prefix() + "Ungültige Report-ID."); openReports(admin, 0); return; }
            if (reports.deleteReport(id, admin.getName())) menuNotice(admin,prefix() + "Report #" + id + " wurde vollständig gelöscht.");
            else menuNotice(admin,prefix() + "Report #" + id + " wurde nicht gefunden oder konnte nicht gelöscht werden.");
            openReports(admin, 0);
            return;
        }
        PlayerProfile target = action.target == null ? null : database.get(action.target);
        if (target == null && action.target != null) { menuNotice(admin,prefix() + "Spielerprofil nicht gefunden."); openMain(admin); return; }
        if (a.equals("device-block")) {
            boolean blocked = Boolean.parseBoolean(action.reason);
            boolean changed = altDetection.setDeviceBlocked(admin, target, action.value, blocked);
            menuNotice(admin,prefix() + (changed ? "Das Bedrock-Gerät wurde " + (blocked ? "gesperrt." : "entsperrt.") : "Das Bedrock-Gerät wurde nicht gefunden."));
            if (altDetection.device(target, action.value) != null) openDeviceDetail(admin, target.uuid, action.value); else openDeviceHistory(admin, target.uuid, 0, "ALL", "");
            return;
        }
        if (a.equals("ip-block")) {
            boolean blocked = Boolean.parseBoolean(action.reason);
            boolean changed = altDetection.setIpBlocked(admin, target, action.value, blocked);
            menuNotice(admin,prefix() + (changed ? "Die IP wurde " + (blocked ? "serverweit gesperrt." : "serverweit entsperrt.") : "Die IP konnte nicht verarbeitet werden."));
            openDeviceHistory(admin, target.uuid, 0, "ALL", action.value);
            return;
        }
        if (a.equals("device-delete")) {
            boolean removed = altDetection.deleteDevice(admin, target, action.value);
            menuNotice(admin,prefix() + (removed ? "Der Gerätedatensatz wurde dauerhaft gelöscht." : "Der Gerätedatensatz wurde nicht gefunden."));
            openDeviceHistory(admin, target.uuid, 0, "ALL", "");
            return;
        }
        if (a.equals("device-clear")) {
            int removed = altDetection.clearDevices(admin, target);
            menuNotice(admin,prefix() + removed + " Gerätedatensätze wurden dauerhaft gelöscht.");
            openDeviceHistory(admin, target.uuid, 0, "ALL", "");
            return;
        }
        if (a.equals("ultraban")) {
            if (!has(admin, "simplexadminsuite.ultraban")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.ultraban."); openUltraProfile(admin, target.uuid); return; }
            AdvancedAltDetection.UltraBanResult result = altDetection.ultraBan(admin, target, action.reason);
            admin.sendMessage(prefix() + result.message);
            openUltraProfile(admin, target.uuid);
            return;
        }
        if (a.equals("ultraunban")) {
            if (!has(admin, "simplexadminsuite.ultraban.unban")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.ultraban.unban."); openUltraProfile(admin, target.uuid); return; }
            AdvancedAltDetection.UltraBanResult result = altDetection.ultraUnban(admin, target.name);
            admin.sendMessage(prefix() + result.message);
            openUltraProfile(admin, target.uuid);
            return;
        }
        if (a.equals("ultrareset")) {
            if (!has(admin, "simplexadminsuite.ultraban.reset")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.ultraban.reset."); openUltraProfile(admin, target.uuid); return; }
            AdvancedAltDetection.ResetResult result = altDetection.resetIdentityData(admin, target);
            admin.sendMessage(prefix() + result.message);
            openUltraProfile(admin, target.uuid);
            return;
        }
        if (a.startsWith("alt-cascade-")) {
            if (!has(admin, "simplexadminsuite.alts.cascade")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.alts.cascade."); openAltProfile(admin, target.uuid); return; }
            String punishment = a.substring("alt-cascade-".length());
            AdvancedAltDetection.CascadeResult result = altDetection.cascadePunishment(admin, punishment, target, action.value, action.reason);
            admin.sendMessage(prefix() + result.message);
            openAltProfile(admin, target.uuid);
            return;
        }
        if (a.equals("delete-note")) {
            boolean removed = target.notes.remove(action.value);
            if (removed) { target.staffNotesUpdatedAt = System.currentTimeMillis(); target.addAction("Einzelne Teamnotiz durch " + admin.getName() + " gelöscht"); database.save(target); audit.log(admin.getName(), target.uuid, "Teamnotiz gelöscht", action.value); }
            menuNotice(admin,prefix() + (removed ? "Teamnotiz wurde vollständig gelöscht." : "Teamnotiz wurde nicht gefunden."));
            openNotesList(admin, target.uuid, 0);
            return;
        }
        if (a.equals("delete-warning")) {
            boolean removed = target.warnings.remove(action.value);
            if (removed) { target.addAction("Einzelne Warnung durch " + admin.getName() + " gelöscht"); database.save(target); audit.log(admin.getName(), target.uuid, "Warnung gelöscht", action.value); }
            menuNotice(admin,prefix() + (removed ? "Warnung wurde vollständig gelöscht." : "Warnung wurde nicht gefunden."));
            openWarningsList(admin, target.uuid, 0);
            return;
        }
        if (a.equals("right")) {
            boolean block = Boolean.parseBoolean(action.reason);
            setRight(admin.getName(), target, action.value, block);
            menuNotice(admin,prefix() + RIGHT_NAMES.get(action.value) + " wurde für " + target.name + " " + (block ? "gesperrt" : "erlaubt") + ".");
            openRights(admin, target.uuid);
            return;
        }
        if (a.equals("allrights-on") || a.equals("allrights-off")) {
            boolean block = a.endsWith("off");
            for (String right : RIGHTS) target.setBlocked(right, block);
            target.addAction("Alle Rechte durch " + admin.getName() + " " + (block ? "gesperrt" : "erlaubt"));
            database.save(target);
            notifyRights(target);
            audit.log(admin.getName(), target.uuid, block ? "Alle Rechte gesperrt" : "Alle Rechte erlaubt", "Bulk-Rechteaktion");
            if (powerTools != null) powerTools.rightsChanged(admin.getName(), target.uuid);
            openRights(admin, target.uuid);
            return;
        }
        if (a.equals("warn")) { addWarning(admin, target, action.reason, true); openWarnings(admin, target.uuid); return; }
        if (a.equals("clearwarnings")) {
            target.warnings.clear(); target.addAction("Alle Warnungen durch " + admin.getName() + " gelöscht"); database.save(target); audit.log(admin.getName(), target.uuid, "Warnungen gelöscht", "Alle internen Warnungen gelöscht"); menuNotice(admin,prefix() + "Warnungen gelöscht."); openWarnings(admin, target.uuid); return;
        }
        if (a.equals("clear-notes")) { clearNotes(admin, target); openNotes(admin, target.uuid); return; }
        if (a.equals("restore-snapshot")) { restoreSnapshot(admin, target, action.value); openSnapshots(admin, target.uuid); return; }
        if (a.equals("restore-latest-snapshot")) { restoreLatestSnapshot(admin, target); openSnapshots(admin, target.uuid); return; }
        if (a.equals("delete-snapshot")) { deleteSnapshot(admin, target, action.value); openSnapshots(admin, target.uuid); return; }
        if (a.equals("clear-chat")) { clearDisposableData(admin, target, "chat"); openPlayer(admin, target.uuid); return; }
        if (a.equals("clear-actions")) { clearDisposableData(admin, target, "aktionen"); openPlayer(admin, target.uuid); return; }
        if (a.equals("clear-disposable")) { clearDisposableData(admin, target, "all"); openPlayer(admin, target.uuid); return; }
        boolean ok;
        ok = executePunishment(admin, a, target, target.name, action.value, action.reason);
        if (ok) {
            target.addAction("Bestätigte Menüaktion durch " + admin.getName() + ": " + a + " " + action.value + " " + action.reason);
            database.save(target);
            audit.log(admin.getName(), target.uuid, "Strafaktion", a + " " + action.value + " " + action.reason);
            admin.sendMessage(prefix() + "Aktion ausgeführt: " + a + " für " + target.name + ".");
        } else menuNotice(admin,prefix() + "Aktion konnte nicht ausgeführt werden. Prüfe LiteBans/Commands.");
        openPunish(admin, target.uuid);
    }

    private void addWarning(CommandSender admin, PlayerProfile target, String reason, boolean useLiteBans) {
        if (!has(admin, "simplexadminsuite.warns")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.warns."); return; }
        reason = sanitizeText(reason, getConfig().getInt("punishments.max-reason-length", 240));
        if (reason.isEmpty()) reason = "No reason provided";
        String line = stamp() + " " + admin.getName() + ": " + reason;
        target.warnings.add(line);
        trim(target.warnings, getConfig().getInt("storage.max-warnings", 80));
        target.addAction("Warnung durch " + admin.getName() + ": " + reason);
        database.save(target);
        boolean lb = useLiteBans && punishments.syncWarning(target.name, reason);
        audit.log(admin.getName(), target.uuid, "Warnung", reason + (lb ? " | LiteBans ausgeführt" : " | intern gespeichert"));
        menuNotice(admin,prefix() + "Warnung gespeichert" + (lb ? " und an LiteBans gesendet" : "") + ".");
        Player online = Bukkit.getPlayerExact(target.name);
        if (online != null) online.sendMessage(prefix() + playerText(online,"Du hast eine Verwarnung vom Team erhalten: ","You have received a warning from staff: ")+reason);
    }

    private void setRight(String admin, PlayerProfile target, String right, boolean blocked) {
        if(suitePolicies!=null)suitePolicies.recordRight(target.uuid,right,blocked);
        target.setBlocked(right, blocked);
        target.addAction("Recht durch " + admin + " geändert: " + right + " = " + (blocked ? "dauerhaft gesperrt" : "erlaubt"));
        database.save(target);
        notifyRights(target);
        audit.log(admin, target.uuid, "Recht geändert", right + " = " + (blocked ? "dauerhaft gesperrt" : "erlaubt"));
        if (powerTools != null) powerTools.rightsChanged(admin, target.uuid);
    }

    private void setTemporaryRight(String admin, PlayerProfile target, String right, String duration, long until) {
        target.setTemporaryBlocked(right, until);
        target.addAction("Recht durch " + admin + " temporär gesperrt: " + right + " für " + duration + " (bis " + time(until) + ")");
        database.save(target);
        notifyRights(target);
        audit.log(admin, target.uuid, "Recht temporär gesperrt", right + " | Dauer=" + duration + " | bis=" + until);
        if (powerTools != null) powerTools.rightsChanged(admin, target.uuid);
    }

    boolean dimensionBlocked(Player player,Location location){
        if(location==null||location.getWorld()==null)return false;PlayerProfile profile=database.get(player.getUniqueId());if(profile==null)return false;
        return location.getWorld().getEnvironment()==World.Environment.NETHER&&profile.isBlocked("nether")||location.getWorld().getEnvironment()==World.Environment.THE_END&&profile.isBlocked("end");
    }
    void enforceDimension(Player player){
        if(!dimensionBlocked(player,player.getLocation()))return;
        for(World world:Bukkit.getWorlds())if(world.getEnvironment()==World.Environment.NORMAL){
            Location spawn=world.getSpawnLocation();
            // Evacuation is an administrative correction, not a player teleport privilege.
            dimensionEvacuations.add(player.getUniqueId());try{if(!player.teleport(spawn))suiteKick(player,playerText(player,"Der Zugang zu dieser Dimension wurde entzogen.","Your access to this dimension was revoked."));}finally{dimensionEvacuations.remove(player.getUniqueId());}return;
        }
        suiteKick(player,playerText(player,"Der Zugang zu dieser Dimension wurde entzogen.","Your access to this dimension was revoked."));
    }
    private final Set<UUID> dimensionEvacuations=new HashSet<>();
    @EventHandler public void dimensionChanged(org.bukkit.event.player.PlayerChangedWorldEvent event){enforceDimension(event.getPlayer());}
    @EventHandler(priority=EventPriority.MONITOR) public void dimensionJoin(org.bukkit.event.player.PlayerJoinEvent event){Bukkit.getScheduler().runTask(this,()->enforceDimension(event.getPlayer()));}
    private void notifyRights(PlayerProfile target) {
        Player online = Bukkit.getPlayer(target.uuid);
        if (online != null) { enforceDimension(online); online.sendMessage(prefix() + "Your server permissions have been updated by an admin."); }
    }

    private void startTemporaryRightsCleanup() {
        if (temporaryRightsTask != null) {
            try { temporaryRightsTask.cancel(); } catch (Exception ignored) { }
        }
        temporaryRightsTask = Bukkit.getScheduler().runTaskTimer(this, this::expireTemporaryRights, 20L, 1200L);
    }

    private void expireTemporaryRights() {
        if (database == null) return;
        List<PlayerProfile> expired = database.expireTemporaryRights(System.currentTimeMillis());
        for (PlayerProfile profile : expired) {
            database.save(profile);
            Player online = Bukkit.getPlayer(profile.uuid);
            if (online != null) online.sendMessage(prefix() + "One or more temporary server-permission restrictions have expired.");
        }
    }

    private void startAutoSnapshots() {
        if (!getConfig().getBoolean("snapshots.auto-enabled", true)) return;
        long minutes = Math.max(1L, getConfig().getLong("snapshots.auto-interval-minutes", 30L));
        long ticks = minutes * 60L * 20L;
        autoSnapshotTask = Bukkit.getScheduler().runTaskTimer(this, this::createAutomaticSnapshots, ticks, ticks);
    }

    private void createAutomaticSnapshots() {
        for (Player online : Bukkit.getOnlinePlayers()) {
            try {
                PlayerProfile profile = database.touch(online);
                createSnapshotInternal(null, profile, online, "auto");
            } catch (Exception e) {
                getLogger().warning("Auto-Snapshot konnte nicht erstellt werden: " + e.getMessage());
            }
        }
    }

    private void createSnapshot(Player admin, PlayerProfile target) {
        if (!has(admin, "simplexadminsuite.snapshots")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.snapshots."); return; }
        Player online = Bukkit.getPlayerExact(target.name);
        if (online == null) { admin.sendMessage(prefix() + "Snapshot geht nur, wenn der Spieler online ist."); return; }
        File file = createSnapshotInternal(admin, target, online, "manual");
        if (file != null) admin.sendMessage(prefix() + "Snapshot erstellt: " + file.getName() + " (" + ageText(file.lastModified()) + ")");
    }

    private File createSnapshotInternal(Player admin, PlayerProfile target, Player online, String source) {
        File dir = snapshotFolder(target.uuid);
        if (!dir.exists()) dir.mkdirs();
        File file = uniqueSnapshotFile(dir, source);
        try {
            YamlConfiguration yaml = new YamlConfiguration();
            long now = System.currentTimeMillis();
            yaml.set("created", now);
            yaml.set("source", source);
            yaml.set("created-by", admin == null ? "AUTO" : admin.getName());
            yaml.set("player.uuid", target.uuid.toString());
            yaml.set("player.name", target.name);
            StoredLocation loc = StoredLocation.from(online.getLocation());
            yaml.set("location", loc == null ? null : loc.encode());
            yaml.set("gamemode", online.getGameMode().name());
            yaml.set("level", online.getLevel());
            yaml.set("food", online.getFoodLevel());
            yaml.set("health", online.getHealth());
            yaml.set("inventory", Arrays.asList(online.getInventory().getContents()));
            yaml.set("armor", Arrays.asList(online.getInventory().getArmorContents()));
            yaml.set("enderchest", Arrays.asList(online.getEnderChest().getContents()));
            yaml.save(file);
            if (source.equals("manual")) {
                target.addAction("Snapshot erstellt durch " + admin.getName() + ": " + file.getName());
                audit.log(admin.getName(), target.uuid, "Snapshot erstellt", file.getName());
            }
            database.save(target);
            pruneSnapshots(target.uuid);
            return file;
        } catch (Exception e) {
            if (admin != null) menuNotice(admin,prefix() + "Snapshot konnte nicht gespeichert werden: " + e.getMessage());
            else getLogger().warning("Auto-Snapshot konnte nicht gespeichert werden: " + e.getMessage());
            return null;
        }
    }

    private File uniqueSnapshotFile(File dir, String source) {
        String safeSource = source == null || source.trim().isEmpty() ? "manual" : source.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_-]", "");
        String stamp = new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss", Locale.GERMANY).format(new Date());
        File file = new File(dir, "snapshot-" + stamp + "-" + safeSource + ".yml");
        int i = 2;
        while (file.exists()) file = new File(dir, "snapshot-" + stamp + "-" + safeSource + "-" + (i++) + ".yml");
        return file;
    }

    private void pruneSnapshots(UUID uuid) {
        int max = Math.max(1, getConfig().getInt("snapshots.max-per-player", DEFAULT_MAX_SNAPSHOTS));
        File[] files = snapshotFiles(uuid);
        for (int i = max; i < files.length; i++) {
            try { files[i].delete(); } catch (Exception ignored) {}
        }
    }

    private void restoreLatestSnapshot(Player admin, PlayerProfile target) {
        File latest = latestSnapshot(target.uuid);
        if (latest == null) { admin.sendMessage(prefix() + "Kein Snapshot gefunden."); return; }
        restoreSnapshot(admin, target, latest.getName());
    }

    private void restoreSnapshot(Player admin, PlayerProfile target, String fileName) {
        if (!has(admin, "simplexadminsuite.snapshots")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.snapshots."); return; }
        Player online = Bukkit.getPlayerExact(target.name);
        if (online == null) { admin.sendMessage(prefix() + "Wiederherstellung geht nur, wenn der Spieler online ist."); return; }
        File snapshot = snapshotFile(target.uuid, fileName);
        if (snapshot == null || !snapshot.exists()) { menuNotice(admin,prefix() + "Snapshot nicht gefunden: " + fileName); return; }
        try {
            YamlConfiguration yaml = YamlConfiguration.loadConfiguration(snapshot);
            online.getInventory().setContents(toItems(yaml.getList("inventory"), online.getInventory().getSize()));
            online.getInventory().setArmorContents(toItems(yaml.getList("armor"), 4));
            online.getEnderChest().setContents(toItems(yaml.getList("enderchest"), online.getEnderChest().getSize()));
            if (isGameModeOperator(admin)) {
                try { online.setGameMode(GameMode.valueOf(yaml.getString("gamemode", online.getGameMode().name()))); } catch (Exception ignored) {}
            } else {
                menuNotice(admin,prefix() + "Der Spielmodus aus dem Snapshot wurde nicht übernommen, weil du kein Server-Operator bist.");
            }
            online.setLevel(yaml.getInt("level", online.getLevel()));
            online.setFoodLevel(yaml.getInt("food", online.getFoodLevel()));
            try { online.setHealth(Math.min(online.getMaxHealth(), Double.parseDouble(String.valueOf(yaml.getString("health", String.valueOf(online.getHealth())))))); } catch (Exception ignored) {}
            StoredLocation loc = StoredLocation.decode(yaml.getString("location"));
            if (loc != null && loc.toLocation() != null) online.teleport(loc.toLocation());
            online.updateInventory();
            target.addAction("Snapshot wiederhergestellt durch " + admin.getName() + ": " + snapshot.getName());
            database.save(target);
            audit.log(admin.getName(), target.uuid, "Snapshot wiederhergestellt", snapshot.getName());
            admin.sendMessage(prefix() + "Snapshot wiederhergestellt: " + snapshot.getName() + " (" + ageText(snapshot.lastModified()) + ")");
            online.sendMessage(prefix() + "Your inventory snapshot was restored by staff.");
        } catch (Exception e) { menuNotice(admin,prefix() + "Snapshot konnte nicht geladen werden: " + e.getMessage()); }
    }

    private void deleteSnapshot(Player admin, PlayerProfile target, String fileName) {
        if (!has(admin, "simplexadminsuite.snapshots")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.snapshots."); return; }
        File snapshot = snapshotFile(target.uuid, fileName);
        if (snapshot == null || !snapshot.exists()) { menuNotice(admin,prefix() + "Snapshot nicht gefunden: " + fileName); return; }
        String age = ageText(snapshot.lastModified());
        if (snapshot.delete()) {
            target.addAction("Snapshot gelöscht durch " + admin.getName() + ": " + fileName);
            database.save(target);
            audit.log(admin.getName(), target.uuid, "Snapshot gelöscht", fileName + " | " + age);
            menuNotice(admin,prefix() + "Snapshot gelöscht: " + fileName + " (" + age + ")");
        } else menuNotice(admin,prefix() + "Snapshot konnte nicht gelöscht werden: " + fileName);
    }

    private ItemStack[] toItems(List<?> list, int size) {
        ItemStack[] items = new ItemStack[size];
        if (list == null) return items;
        for (int i = 0; i < Math.min(size, list.size()); i++) if (list.get(i) instanceof ItemStack) items[i] = (ItemStack) list.get(i);
        return items;
    }

    private void listSnapshots(CommandSender sender, PlayerProfile target) {
        File[] files = snapshotFiles(target.uuid);
        if (files.length == 0) { sender.sendMessage(prefix() + "Keine Snapshots vorhanden."); return; }
        sender.sendMessage(color("&8&m----------&r &dSnapshots von " + target.name + " &8&m----------"));
        int max = Math.min(files.length, Math.max(1, getConfig().getInt("snapshots.max-list-command", 100)));
        for (int i = 0; i < max; i++) {
            sender.sendMessage(color("&7" + (i + 1) + ". &f" + files[i].getName() + " &8| &7Alter: &f" + ageText(files[i].lastModified()) + " &8| &7" + files[i].length() + " Bytes"));
        }
        sender.sendMessage(color("&7Wiederherstellen: &f/sas snapshot restore " + target.name + " <Dateiname>"));
        sender.sendMessage(color("&7Löschen: &f/sas snapshot delete " + target.name + " <Dateiname>"));
    }

    private File snapshotFolder(UUID uuid) { return new File(new File(getDataFolder(), "players" + File.separator + uuid), "snapshots"); }
    private File[] snapshotFiles(UUID uuid) {
        File dir = snapshotFolder(uuid);
        File[] files = dir.listFiles((d, n) -> n.endsWith(".yml"));
        if (files == null) return new File[0];
        Arrays.sort(files, Comparator.comparingLong(File::lastModified).reversed());
        return files;
    }
    private File latestSnapshot(UUID uuid) { File[] files = snapshotFiles(uuid); return files.length == 0 ? null : files[0]; }
    private File snapshotFile(UUID uuid, String fileName) {
        if (fileName == null || fileName.contains("..") || fileName.contains("/") || fileName.contains("\\")) return null;
        File file = new File(snapshotFolder(uuid), fileName);
        return file.getName().equals(fileName) ? file : null;
    }
    private String readableSnapshotName(String fileName) {
        if (fileName == null) return "Snapshot";
        String value = fileName.replace("snapshot-", "").replace(".yml", "");
        if (value.matches("\\d{4}-\\d{2}-\\d{2}_\\d{2}-\\d{2}-\\d{2}.*")) return value.substring(8,10) + "." + value.substring(5,7) + "." + value.substring(0,4) + " " + value.substring(11,13) + ":" + value.substring(14,16) + ":" + value.substring(17,19) + (value.contains("auto") ? " &8(Auto)" : " &8(Manuell)");
        if (value.matches("\\d{8}-\\d{6}")) return value.substring(6,8) + "." + value.substring(4,6) + "." + value.substring(0,4) + " " + value.substring(9,11) + ":" + value.substring(11,13) + ":" + value.substring(13,15);
        return value;
    }

    private void clearDisposableData(CommandSender admin, PlayerProfile target, String type) {
        String normalized = type == null ? "" : type.toLowerCase(Locale.ROOT);
        boolean changed = false;
        if (normalized.equals("chat") || normalized.equals("all")) { target.recentChat.clear(); changed = true; }
        if (normalized.equals("aktionen") || normalized.equals("actions") || normalized.equals("logs") || normalized.equals("all")) { target.recentActions.clear(); changed = true; }
        if (normalized.equals("warnungen") || normalized.equals("warnings")) { target.warnings.clear(); changed = true; }
        if (!changed) {
            admin.sendMessage(prefix() + "Unbekannter Datentyp. Möglich: chat, aktionen, logs, warnungen, all.");
            return;
        }
        target.addAction("Wegwerfdaten gelöscht durch " + admin.getName() + ": " + normalized);
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Wegwerfdaten gelöscht", normalized);
        menuNotice(admin,prefix() + "Wegwerfdaten gelöscht: " + normalized + " für " + target.name + ".");
    }

    private String ageText(long timestamp) {
        long diff = Math.max(0L, System.currentTimeMillis() - timestamp);
        long seconds = diff / 1000L;
        if (seconds < 60) return "gerade eben";
        long minutes = seconds / 60L;
        if (minutes < 60) return minutes == 1 ? "vor 1 Minute" : "vor " + minutes + " Minuten";
        long hours = minutes / 60L;
        if (hours < 24) return hours == 1 ? "vor 1 Stunde" : "vor " + hours + " Stunden";
        long days = hours / 24L;
        if (days < 7) return days == 1 ? "vor 1 Tag" : "vor " + days + " Tagen";
        long weeks = days / 7L;
        if (weeks < 5) return weeks == 1 ? "vor 1 Woche" : "vor " + weeks + " Wochen";
        long months = days / 30L;
        if (months < 12) return months == 1 ? "vor 1 Monat" : "vor " + months + " Monaten";
        long years = days / 365L;
        return years <= 1 ? "vor 1 Jahr" : "vor " + years + " Jahren";
    }

    private void searchProfile(CommandSender sender, PlayerProfile target, String type, String query) {
        List<String> source;
        if (type.equalsIgnoreCase("chat")) source = target.recentChat;
        else if (type.equalsIgnoreCase("warnungen") || type.equalsIgnoreCase("warnings")) source = target.warnings;
        else source = target.recentActions;
        String q = query.toLowerCase(Locale.ROOT);
        List<String> result = source.stream().filter(s -> s.toLowerCase(Locale.ROOT).contains(q)).collect(Collectors.toList());
        Collections.reverse(result);
        sendList(sender, "Suchergebnisse " + target.name + " / " + type + " / " + query, result, 15);
        audit.log(sender.getName(), target.uuid, "Suche", type + " | " + query + " | Treffer: " + result.size());
    }

    private void sendList(CommandSender sender, String title, List<String> lines, int max) {
        sender.sendMessage(color("&8&m----------&r &b" + title + " &8&m----------"));
        if (lines == null || lines.isEmpty()) { sender.sendMessage(color("&7Keine Einträge.")); return; }
        int start = Math.max(0, lines.size() - max);
        for (int i = start; i < lines.size(); i++) sender.sendMessage(color("&7- &f" + lines.get(i)));
    }

    private void openAdminMenu(Player player) {
        if (!adminMenuAllowed(player, "suite.openadminmenu")) return;
        if (getConfig().getBoolean("floodgate.prefer-bedrock-forms", true) && bedrockMenus.isBedrock(player)) {
            player.closeInventory();
            if (bedrockMenus.openMain(player)) return;
            menuNotice(player,prefix() + "Bedrock-Form konnte nicht geöffnet werden; Java-Menü wird als Fallback genutzt.");
        }
        openMain(player);
    }

    private void openAdminQualityMenu(Player player, String module) {
        if (!adminMenuAllowed(player, "suite.openadminqualitymenu")) return;
        if (player == null || !require(player, "simplexadminsuite.qol")) return;
        String normalized = module == null ? "qol" : module.toLowerCase(Locale.ROOT);
        boolean bedrock = getConfig().getBoolean("floodgate.prefer-bedrock-forms", true)
                && bedrockMenus != null && bedrockMenus.isBedrock(player);
        if (bedrock) {
            player.closeInventory();
            boolean opened;
            if (is(normalized, "aufgaben", "tasks")) opened = bedrockMenus.openQolTasks(player);
            else if (is(normalized, "planer", "scheduler")) opened = bedrockMenus.openQolScheduler(player);
            else if (normalized.equals("incidents")) opened = bedrockMenus.openQolIncidents(player);
            else if (normalized.equals("health")) opened = bedrockMenus.openQolHealth(player);
            else if (is(normalized, "makros", "macros")) opened = bedrockMenus.openQolMacros(player);
            else if (normalized.equals("bulk")) opened = bedrockMenus.openQolBulk(player);
            else if (is(normalized, "timeline", "chronik")) opened = bedrockMenus.openQolTimeline(player);
            else opened = bedrockMenus.openAdminQuality(player);
            if (opened) return;
            menuNotice(player,prefix() + "Bedrock-Form konnte nicht geöffnet werden; Java-Menü wird als Fallback genutzt.");
        }
        if (is(normalized, "aufgaben", "tasks")) adminQuality.openTasksJava(player, 0);
        else if (is(normalized, "planer", "scheduler")) adminQuality.openSchedulesJava(player, 0);
        else if (normalized.equals("incidents")) adminQuality.openIncidentsJava(player);
        else if (normalized.equals("health")) adminQuality.openHealthJava(player);
        else if (is(normalized, "makros", "macros")) adminQuality.openMacrosJava(player, 0);
        else if (normalized.equals("bulk")) adminQuality.openBulkJava(player);
        else if (is(normalized, "timeline", "chronik")) adminQuality.openTimelineJava(player, 0);
        else adminQuality.openDashboardJava(player);
    }

