    String platformLabel(PlayerProfile profile) {
        if (profile == null) return "Unknown";
        ConnectionClient current = profile.liveClient;
        if (current != null) return current.label(false);
        if ("JAVA".equalsIgnoreCase(profile.clientPlatform)) return ConnectionClient.javaLabel(profile.javaClientBrand);
        if (!"BEDROCK".equalsIgnoreCase(profile.clientPlatform)) return "Unknown";
        String model = profile.currentDeviceModel == null ? profile.bedrockDeviceModel : profile.currentDeviceModel;
        return DeviceNames.connectionDevice(model, profile.clientDevice.isBlank() ? profile.bedrockDeviceOs : profile.clientDevice, false);
    }

    String connectionLabel(Player player, PlayerProfile profile, boolean german) {
        ConnectionClient current = profile == null ? null : profile.liveClient;
        if (current != null && current.player == player) {current.refreshJava(); return current.label(german);}
        // No current observation means a generic live platform, never a saved model.
        if (!isBedrockClient(player)) {
            ConnectionClient fallback = new ConnectionClient(player, false, "", System.currentTimeMillis());
            fallback.refreshJava(); return fallback.label(german);
        }
        ClientInfo info = bedrockMenus.clientInfo(player);
        return DeviceNames.connectionDevice("", info == null ? "" : info.device, german);
    }

    String platformEmoji(PlayerProfile profile) {
        String platform = platformLabel(profile);
        if (platform.contains("PlayStation")) return "🎮";
        if (platform.contains("Nintendo")) return "🔴";
        if (platform.contains("Xbox")) return "🟢";
        if (platform.contains("iOS") || platform.contains("iPhone") || platform.contains("iPad")) return "🍎";
        if (platform.contains("Android")) return "📱";
        if (platform.contains("Windows")) return "🖥️";
        if (platform.contains("Fabric")) return "🧵";
        if (platform.startsWith("Java")) return "☕";
        return "🎮";
    }

