    List<DiscordBotManager.PlayerSnapshot> discordPlayerSnapshots() {
        List<DiscordBotManager.PlayerSnapshot> players = new ArrayList<>();
        for (Player online : Bukkit.getOnlinePlayers()) {
            if (isPubliclyHidden(online)) continue;
            PlayerProfile profile = database.touch(online);
            updateClientInfo(online, profile);
            players.add(new DiscordBotManager.PlayerSnapshot(online.getName(), platformLabel(profile), platformEmoji(profile),
                    expansionIsAfk(online)));
        }
        players.sort(Comparator.comparing(snapshot -> snapshot.name.toLowerCase(Locale.ROOT)));
        return players;
    }

