    ServerStatistics.Live statisticsLive() {
        World world=Bukkit.getWorld(getConfig().getString("scoreboard.main-world","world"));
        if(world!=null&&world.getEnvironment()!=World.Environment.NORMAL)world=null;
        long ticks=world==null?0:Math.floorMod(world.getTime(),24000);
        String phase=world==null?"Unavailable":ticks<12000?"Day":ticks<13000?"Sunset":ticks<23000?"Night":"Sunrise";
        long minutes=(ticks/1000*60+(ticks%1000)*60/1000+360)%1440;
        String clock=world==null?"--:--":String.format(Locale.ROOT,"%02d:%02d",minutes/60,minutes%60);
        List<DiscordBotManager.PlayerSnapshot> players=discordPlayerSnapshots();int j=0,b=0;
        for(Player online:Bukkit.getOnlinePlayers()){if(isPubliclyHidden(online))continue;PlayerProfile p=database.get(online.getUniqueId());if(p!=null&&"BEDROCK".equals(p.clientPlatform))b++;else j++;}
        if(System.currentTimeMillis()-worldStatsAt>=60000){worldStatsChunks=0;worldStatsEntities=0;for(World w:Bukkit.getWorlds()){worldStatsChunks+=w.getLoadedChunks().length;worldStatsEntities+=w.getEntities().size();}worldStatsAt=System.currentTimeMillis();}
        int chunks=worldStatsChunks,entities=worldStatsEntities;
        double cpu=-1;try { java.lang.management.OperatingSystemMXBean os=java.lang.management.ManagementFactory.getOperatingSystemMXBean();
            if(os instanceof com.sun.management.OperatingSystemMXBean bean)cpu=bean.getProcessCpuLoad(); }catch(Throwable ignored){}
        Runtime r=Runtime.getRuntime();return new ServerStatistics.Live(world==null?"unavailable":world.getUID().toString(),world==null?"Unavailable":world.getName(),world==null?null:world.getWorldFolder().toPath().resolve("playerdata"),scoreboardMainDays(),phase,clock,players.size(),j,b,serverMaxPlayers(),discordAdminTps(),cpu,r.totalMemory()-r.freeMemory(),r.maxMemory(),chunks,entities,System.currentTimeMillis()-suiteBootTime);
    }

