    private boolean isPubliclyHidden(Player player) {
        if (moderationControl != null && moderationControl.ghost(player)) return true;
        if (adminRuntime != null && (adminRuntime.vanished(player) || adminRuntime.blocked(player))) return true;
        if (player == null) return true;
        if (adminSpy != null && adminSpy.hiddenTab(player)) return true;
        try {
            Object has = player.getClass().getMethod("hasMetadata", String.class).invoke(player, "vanished");
            if (!Boolean.TRUE.equals(has)) return false;
            Object values = player.getClass().getMethod("getMetadata", String.class).invoke(player, "vanished");
            if (values instanceof Collection<?>) {
                for (Object value : (Collection<?>) values) {
                    Object hidden = value.getClass().getMethod("asBoolean").invoke(value);
                    if (Boolean.TRUE.equals(hidden)) return true;
                }
            }
        } catch (Throwable ignored) { }
        return false;
    }

    private boolean require(Player player, String permission) {
        if (has(player, permission)) return true;
        player.sendMessage(playerUiText(player, prefix() + "Dafür fehlt dir " + permission + "."));
        return false;
    }

    private ConnectionClient ensureConnectionClient(Player player, PlayerProfile profile) {
        ClientInfo info = bedrockMenus == null ? ClientInfo.javaClient() : bedrockMenus.clientInfo(player);
        if (info == null) info = ClientInfo.javaClient();
        boolean bedrock = "BEDROCK".equalsIgnoreCase(info.platform);
        ConnectionClient current = profile.liveClient;
        if (current == null || current.player != player || current.bedrock != bedrock) {
            long started = current != null && current.player == player ? current.startedAt : System.currentTimeMillis();
            current = new ConnectionClient(player, bedrock, info.device, started);
            profile.liveClient = current;
            profile.currentDeviceModel = "";
        }
        current.refreshJava();
        return current;
    }

    private void updateClientInfo(Player player, PlayerProfile profile) {
        ConnectionClient current = ensureConnectionClient(player, profile);
        ClientInfo info = bedrockMenus.clientInfo(player);
        if (info == null) info = ClientInfo.javaClient();
        profile.clientPlatform = info.platform;
        profile.clientDevice = info.device;
        profile.clientInput = info.input;
        profile.clientVersion = info.version;
        profile.clientLanguage = info.language;
        if (altDetection != null) altDetection.capture(player, profile);
        profile.currentDeviceModel = current.model();
        if (powerTools != null) powerTools.identityUpdated(profile);
    }

