    Map<String,Object> securityDossier(UUID id,boolean fullIp,boolean checks){
        PlayerProfile p=database.get(id);if(p==null)return Map.of("uuid",id.toString());Player online=Bukkit.getPlayer(id);
        Map<String,Object> out=new LinkedHashMap<>();out.put("uuid",id.toString());out.put("name",p.name);out.put("observedAt",java.time.Instant.now().toString());out.put("platform",p.clientPlatform);out.put("firstSeen",p.firstSeen);out.put("versionHint",p.clientVersion);out.put("ipPseudonym",p.lastIpHash);
        if(fullIp&&online!=null&&online.getAddress()!=null)out.put("ip",online.getAddress().getAddress().getHostAddress());
        else if(online!=null&&online.getAddress()!=null){byte[] ip=online.getAddress().getAddress().getAddress();out.put("ipMasked",ip.length==4?(ip[0]&255)+"."+(ip[1]&255)+"."+(ip[2]&255)+".x":"IPv6 / pseudonym only");}
        out.put("reportedMetadataWarning","Client-supplied values are not proof of identity or cheating. IP location is approximate.");
        if("BEDROCK".equals(p.clientPlatform)){
            Map<String,Object> bedrock=new LinkedHashMap<>();bedrock.put("xuidPseudonym",p.bedrockXuidHash);bedrock.put("deviceIdPseudonym",p.bedrockDeviceIdHash);bedrock.put("selfSignedPseudonym",p.bedrockSelfSignedIdHash);bedrock.put("model",p.bedrockDeviceModel);bedrock.put("os",p.bedrockDeviceOs);bedrock.put("language",p.clientLanguage);bedrock.put("ui",p.bedrockUiProfile);bedrock.put("guiScale",p.bedrockGuiScale);bedrock.put("input",p.bedrockCurrentInput);bedrock.put("defaultInput",p.bedrockDefaultInput);bedrock.put("reportedDiagnostics",new LinkedHashMap<>(p.bedrockDiagnostics));out.put("bedrock",bedrock);
        }else{
            Map<String,Object> java=new LinkedHashMap<>();java.put("brand",p.javaClientBrand);java.put("protocol",p.javaProtocolVersion);java.put("locale",p.javaLocale);java.put("viewDistance",p.javaClientViewDistance);java.put("ping",online==null?p.javaLastPing:online.getPing());java.put("registeredChannels",new ArrayList<>(p.javaRegisteredChannels));java.put("channelModHints",new ArrayList<>(p.javaDetectedMods));java.put("reportedDiagnostics",new LinkedHashMap<>(p.javaDiagnostics));out.put("java",java);
        }
        if(checks&&qualityOfLife!=null)out.put("lastKnownProbe",qualityOfLife.probes.reportData(id));if(detectors!=null)out.put("securityHints",detectors.summary(id));out.put("authenticatedLinks",verifiedLinks(id));return out;
    }
    void historicalGeo(java.util.function.BiConsumer<String,String> enqueue){
        if(historicalGeoTask!=null)return;java.util.Iterator<PlayerProfile> profiles=database.sortedProfiles().iterator();
        historicalGeoTask=Bukkit.getScheduler().runTaskTimer(this,()->{if(securityHub==null||!getConfig().getBoolean(ClientControlCenter.ROOT+"geo.enabled",false)||!profiles.hasNext()){if(historicalGeoTask!=null)historicalGeoTask.cancel();historicalGeoTask=null;return;}if(securityHub.geo.pending()>=3500)return;PlayerProfile p=profiles.next();String ip=GeoInsights.publicIp(p.lastIpMasked);if(ip!=null)enqueue.accept(geoIpKey(ip),ip);synchronized(p.devices){for(DeviceRecord d:p.devices.values()){ip=GeoInsights.publicIp(d.lastIp);if(ip!=null)enqueue.accept(geoIpKey(ip),ip);}}},20,20);
    }
    void securityGroups(java.util.function.Consumer<Map<UUID,Set<UUID>>> callback){
        if(altDetection==null)return;Runnable ready=()->{Map<UUID,Set<UUID>> groups=new LinkedHashMap<>();AltMatchCacheEngine.Result cache=altDetection.matchCache;if(cache==null)return;cache.strongComponentRoots.forEach((id,root)->groups.computeIfAbsent(root,k->new LinkedHashSet<>()).add(id));callback.accept(groups);};
        synchronized(altDetection.matchCacheLock){if(altDetection.matchCache!=null&&altDetection.publishedMatchCacheRevision==altDetection.matchCacheRevision){ready.run();return;}altDetection.matchCacheWaiters.add(ready);}altDetection.requestMatchCache(null);
    }

