    List<VpnPlayerRef> vpnPlayers() {
        if (database == null) return Collections.emptyList();
        List<VpnPlayerRef> result = new ArrayList<>();
        for (PlayerProfile profile : database.sortedProfiles()) result.add(new VpnPlayerRef(profile.uuid, profile.name, profile.lastSeen));
        return result;
    }
    VpnPlayerRef vpnPlayer(String query) {
        if (database == null || query == null || query.isBlank()) return null;
        String clean = query.trim();
        try {
            PlayerProfile byUuid = database.get(UUID.fromString(clean));
            if (byUuid != null) return new VpnPlayerRef(byUuid.uuid, byUuid.name, byUuid.lastSeen);
        } catch (Exception ignored) { }
        for (PlayerProfile profile : database.sortedProfiles()) {
            if (profile.name.equalsIgnoreCase(clean) || profile.previousNames.stream().anyMatch(name -> name.equalsIgnoreCase(clean)))
                return new VpnPlayerRef(profile.uuid, profile.name, profile.lastSeen);
        }
        return null;
    }
