        if(german)form.title=PlayerLanguages.translate(form.title);
        for(int n=0;n<form.components.size();n++){FormComponent c=form.components.get(n);String text=brandText(c.text),placeholder=brandText(c.placeholder);form.components.set(n,new FormComponent(c.type,german?PlayerLanguages.translate(text):text,german?PlayerLanguages.translate(placeholder):placeholder,c.defaultText,c.defaultToggle,c.minimum,c.maximum,c.step,c.defaultSlider,c.options.stream().map(value->{String branded=brandText(value);return german?PlayerLanguages.translate(branded):branded;}).toList(),c.defaultOption));}
