    List<String> ownProfileLines(Player viewer) {
        PlayerProfile p = database.get(viewer.getUniqueId()); if(p == null) return List.of();
        synchronized(p) {
            long play=p.totalPlayMillis+(p.currentSessionStartedAt>0?Math.max(0,System.currentTimeMillis()-p.currentSessionStartedAt):0);
            return List.of(playerText(viewer,"Name: ","Name: ")+p.name,
                "UUID: "+p.uuid,
                playerText(viewer,"Frühere Namen: ","Previous names: ")+String.join(", ",p.previousNames),
                playerText(viewer,"Plattform: ","Platform: ")+p.clientPlatform,
                playerText(viewer,"Minecraft-Version: ","Minecraft version: ")+p.clientVersion,
                playerText(viewer,"Erstmals von Simplex erfasst: ","First recorded by Simplex: ")+profileDate(p.firstSeen),
                playerText(viewer,"Seit Simplex-Erfassung: ","Since first Simplex record: ")+(p.firstSeen>0?Math.max(0,System.currentTimeMillis()-p.firstSeen)/86400000+playerText(viewer," Tage"," days"):"—"),
                playerText(viewer,"Letzter Beitritt: ","Last join: ")+profileDate(p.lastJoinAt),
                playerText(viewer,"Sitzungen: ","Sessions: ")+p.sessionCount,
                playerText(viewer,"Spielzeit: ","Playtime: ")+profileDuration(play),
                playerText(viewer,"AFK-Zeit: ","AFK time: ")+profileDuration(p.totalAfkMillis),
                playerText(viewer,"Simplex-Punkte: ","Simplex Points: ")+p.simplexPoints,
                playerText(viewer,"Verwarnungen: ","Warnings: ")+p.warnings.size(),
                playerText(viewer,"Aktive interne Sperre: ","Active internal ban: ")+p.internalBanActive(System.currentTimeMillis()),
                playerText(viewer,"Aktive interne Stummschaltung: ","Active internal mute: ")+p.internalMuteActive(System.currentTimeMillis()),
                playerText(viewer,"Gerät: ","Device: ")+connectionLabel(viewer,p,community!=null&&community.german(viewer)),
                playerText(viewer,"Client-Sprache: ","Client language: ")+p.localeValue());
        }
    }
