    void broadcastConnection(Player joining, PlayerProfile profile, boolean join) {
        for(Player viewer:Bukkit.getOnlinePlayers()) {
            if(community!=null&&!community.joinMessages(viewer))continue;
            String model=connectionLabel(joining,profile,community!=null&&community.german(viewer));
            String action=join?playerText(viewer," ist dem Server beigetreten mit "," joined the server with "):playerText(viewer," hat den Server verlassen."," left the server.");
            int online=join?visibleOnlineCount():visibleOnlineCountExcluding(joining.getUniqueId());
            viewer.sendMessage(color("&8["+(join?"&a+":"&c-")+"&8] &f"+joining.getName()+" &7"+action+(join?"&f"+model+"&7.":"")+" &8(&f"+online+"&7/&f"+serverMaxPlayers()+"&8)"));
        }
    }
    String publicMessage(Player recipient, String path, String fallback, String... replacements) {
        String text = getConfig().getString(path, fallback);
        if(community!=null&&community.german(recipient)) text=getConfig().getString("player-languages.de."+path, PlayerLanguages.translate(text));
        else text=getConfig().getString("player-languages.en."+path,text);
        for(int i=0;i+1<replacements.length;i+=2)text=text.replace("{"+replacements[i]+"}",replacements[i+1]==null?"":replacements[i+1]);
        return color(text);
    }
    String publicMessage(String path, String fallback, String... replacements) {
        String text = getConfig().getString(path, fallback);
        for (int i = 0; i + 1 < replacements.length; i += 2) text = text.replace("{" + replacements[i] + "}", replacements[i + 1] == null ? "" : replacements[i + 1]);
        return color(text);
    }

    private Player findOnline(UUID uuid) { for (Player p : Bukkit.getOnlinePlayers()) if (p.getUniqueId().equals(uuid)) return p; return null; }

    private void openProfile(Player admin, PlayerProfile p) {
        if (!adminMenuAllowed(admin, "suite.openprofile")) return;
        admin.closeInventory();
        admin.sendMessage(color("&8&m----------&r &bProfil: " + p.name + " &8&m----------"));
        admin.sendMessage(color("&7UUID: &f" + p.uuid));
        admin.sendMessage(color("&7Erster Join: &f" + time(p.firstSeen)));
        admin.sendMessage(color("&7Zuletzt gesehen: &f" + time(p.lastSeen)));
        menuNotice(admin,color("&7Letzter Ort: &f" + (p.lastLocation == null ? "Nicht gespeichert" : p.lastLocation.shortText())));
        admin.sendMessage(color("&7Client: &f" + p.clientSummary()));
        admin.sendMessage(color("&7Warnungen: &f" + p.warnings.size()));
        admin.sendMessage(color("&7Teamnotizen: &f" + p.notes.size()));
        admin.sendMessage(color("&7Strafstatus: &f" + punishments.summary(p)));
        admin.sendMessage(color("&7Aktive Sperren: &f" + p.blockedRights().stream().map(RIGHT_NAMES::get).collect(Collectors.joining(", "))));
    }

    private void ask(Player admin, UUID target, String action, String message) {
        ask(admin, target, action, message, "");
    }

    private void ask(Player admin, UUID target, String action, String message, String value) {
        if(appApi!=null && appApi.menus.prompt(admin,message,"",input->completePending(admin,new PendingInput(target,action,value),input)))return;
        pendingInputs.put(admin.getUniqueId(), new PendingInput(target, action, value));
        admin.closeInventory();
        admin.sendMessage(prefix() + message);
    }

    private void teleportToOnline(Player admin, PlayerProfile target) {
        if (!has(admin, "simplexadminsuite.teleport")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.teleport."); return; }
        Player online = Bukkit.getPlayerExact(target.name);
        if (online == null) { admin.sendMessage(prefix() + "Dieser Spieler ist gerade nicht online."); return; }
        admin.teleport(online.getLocation());
        target.addAction(admin.getName() + " hat sich zum Spieler teleportiert");
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Teleport", "zu Online-Spieler");
        admin.sendMessage(prefix() + "Teleportiert zu " + target.name + ".");
    }

    private void teleportToLast(Player admin, PlayerProfile target) {
        if (!has(admin, "simplexadminsuite.teleport")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.teleport."); return; }
        if (target.lastLocation == null) { menuNotice(admin,prefix() + "Kein letzter Ort gespeichert."); return; }
        Location loc = target.lastLocation.toLocation();
        if (loc == null) { admin.sendMessage(prefix() + "Die Welt ist nicht geladen: " + target.lastLocation.world); return; }
        admin.teleport(loc);
        target.addAction(admin.getName() + " hat sich zum letzten Ort teleportiert");
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Teleport", "zum letzten Ort");
        admin.sendMessage(prefix() + "Teleportiert zum letzten Ort von " + target.name + ".");
    }

    private void bringPlayer(Player admin, PlayerProfile target) {
        if (!require(admin, "simplexadminsuite.teleport")) return;
        Player online = Bukkit.getPlayerExact(target.name);
        if (online == null) { admin.sendMessage(prefix() + "Dieser Spieler ist gerade nicht online."); return; }
        online.teleport(admin.getLocation());
        target.addAction("Durch " + admin.getName() + " zum Admin teleportiert");
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Spieler hergeholt", "Teleport zum Admin");
        menuNotice(admin,prefix() + target.name + " wurde zu dir teleportiert.");
        online.sendMessage(prefix()+playerText(online,"Du wurdest zu einem Teammitglied teleportiert.","You were teleported to a staff member."));
    }

    private void setFrozen(CommandSender admin, PlayerProfile target, boolean frozen) {
        if (!has(admin, "simplexadminsuite.freeze")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.freeze."); return; }
        target.setBlocked("move", frozen);
        target.addAction("Freeze durch " + admin.getName() + ": " + (frozen ? "aktiv" : "inaktiv"));
        database.save(target);
        audit.log(admin.getName(), target.uuid, frozen ? "Spieler eingefroren" : "Spieler freigegeben", target.name);
        Player online = Bukkit.getPlayerExact(target.name);
        if (online != null) online.sendMessage(prefix() + publicMessage(online, frozen ? "messages.frozen" : "messages.unfrozen", frozen ? "You have been frozen by staff." : "You are no longer frozen."));
        menuNotice(admin,prefix() + target.name + " wurde " + (frozen ? "eingefroren" : "freigegeben") + ".");
    }

    private void healOrFeed(CommandSender admin, PlayerProfile target, boolean heal, boolean feed) {
        if (!has(admin, "simplexadminsuite.utilities")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.utilities."); return; }
        Player online = Bukkit.getPlayerExact(target.name);
        if (online == null) { admin.sendMessage(prefix() + "Dieser Spieler ist gerade nicht online."); return; }
        if (heal) online.setHealth(online.getMaxHealth());
        if (feed) online.setFoodLevel(20);
        String action = heal && feed ? "geheilt und gesättigt" : heal ? "geheilt" : "gesättigt";
        String playerMessage = heal && feed ? publicMessage("messages.healed", "You have been healed and fed by staff.")
                : heal ? "You have been healed by staff." : "You have been fed by staff.";
        online.sendMessage(prefix() + playerMessage);
        target.addAction("Durch " + admin.getName() + " " + action);
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Spieler " + action, target.name);
        menuNotice(admin,prefix() + target.name + " wurde " + action + ".");
    }

    private void setGameMode(CommandSender admin, PlayerProfile target, String input) {
        if (!has(admin, "simplexadminsuite.gamemode")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.gamemode."); return; }
        if (!isGameModeOperator(admin)) {
            admin.sendMessage(prefix() + "Spielmodusänderungen sind ausschließlich für echte Server-Operatoren erlaubt. Eine Plugin- oder LuckPerms-Berechtigung allein reicht nicht aus.");
            audit.log(admin.getName(), target == null ? null : target.uuid, "Spielmodus verweigert", "Absender ist kein Server-Operator");
            return;
        }
        Player online = Bukkit.getPlayerExact(target.name);
        if (online == null) { admin.sendMessage(prefix() + "Dieser Spieler ist gerade nicht online."); return; }
        String normalized = input == null ? "" : input.toUpperCase(Locale.ROOT);
        if (normalized.equals("S") || normalized.equals("0")) normalized = "SURVIVAL";
        if (normalized.equals("C") || normalized.equals("1")) normalized = "CREATIVE";
        if (normalized.equals("A") || normalized.equals("2")) normalized = "ADVENTURE";
        if (normalized.equals("SP") || normalized.equals("3")) normalized = "SPECTATOR";
        GameMode mode;
        try { mode = GameMode.valueOf(normalized); }
        catch (Exception error) { admin.sendMessage(prefix() + "Unbekannter Spielmodus. Möglich: survival, creative, adventure, spectator."); return; }
        online.setGameMode(mode);
        online.sendMessage(prefix() + publicMessage(online, "messages.gamemode-changed", "Your game mode was changed to {gamemode} by staff.", "gamemode", mode.name()));
        target.addAction("Spielmodus durch " + admin.getName() + " geändert: " + mode.name());
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Spielmodus geändert", mode.name());
        menuNotice(admin,prefix() + "Spielmodus von " + target.name + " wurde auf " + mode.name() + " gesetzt.");
    }

    private void addNote(CommandSender admin, PlayerProfile target, String text) {
        if (!has(admin, "simplexadminsuite.notes")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.notes."); return; }
        String clean = sanitizeText(text, 240);
        if (clean.isEmpty()) { menuNotice(admin,prefix() + "Eine leere Notiz wird nicht gespeichert."); return; }
        target.notes.add(stamp() + " " + admin.getName() + ": " + clean);
        target.staffNotesUpdatedAt = System.currentTimeMillis();
        trim(target.notes, Math.max(1, getConfig().getInt("storage.max-notes", 80)));
        target.addAction("Teamnotiz durch " + admin.getName() + " hinzugefügt");
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Teamnotiz hinzugefügt", clean);
        menuNotice(admin,prefix() + "Teamnotiz für " + target.name + " gespeichert.");
    }

    private void clearNotes(CommandSender admin, PlayerProfile target) {
        if (!has(admin, "simplexadminsuite.notes")) { admin.sendMessage(prefix() + "Dafür fehlt dir simplexadminsuite.notes."); return; }
        int count = target.notes.size();
        target.notes.clear();
        target.staffNotesUpdatedAt = System.currentTimeMillis();
        target.addAction("Alle Teamnotizen durch " + admin.getName() + " gelöscht");
        database.save(target);
        audit.log(admin.getName(), target.uuid, "Teamnotizen gelöscht", "Anzahl: " + count);
        menuNotice(admin,prefix() + "Alle Teamnotizen für " + target.name + " wurden gelöscht.");
    }

    private boolean isGameModeOperator(CommandSender sender) {
        if (sender instanceof ConsoleCommandSender) return true;
        return sender instanceof Player && ((Player) sender).isOp();
    }

    boolean has(CommandSender sender, String permission) {
        boolean inherited = sender.hasPermission(permission) || sender.hasPermission("simplexadminsuite.*") || sender.hasPermission("*");
        if (permission.startsWith("simplexadminsuite.action.")) {
            String action = permission.substring(permission.lastIndexOf('.') + 1);
            inherited = sender.isPermissionSet(permission) ? sender.hasPermission(permission) : inherited || has(sender, Set.of("mute", "tempmute", "unmute").contains(action) ? "simplexadminsuite.mutes" : "simplexadminsuite.bans");
        }
        return adminAccess == null ? inherited : adminAccess.allows(sender, permission, inherited);
    }
    boolean adminSessionUsable(Player p) {
        return p != null && (Bukkit.getPlayer(p.getUniqueId()) == p || appApi != null && appApi.remote(p)) && (adminRuntime == null || !adminRuntime.blocked(p))
                && (adminSecurity == null || !adminSecurity.isLocked(p));
    }
    boolean adminMenuAllowed(Player p, String key) {
        if (p == null) return false;
        if (adminRuntime != null && adminRuntime.blocked(p)) return false;
        if (adminSecurity != null && adminSecurity.isLocked(p)) return false;
        if (adminAccess != null && !adminAccess.allows(p, "simplexadminsuite.menu." + key, true)) {
            p.sendMessage(prefix() + "Dieser Menüpunkt ist für dich gesperrt."); return false;
        }
        return true;
    }
    void invalidateAdminSession(UUID uuid) {
        pendingInputs.remove(uuid); pendingActions.remove(uuid);
        if (adminUpdate != null) adminUpdate.invalidate(uuid);
    }
