    void openMainFromModule(Player player) { if (player != null) openAdminMenu(player); }
    boolean completeStealth(Player player) { return adminSpy != null && adminSpy.hiddenTab(player); }
    void setVisualNickname(Player actor, UUID target, String name) { if (nicknames != null && has(actor,"simplexadminsuite.nickname") && adminSessionUsable(actor)) menuNotice(actor,nicknames.set(actor.getName(),target,name).message); }
    /** Geyser name bridge: main-thread snapshot, only names visible to this viewer. */
    public Map<UUID,String> bedrockPlayerListSnapshot(UUID viewerId) {
        if (!Bukkit.isPrimaryThread()) throw new IllegalStateException("Use the Bukkit main thread");
        Player viewer=Bukkit.getPlayer(viewerId); Map<UUID,String> out=new LinkedHashMap<>();
        if(viewer==null || !getConfig().getBoolean("integrations.geyser-name-bridge.enabled",true))return out;
        for(Player target:Bukkit.getOnlinePlayers())if(target.equals(viewer)||viewer.canSee(target)&&!adminRuntime.vanished(target)) {
            String name=getConfig().getBoolean("integrations.geyser-name-bridge.show-nicknames",false)?stripFormatting(visualName(target)):target.getName();
            out.put(target.getUniqueId(),name+(expansionIsAfk(target)&&getConfig().getBoolean("afk.show-in-player-list",true)?" [AFK]":""));
        }
        return Map.copyOf(out);
    }
