    void handleSuspiciousActivity(Player player, ActivityIntelligence.Evaluation evaluation, boolean sendDiscord, boolean sendWarning) {
        if (player == null || evaluation == null) return;
        if (getConfig().getBoolean("activity-intelligence.suspicious-detection.force-afk", true) && afk != null) afk.forceSuspicious(player);
        if (sendWarning) player.sendMessage(playerUiText(player, prefix() + publicMessage(player, "activity-intelligence.suspicious-detection.player-message",
                "Your current input pattern does not count as active gameplay. You are marked AFK and Simplex Point progress is paused until varied, active play resumes.")));
        PlayerProfile profile = database.touch(player);
        profile.addAction("Verdächtiges AFK-Muster: Punkte pausiert | " + evaluation.reason);
        database.save(profile);
        // Input-pattern hints are local only, including on servers with legacy discord-alerts=true.

    }
    void relayFart(String playerName, String level, String message, int color) { if (discordBot != null) discordBot.relayFart(playerName, level, message, color); }
    void relayBurp(String playerName, String level, String message, int color) { if (discordBot != null) discordBot.relayBurp(playerName, level, message, color); }

    String discordAdminFun(String actor, String feature, String setting, String value) {
        if (funFeatures == null) return "Das Fun-System ist noch nicht initialisiert.";
        String group = feature == null ? "" : feature.trim().toLowerCase(Locale.ROOT);
        String option = setting == null ? "status" : setting.trim().toLowerCase(Locale.ROOT);
        if (group.isBlank()) group = "shared";
        if (option.equals("status")) {
            return "**Fun-System 7.0**\n"
                    + "• `/fart`: " + (funFeatures.fartEnabled() ? "aktiv" : "inaktiv") + ", Cooldown " + funFeatures.fartCooldownSeconds() + "s, " + funFeatures.totalFarts() + " Aktionen\n"
                    + "• `/burp`: " + (funFeatures.burpEnabled() ? "aktiv" : "inaktiv") + ", Cooldown " + funFeatures.burpCooldownSeconds() + "s, " + funFeatures.totalBurps() + " Aktionen\n"
                    + "• Gemeinsamer Cooldown: " + (funFeatures.sharedCooldown() ? "aktiv" : "inaktiv");
        }
        if (option.equals("clear-cooldowns")) {
            funFeatures.clearCooldowns();
            audit.log(actor, null, "Discord Fun-Cooldowns gelöscht", "Furz und Rülpser");
            return "Alle `/fart`- und `/burp`-Cooldowns wurden gelöscht.";
        }
        if (group.equals("shared")) {
            if (!option.equals("enabled")) return "Für `shared` sind nur `status`, `enabled` und `clear-cooldowns` verfügbar.";
            Boolean enabled = parseDiscordToggle(value);
            if (enabled == null) return "Für `value` muss `on` oder `off` angegeben werden.";
            getConfig().set("fun.shared-cooldown", enabled);
            saveConfig();
            audit.log(actor, null, "Gemeinsamer Fun-Cooldown geändert", Boolean.toString(enabled));
            return "Der gemeinsame `/fart`-/`/burp`-Cooldown ist jetzt **" + (enabled ? "aktiv" : "inaktiv") + "**.";
        }
        if (!group.equals("fart") && !group.equals("burp")) return "Unbekanntes Fun-System. Möglich: `fart`, `burp`, `shared`.";
        String base = "fun." + group + ".";
        if (option.equals("cooldown")) {
            int seconds;
            try { seconds = Integer.parseInt(value == null ? "" : value.trim()); }
            catch (Exception ignored) { return "Der Cooldown muss als Zahl in Sekunden angegeben werden."; }
            if (seconds < 1 || seconds > 86400) return "Der Cooldown muss zwischen 1 und 86400 Sekunden liegen.";
            getConfig().set(base + "cooldown-seconds", seconds);
            saveConfig();
            audit.log(actor, null, "Discord Fun-Cooldown geändert", group + "=" + seconds + "s");
            return "Der `/" + group + "`-Cooldown wurde auf **" + seconds + " Sekunden** gesetzt.";
        }
        Map<String, String> paths = Map.of(
                "enabled", "enabled",
                "minecraft-chat", "minecraft-broadcast",
                "discord-relay", "discord-relay",
                "sounds", "sounds",
                "global-sounds", "global-sounds",
                "particles", "particles",
                "variants", "allow-player-variant-selection");
        String suffix = paths.get(option);
        if (suffix == null) return "Unbekannte Einstellung für `" + group + "`.";
        Boolean enabled = parseDiscordToggle(value);
        if (enabled == null) return "Für `value` muss `on` oder `off` angegeben werden.";
        getConfig().set(base + suffix, enabled);
        saveConfig();
        audit.log(actor, null, "Discord Fun-Einstellung geändert", group + "." + suffix + "=" + enabled);
        return "`" + group + "." + suffix + "` ist jetzt **" + (enabled ? "aktiv" : "inaktiv") + "**.";
    }

    private static Boolean parseDiscordToggle(String value) {
        String normalized = value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
        if (normalized.equals("on") || normalized.equals("true") || normalized.equals("an") || normalized.equals("1")) return Boolean.TRUE;
        if (normalized.equals("off") || normalized.equals("false") || normalized.equals("aus") || normalized.equals("0")) return Boolean.FALSE;
        return null;
    }

    void recordFunAction(Player player, String command, String level) {
        if (player == null) return;
        PlayerProfile profile = database.touch(player);
        profile.addAction("Used /" + command + " variant " + level);
        database.save(profile);
    }

    private final ThreadLocal<String> adminActor = new ThreadLocal<>();
    private final Map<String,String> auditedConfig = new HashMap<>();
    private final MenuFeedback menuFeedback = new MenuFeedback(this::playMenuSound);
    String currentAdminActor(){return adminActor.get();}
    void asAdmin(String actor,Runnable action){String previous=adminActor.get();adminActor.set(actor);try{if(menuFeedback==null)action.run();else menuFeedback.run(actor,action);}finally{if(previous==null)adminActor.remove();else adminActor.set(previous);}}
    void menuError(CommandSender actor,String message){if(menuFeedback!=null)menuFeedback.failure(actor.getName());actor.sendMessage(message);}
    void menuSuccess(CommandSender actor){if(menuFeedback!=null)menuFeedback.success(actor.getName());}
    void runAdminTask(Runnable action){String actor=currentAdminActor();Bukkit.getScheduler().runTask(this,()->{if(actor==null)action.run();else asAdmin(actor,action);});}
    void menuNotice(CommandSender actor,String message){
        if (menuAudio != null) menuAudio.hint(actor.getName(), message);
        String text=stripFormatting(message),label=stripFormatting(prefix());
        if(!label.isEmpty()&&text.startsWith(label))text=text.substring(label.length());
        text=text.toLowerCase(Locale.ROOT);
        if(menuFeedback!=null){
            if(text.matches(".*(ungültig|fehlgeschlagen|konnte nicht|können nicht|nicht gefunden|nicht mehr geladen|nicht gespeichert|nicht angelegt|nicht ausgeführt|nicht bestätigt|wurde abgelehnt|darf nicht leer|leere (notiz|warnung|nachricht)|kein wert|keine berechtigung|berechtigung fehlt|kein adminzugriff|wert erforderlich|erlaubt sind|erwartet:).*"))menuFeedback.failure(actor.getName());
            else if(text.matches(".*(erfolgreich|wurde[n]? .*?(gespeichert|geändert|aktualisiert|angelegt|gelöscht|übernommen|aktiviert|deaktiviert|gesetzt|gesperrt|freigegeben|erstellt|geplant)|gespeichert\\.|übernommen\\.|gelöscht\\.|aktualisiert\\.|geleert\\.|geheilt\\.).*"))menuFeedback.success(actor.getName());
        }
        actor.sendMessage(message);
    }
    private void playMenuSound(String actor,boolean success){
        if(actor==null||!isEnabled())return;
        Runnable play=()->{
            Player player=Bukkit.getPlayerExact(actor);
            if(player==null||!player.isOnline()||!getConfig().getBoolean("admin-update.feedback.enabled",true))return;
            if (menuAudio != null) { menuAudio.outcome(player, success); return; }
            String fallback=success?"entity.experience_orb.pickup":"block.note_block.bass";
            String sound=getConfig().getString("admin-update.feedback."+(success?"success-sound":"error-sound"),fallback);
            if(sound==null||sound.isBlank())sound=fallback;
            org.bukkit.NamespacedKey key=org.bukkit.NamespacedKey.fromString(sound);
            if(key==null||org.bukkit.Registry.SOUNDS.get(key)==null)sound=fallback;
            float volume=(float)Math.max(0.0,Math.min(1.0,getConfig().getDouble("admin-update.feedback.volume-percent",65)/100.0));
            if(!Float.isFinite(volume))volume=0.65f;
            try{player.playSound(player.getLocation(),sound,org.bukkit.SoundCategory.MASTER,volume,success?1.25f:0.7f);}
            catch(IllegalArgumentException invalid){player.playSound(player.getLocation(),fallback,org.bukkit.SoundCategory.MASTER,volume,success?1.25f:0.7f);}
        };
        if(Bukkit.isPrimaryThread())play.run();else Bukkit.getScheduler().runTask(this,play);
    }
    static String validatedMenuSound(String value){
        String sound=value==null?"":value.trim();
        org.bukkit.NamespacedKey key=org.bukkit.NamespacedKey.fromString(sound);
        if(key==null||org.bukkit.Registry.SOUNDS.get(key)==null)throw new IllegalArgumentException("Bekannte Minecraft-Sound-ID erforderlich.");
        return sound;
    }
    private void primeConfigAudit(){for(String key:getConfig().getKeys(true))if(!ModerationControl.protectedKey(key)&&!key.contains(".statistics.")&&!(getConfig().get(key) instanceof org.bukkit.configuration.ConfigurationSection))auditedConfig.put(key,String.valueOf(getConfig().get(key)));}
    @Override public synchronized void saveConfig(){
        Map<String,String> next=new java.util.TreeMap<>();
        for(String key:getConfig().getKeys(true))if(!ModerationControl.protectedKey(key)&&!key.contains(".statistics.")&&!(getConfig().get(key) instanceof org.bukkit.configuration.ConfigurationSection))next.put(key,String.valueOf(getConfig().get(key)));
        try{saveAtomic(getConfig(),new File(getDataFolder(),"config.yml"));}
        catch(Exception error){if(menuFeedback!=null)menuFeedback.failure(adminActor.get());throw new IllegalStateException("Einstellungen konnten nicht gespeichert werden.",error);}
        if(menuFeedback!=null)menuFeedback.success(adminActor.get());
        if(moderationControl!=null&&!auditedConfig.isEmpty()){
            List<String> changed=new ArrayList<>();
            for(var entry:next.entrySet())if(!java.util.Objects.equals(auditedConfig.get(entry.getKey()),entry.getValue()))changed.add(entry.getKey()+": "+auditedConfig.getOrDefault(entry.getKey(),"—")+" → "+entry.getValue());
            for(String key:auditedConfig.keySet())if(!next.containsKey(key))changed.add(key+": entfernt");
            if(!changed.isEmpty())suiteAudit(adminActor.get()==null?"System":adminActor.get(),"Konfiguration geändert",String.join(" • ",changed));
        }
        auditedConfig.clear();auditedConfig.putAll(next);
    }
