    private boolean pointsCommand(CommandSender s,String[] args){
        if(!has(s,"simplexadminsuite.points.admin")||s instanceof Player p&&!adminSessionUsable(p))return true;
        if(args.length<2){s.sendMessage("/spcurrency <balance|deposit|withdraw|set> <Spieler> [Betrag] [Grund]");return true;}
        UUID id=discordAdminResolvePlayer(args[1]);if(id==null){s.sendMessage("Spielerprofil nicht gefunden.");return true;}
        try{String op=args[0].toLowerCase(Locale.ROOT);if(op.equals("balance")){s.sendMessage(getPointsApi().balance(id)+" SP");return true;}
            long a=Long.parseLong(args[2]);String reason=args.length>3?String.join(" ",Arrays.copyOfRange(args,3,args.length)):"command by "+s.getName();
            switch(op){case "deposit"->getPointsApi().deposit(id,a,reason);case "withdraw"->{if(!getPointsApi().withdraw(id,a,reason)){s.sendMessage("Zu wenig Punkte. Keine Änderung.");return true;}}case "set"->getPointsApi().setBalance(id,a,reason);default->throw new IllegalArgumentException("Unbekannte Aktion");}
            suiteAudit(s.getName(),"Punkte-API-Befehl",op+" "+id+" "+a);s.sendMessage("Erfolgreich: "+getPointsApi().balance(id)+" SP");
        }catch(Exception e){s.sendMessage("Nicht ausgeführt: "+e.getMessage());}return true;
    }
