    static void saveAtomic(org.bukkit.configuration.file.FileConfiguration yaml, File file) throws Exception {
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) parent.mkdirs();
        File temporary = new File(parent == null ? new File(".") : parent, file.getName() + ".tmp");
        yaml.save(temporary);
        try { Files.move(temporary.toPath(), file.toPath(), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING); }
        catch (Exception ignored) { Files.move(temporary.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING); }
    }
