    private static String plainDuration(String value) { String clean = stripFormatting(value).trim().toLowerCase(Locale.ROOT); return DurationValue.isValid(clean) ? clean : "1d"; }
    static String stripFormatting(String value) {
        if (value == null || value.isEmpty()) return "";
        return sanitizePlayerChatFormatting(value, true, true, false).replace('\n', ' ').replace('\r', ' ');
    }

    static String sanitizePlayerChatFormatting(String value, boolean blockColors, boolean blockFormatting, boolean bedrockClient) {
        if (value == null || value.isEmpty() || (!blockColors && !blockFormatting)) return value == null ? "" : value;
        String clean = value;
        if (blockColors) {
            clean = LEGACY_HEX_SEQUENCE.matcher(clean).replaceAll("");
            clean = LEGACY_HEX_SHORT.matcher(clean).replaceAll("");
            clean = MINI_COLOR_TAG.matcher(clean).replaceAll("");
            clean = clean.replaceAll("(?i)&[0-9a-f]", "");
            clean = clean.replaceAll(bedrockClient ? "(?i)§[0-9a-jmnpqstu-v]" : "(?i)§[0-9a-f]", "");
        }
        if (blockFormatting) {
            clean = MINI_FORMAT_TAG.matcher(clean).replaceAll("");
            clean = clean.replaceAll("(?i)&[k-or]", "");
            clean = clean.replaceAll(bedrockClient ? "(?i)§[klor]" : "(?i)§[k-or]", "");
        }
        return clean;
    }
    private String join(String[] args, int start) { if (args.length <= start) return ""; StringBuilder b = new StringBuilder(); for (int i = start; i < args.length; i++) { if (b.length() > 0) b.append(' '); b.append(args[i]); } return b.toString(); }
    private List<String> filter(Collection<String> values, String prefix) { String p = prefix == null ? "" : prefix.toLowerCase(Locale.ROOT); return values.stream().filter(v -> v.toLowerCase(Locale.ROOT).startsWith(p)).sorted(String.CASE_INSENSITIVE_ORDER).limit(80).collect(Collectors.toList()); }
    private void trim(List<String> list, int max) { while (list.size() > max) list.remove(0); }
    private String normalizeRight(String input) { if (input == null) return null; String s = input.toLowerCase(Locale.ROOT); if (s.equals("bauen")) s = "build"; if (s.equals("abbauen")) s = "break"; if (s.equals("befehle")) s = "commands"; if (s.equals("farben") || s.equals("chatfarben") || s.equals("color") || s.equals("colors")) s = "chat-colors"; if (s.equals("format") || s.equals("formatierung") || s.equals("chatformatierung") || s.equals("formats")) s = "chat-formatting"; if (s.equals("enderkiste")) s = "enderchest"; if (s.equals("öfen") || s.equals("oefen")) s = "furnaces"; if (s.equals("teleport")) s = "teleportation"; for (String right : RIGHTS) if (right.equals(s)) return right; return null; }

