    private ItemStack playerHead(PlayerProfile profile, String name, String... lore) {
        ItemStack stack = item(Material.PLAYER_HEAD, name, lore);
        if (profile == null) return stack;
        try {
            ItemMeta meta = stack.getItemMeta();
            if (meta instanceof SkullMeta) {
                ((SkullMeta) meta).setOwningPlayer(Bukkit.getOfflinePlayer(profile.uuid));
                stack.setItemMeta(meta);
            }
        } catch (Throwable ignored) { }
        return stack;
    }
