    String executeConfirmedAiAction(Player admin, String action, UUID targetUuid, String duration, long amount, String reason) {
        if (admin == null || targetUuid == null) return "KI-Aktion wurde wegen ungültiger Bestätigungsdaten abgebrochen.";
        PlayerProfile target = database.get(targetUuid);
        if (target == null) return "Das bestätigte Spielerprofil existiert nicht mehr.";
        String normalized = action == null ? "" : action.toUpperCase(Locale.ROOT);
        if (normalized.equals("SETPOINTS")) {
            if (!has(admin, "simplexadminsuite.points.admin")) return "Dir fehlt simplexadminsuite.points.admin.";
            target.setSimplexPoints(Math.max(0L, Math.min(1_000_000_000L, amount)));
            database.save(target); refreshExpansionNameplate(Bukkit.getPlayer(targetUuid)); discordPointsChanged();
            return "Bestätigt ausgeführt: Simplex Points von " + target.name + " auf " + target.simplexPoints() + " gesetzt.";
        }
        String punishment = normalized.toLowerCase(Locale.ROOT);
        if (punishment.equals("warn") && !has(admin, "simplexadminsuite.warns")) return "Dir fehlt simplexadminsuite.warns.";
        if ((punishment.equals("mute") || punishment.equals("tempmute")) && !has(admin, "simplexadminsuite.mutes")) return "Dir fehlt simplexadminsuite.mutes.";
        if ((punishment.equals("kick") || punishment.equals("tempban")) && !has(admin, "simplexadminsuite.bans")) return "Dir fehlt simplexadminsuite.bans.";
        boolean success = executePunishment(admin, punishment, target, target.name, duration == null ? "" : duration,
                sanitizeText(reason, getConfig().getInt("punishments.max-reason-length", 240)));
        if (!success) return "Die bestätigte Aktion konnte vom Strafanbieter nicht ausgeführt werden.";
        target.addAction("Bestätigte KI-Adminaktion durch " + admin.getName() + ": " + normalized + " " + reason);
        database.save(target);
        return "Bestätigt ausgeführt: " + normalized + " für " + target.name + ".";
    }
