    List<AdminPowerToolsManager.AltCandidate> powerAltCandidates(UUID sourceUuid, int minimumScore, boolean includeIpOnly) {
        PlayerProfile source = database.get(sourceUuid);
        if (source == null || altDetection == null) return Collections.emptyList();
        List<AdminPowerToolsManager.AltCandidate> result = new ArrayList<>();
        for (PlayerProfile candidate : database.sortedProfiles()) {
            if (candidate == null || candidate.uuid.equals(sourceUuid) || altDetection.ignored(source, candidate)) continue;
            AdvancedAltDetection.AltMatch match = altDetection.score(source, candidate);
            if (!powerAcceptAltMatch(match, minimumScore, includeIpOnly)) continue;
            result.add(new AdminPowerToolsManager.AltCandidate(candidate.uuid, candidate.name, match.score, match.safeForCascade, match.evidence));
        }
        result.sort(Comparator.comparingInt((AdminPowerToolsManager.AltCandidate match) -> match.score).reversed()
                .thenComparing(match -> match.name, String.CASE_INSENSITIVE_ORDER));
        return result;
    }
    AdminPowerToolsManager.AltCandidate powerAltRelation(UUID sourceUuid, UUID candidateUuid, int minimumScore, boolean includeIpOnly) {
        PlayerProfile source = database.get(sourceUuid), candidate = database.get(candidateUuid);
        if (source == null || candidate == null || altDetection == null || altDetection.ignored(source, candidate)) return null;
        AdvancedAltDetection.AltMatch match = altDetection.score(source, candidate);
        if (!powerAcceptAltMatch(match, minimumScore, includeIpOnly)) return null;
        return new AdminPowerToolsManager.AltCandidate(candidate.uuid, candidate.name, match.score, match.safeForCascade, match.evidence);
    }
    boolean powerAltLinkIgnored(UUID sourceUuid, UUID candidateUuid) {
        PlayerProfile source = database.get(sourceUuid), candidate = database.get(candidateUuid);
        return source == null || candidate == null || altDetection == null || altDetection.ignored(source, candidate);
    }
    private boolean powerAcceptAltMatch(AdvancedAltDetection.AltMatch match, int minimumScore, boolean includeIpOnly) {
        if (match == null) return false;
        int ipMinimum = Math.max(12, Math.min(100, getConfig().getInt("alt-rights.ip-only-minimum-score", 25)));
        return powerAcceptAltEvidence(match.score, match.safeForCascade, match.evidence, minimumScore, includeIpOnly, ipMinimum);
    }
    static boolean powerAcceptAltEvidence(int score, boolean safeForCascade, Collection<String> evidence,
                                          int minimumScore, boolean includeIpOnly, int ipMinimumScore) {
        boolean strongIdentity = safeForCascade && score >= Math.max(1, minimumScore);
        if (strongIdentity) return true;
        if (!includeIpOnly) return false;
        int ipMinimum = Math.max(12, Math.min(100, ipMinimumScore));
        boolean sharedIp = evidence != null && evidence.stream()
                .anyMatch(text -> text != null && text.startsWith("Gemeinsame IP-Historie"));
        return sharedIp && score >= ipMinimum;
    }

    /*
     * Discord remote administration deliberately terminates here, in the same service facade used
     * by the Java and Floodgate menus. Gateway threads schedule these methods onto Bukkit's primary
     * thread. Virtual senders are permission-complete but have no world presence; their output is
     * captured for the private Discord response and every mutation still reaches the normal audit.
     */
    List<DiscordAdminController.Choice> discordAdminPlayerChoices(String query, int requestedLimit) {
        String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
        int limit = Math.max(1, Math.min(25, requestedLimit));
        List<PlayerProfile> profiles = database.sortedProfiles();
        profiles.sort(Comparator
                .comparing((PlayerProfile profile) -> Bukkit.getPlayer(profile.uuid) == null)
                .thenComparing((PlayerProfile profile) -> !profile.name.toLowerCase(Locale.ROOT).startsWith(needle))
                .thenComparing((PlayerProfile profile) -> !profile.name.toLowerCase(Locale.ROOT).contains(needle))
                .thenComparing(Comparator.comparingLong((PlayerProfile profile) -> profile.lastSeen).reversed()));
        List<DiscordAdminController.Choice> result = new ArrayList<>();
        for (PlayerProfile profile : profiles) {
            if (!needle.isBlank() && !profile.name.toLowerCase(Locale.ROOT).contains(needle)
                    && !profile.uuid.toString().startsWith(needle)
                    && profile.previousNames.stream().noneMatch(name -> name.toLowerCase(Locale.ROOT).contains(needle))) continue;
            boolean online = Bukkit.getPlayer(profile.uuid) != null;
            result.add(new DiscordAdminController.Choice((online ? "Online • " : "Offline • ") + profile.name, profile.uuid.toString()));
            if (result.size() >= limit) break;
        }
        return result;
    }

    List<DiscordAdminController.Choice> discordAdminTrimChoices(String query, int requestedLimit) {
        if (worldTrimmer == null) return List.of();
        String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
        List<DiscordAdminController.Choice> result = new ArrayList<>();
        result.add(new DiscordAdminController.Choice("All detected dimensions", "all"));
        for (WorldTrimManager.WorldTarget target : worldTrimmer.targetsSnapshot()) {
            if (!needle.isBlank() && !target.id.toLowerCase(Locale.ROOT).contains(needle)
                    && !target.label.toLowerCase(Locale.ROOT).contains(needle)) continue;
            result.add(new DiscordAdminController.Choice(target.label + " • " + formatDiscordBytes(target.bytes), target.id));
            if (result.size() >= Math.max(1, Math.min(25, requestedLimit))) break;
        }
        return result;
    }

