    String discordAdminServerStatus() {
        StringBuilder text = new StringBuilder("**Spieler:** ").append(visibleOnlineCount()).append('/').append(serverMaxPlayers())
                .append(" • **TPS:** ").append(String.format(Locale.ROOT, "%.2f", discordAdminTps()))
                .append("\n**Wartung:** ").append(qolMaintenanceActive() ? "Aktiv" : "Inaktiv")
                .append(" • **Chat:** ").append(qolGlobalChatEnabled() ? "Aktiv" : "Inaktiv")
                .append("\n**Server-Tage:** Hauptwelt ").append(scoreboardMainDays()).append(" • Zweitwelt ").append(scoreboardSecondDays());
        List<DiscordBotManager.PlayerSnapshot> players = discordPlayerSnapshots();
        text.append("\n\n**Online-Spieler**");
        if (players.isEmpty()) text.append("\n_Aktuell ist kein Spieler online._");
        for (DiscordBotManager.PlayerSnapshot player : players) {
            text.append("\n").append(player.emoji).append(" **").append(discordSafe(player.name)).append("**")
                    .append(player.afk ? " • AFK" : "").append(" • ").append(discordSafe(player.platform));
        }
        WorldTrimManager.TrimStatus trim = worldTrimStatus();
        if (trim.active()) text.append("\n\n**Welten-Trimmer:** ").append(trim.phase.name()).append(" • ").append(trim.progress)
                .append("% • ").append(discordSafe(trim.eta));
        return text.toString();
    }

    String discordAdminPlayerInfo(UUID uuid, boolean includeSensitive) {
        PlayerProfile profile = database.get(uuid);
        if (profile == null) return "Spielerprofil nicht gefunden.";
        Player online = Bukkit.getPlayer(uuid);
        long now = System.currentTimeMillis();
        StringBuilder text = new StringBuilder("**UUID:** `").append(profile.uuid).append("`")
                .append("\n**Status:** ").append(online == null ? "Offline" : "Online")
                .append(" • **Client:** ").append(discordSafe(profile.clientSummary()))
                .append("\n**First seen:** ").append(time(profile.firstSeen)).append(" • **Last seen:** ").append(time(profile.lastSeen))
                .append("\n**Sessions:** ").append(profile.sessionCount)
                .append(" • **Playtime:** ").append(formatDiscordDuration(profile.totalPlayMillis))
                .append(" • **AFK:** ").append(formatDiscordDuration(profile.totalAfkMillis))
                .append("\n**Simplex Points:** ").append(profile.simplexPoints())
                .append(" • **Warnings:** ").append(profile.warnings.size()).append(" • **Staff notes:** ").append(profile.notes.size())
                .append("\n**Punishments:** ").append(discordSafe(punishments.summary(profile)))
                .append("\n**Blocked rights:** ").append(profile.blockedRights().isEmpty() ? "None" : String.join(", ", profile.blockedRights()))
                .append("\n**Last location:** ").append(profile.lastLocation == null ? "Not stored" : discordSafe(profile.lastLocation.shortText()));
        if (profile.internalBanActive(now)) text.append("\n**Internal ban:** active • ").append(discordSafe(profile.internalBanReason));
        if (profile.internalMuteActive(now)) text.append("\n**Internal mute:** active • ").append(discordSafe(profile.internalMuteReason));
        if (!profile.previousNames.isEmpty()) text.append("\n**Previous names:** ").append(discordSafe(String.join(", ", profile.previousNames)));
        if (includeSensitive) {
            text.append("\n\n**Sensitive identifiers (private response)**")
                    .append("\nIP: `").append(discordIdentifier(profile.lastIpMasked.isBlank() ? profile.lastIpHash : profile.lastIpMasked)).append("`")
                    .append("\nXUID hash: `").append(discordIdentifier(profile.bedrockXuidHash)).append("`")
                    .append("\nDevice hash: `").append(discordIdentifier(profile.bedrockDeviceIdHash)).append("`")
                    .append("\nSelf-signed hash: `").append(discordIdentifier(profile.bedrockSelfSignedIdHash)).append("`");
        }
        return text.toString();
    }

    String discordAdminLiveSession(UUID uuid) {
        PlayerProfile profile = database.get(uuid);
        if (profile == null) return "Spielerprofil nicht gefunden.";
        Player online = Bukkit.getPlayer(uuid);
        if (online == null) {
            return "**Status:** Offline"
                    + "\n**Last seen:** " + time(profile.lastSeen)
                    + "\n**Last location:** " + (profile.lastLocation == null ? "Not stored" : discordSafe(profile.lastLocation.shortText()))
                    + "\n**Logout location:** " + (profile.logoutLocation == null ? "Not stored" : discordSafe(profile.logoutLocation.shortText()))
                    + "\n**Last client:** " + discordSafe(profile.clientSummary());
        }
        Location location = online.getLocation();
        String coordinates = location.getWorld() == null ? "Unknown"
                : location.getWorld().getName() + " " + location.getBlockX() + " / " + location.getBlockY() + " / " + location.getBlockZ();
        int ping = -1;
        try {
            Object value = online.getClass().getMethod("getPing").invoke(online);
            if (value instanceof Number) ping = ((Number) value).intValue();
        } catch (Throwable ignored) { }
        long currentSession = profile.currentSessionStartedAt <= 0L ? 0L : System.currentTimeMillis() - profile.currentSessionStartedAt;
        return "**Status:** Online" + (afk != null && afk.isAfk(online) ? " • AFK" : " • Active")
                + "\n**World / position:** " + discordSafe(coordinates)
                + "\n**Gamemode:** " + online.getGameMode().name() + " • **Ping:** " + (ping < 0 ? "Unknown" : ping + " ms")
                + "\n**Health:** " + String.format(Locale.ROOT, "%.1f/%.1f", online.getHealth(), online.getMaxHealth())
                + " • **Food:** " + online.getFoodLevel() + "/20 • **Level:** " + online.getLevel()
                + "\n**Flight:** " + (discordPlayerBoolean(online, "isFlying") ? "Flying" : discordPlayerBoolean(online, "getAllowFlight") ? "Allowed" : "Disabled")
                + " • **Invulnerable:** " + (discordPlayerBoolean(online, "isInvulnerable") ? "Yes" : "No")
                + "\n**Current session:** " + formatDiscordDuration(currentSession)
                + " • **Client:** " + discordSafe(profile.clientSummary());
    }

    String discordAdminHistory(UUID uuid, String category, int requestedLimit) {
        PlayerProfile profile = database.get(uuid);
        if (profile == null) return "Spielerprofil nicht gefunden.";
        int limit = Math.max(1, Math.min(40, requestedLimit));
        String normalized = category == null ? "all" : category.toLowerCase(Locale.ROOT);
        List<String> lines = new ArrayList<>();
        if (normalized.equals("all")) {
            appendDiscordHistory(lines, "Chat", profile.recentChat, Math.max(1, limit / 4));
            appendDiscordHistory(lines, "Actions", profile.recentActions, Math.max(1, limit / 4));
            appendDiscordHistory(lines, "Combat", profile.recentCombat, Math.max(1, limit / 4));
            appendDiscordHistory(lines, "Private messages", profile.recentPrivateMessages, Math.max(1, limit / 4));
        } else {
            List<String> selected = switch (normalized) {
                case "chat" -> profile.recentChat;
                case "actions" -> profile.recentActions;
                case "combat" -> profile.recentCombat;
                case "private" -> profile.recentPrivateMessages;
                default -> null;
            };
            if (selected == null) return "Unbekannte Verlaufskategorie.";
            appendDiscordHistory(lines, normalized, selected, limit);
        }
        return lines.isEmpty() ? "Für diese Kategorie sind keine Einträge gespeichert." : String.join("\n", lines);
    }

    private void appendDiscordHistory(List<String> output, String title, List<String> source, int limit) {
        List<String> copy;
        synchronized (source) { copy = new ArrayList<>(source); }
        if (copy.isEmpty()) return;
        output.add("**" + discordSafe(title) + "**");
        int start = Math.max(0, copy.size() - Math.max(1, limit));
        for (int index = copy.size() - 1; index >= start; index--) output.add("• " + discordSafe(copy.get(index)));
    }

    String discordAdminRights(UUID uuid) {
        PlayerProfile profile = database.get(uuid);
        if (profile == null) return "Spielerprofil nicht gefunden.";
        Set<String> blocked = profile.blockedRightsSet();
        Map<String, Long> temporary = profile.temporaryBlockedRightsMap();
        StringBuilder text = new StringBuilder("**Dauerhaft gesperrt: ").append(blocked.size())
                .append(" • Temporär gesperrt: ").append(temporary.size()).append(" • Gesamt: ")
                .append(powerRights().length).append("**");
        for (String right : powerRights()) {
            Long until = temporary.get(right);
            text.append("\n");
            if (blocked.contains(right)) text.append("🔴 `").append(discordSafe(right)).append("` • dauerhaft");
            else if (until != null && until > System.currentTimeMillis()) text.append("🟠 `").append(discordSafe(right))
                    .append("` • endet <t:").append(until / 1000L).append(":R>");
            else text.append("🟢 `").append(discordSafe(right)).append("` • erlaubt");
        }
        text.append("\n\nMit `/sasadmin player right` kann ein Recht erlaubt, dauerhaft gesperrt oder mit `duration` temporär gesperrt werden. Die Alt-/IP-Vererbung übernimmt dieselbe Ablaufzeit.");
        return text.toString();
    }

    String discordAdminPoints(String actor, String query, String operation, long amount) {
        PlayerProfile profile = database.find(query);
        if (profile == null) return "Spielerprofil nicht gefunden.";
        String normalized = operation == null || operation.isBlank() ? "status" : operation.toLowerCase(Locale.ROOT);
        long before = profile.simplexPoints();
        if (normalized.equals("status")) return "**" + discordSafe(profile.name) + "** has **" + before + " Simplex Points**."
                + "\nCounted active playtime: " + formatDiscordDuration(profile.pointsActiveMillis());
        long safeAmount = Math.max(0L, amount);
        long after = switch (normalized) {
            case "set" -> safeAmount;
            case "add" -> before > Long.MAX_VALUE - safeAmount ? Long.MAX_VALUE : before + safeAmount;
            case "remove" -> Math.max(0L, before - safeAmount);
            default -> -1L;
        };
        if (after < 0L) return "Unbekannte Punkteaktion.";
        profile.setSimplexPoints(after);
        profile.addAction("Simplex Points durch " + actor + " geändert: " + before + " -> " + after);
        database.save(profile);
        Player online = Bukkit.getPlayer(profile.uuid);
        if (online != null) {
            refreshExpansionNameplate(online);
            online.sendMessage(playerUiText(online,prefix() + "Your Simplex Points balance was updated by staff. New balance: " + after + "."));
        }
        audit.log(actor, profile.uuid, "Simplex Points geändert", normalized + " " + safeAmount + " | " + before + " -> " + after);
        return "Balance updated for **" + discordSafe(profile.name) + "**: **" + before + " → " + after + "**.";
    }

    List<DiscordAdminController.Choice> discordAdminSnapshotChoices(String query, String filter, int requestedLimit) {
        PlayerProfile profile = database.find(query);
        if (profile == null) return List.of();
        String needle = filter == null ? "" : filter.toLowerCase(Locale.ROOT);
        List<DiscordAdminController.Choice> choices = new ArrayList<>();
        for (File file : snapshotFiles(profile.uuid)) {
            if (!needle.isBlank() && !file.getName().toLowerCase(Locale.ROOT).contains(needle)) continue;
            choices.add(new DiscordAdminController.Choice(readableSnapshotName(file.getName()).replace("&8", "") + " • " + formatDiscordBytes(file.length()), file.getName()));
            if (choices.size() >= Math.max(1, Math.min(25, requestedLimit))) break;
        }
        return choices;
    }

    String discordAdminSnapshots(String discordId, String actor, String query, String operation, String fileName) {
        PlayerProfile profile = database.find(query);
        if (profile == null) return "Spielerprofil nicht gefunden.";
        String normalized = operation == null || operation.isBlank() ? "list" : operation.toLowerCase(Locale.ROOT);
        File[] snapshots = snapshotFiles(profile.uuid);
        if (normalized.equals("list")) {
            if (snapshots.length == 0) return "No inventory snapshots are stored for **" + discordSafe(profile.name) + "**.";
            StringBuilder text = new StringBuilder("**Stored snapshots: ").append(snapshots.length).append("**");
            for (int index = 0; index < Math.min(20, snapshots.length); index++) {
                File file = snapshots[index];
                text.append("\n").append(index + 1).append(". `").append(discordSafe(file.getName())).append("` • ")
                        .append(discordSafe(ageText(file.lastModified()))).append(" • ").append(formatDiscordBytes(file.length()));
            }
            if (snapshots.length > 20) text.append("\n…and ").append(snapshots.length - 20).append(" more.");
            return text.toString();
        }
        List<String> output = new ArrayList<>();
        Player sender = discordVirtualPlayer(discordId, actor, output);
        if (normalized.equals("create")) createSnapshot(sender, profile);
        else {
            File selected = fileName == null || fileName.isBlank() ? latestSnapshot(profile.uuid) : snapshotFile(profile.uuid, fileName);
            if (selected == null || !selected.exists()) return "Snapshot wurde nicht gefunden. Nutze Autocomplete oder lasse die Datei für den neuesten Snapshot leer.";
            if (normalized.equals("restore")) restoreSnapshot(sender, profile, selected.getName());
            else if (normalized.equals("delete")) deleteSnapshot(sender, profile, selected.getName());
            else return "Unbekannte Snapshot-Aktion.";
        }
        return capturedDiscordOutput(output, "Snapshot-Aktion für " + profile.name + " wurde ausgeführt.");
    }

    String discordAdminIdentity(UUID uuid) {
        PlayerProfile profile = database.get(uuid);
        if (profile == null || altDetection == null) return "Spielerprofil oder Identitätserkennung nicht gefunden.";
        AdvancedAltDetection.UltraBanStatus status = altDetection.ultraStatus(profile);
        StringBuilder text = new StringBuilder("**Client identity:** ").append(discordSafe(profile.clientSummary()))
                .append("\n**Known devices:** ").append(profile.devices.size())
                .append(" • **IP history:** ").append(profile.altIpHistory.size())
                .append(" • **Manual links:** ").append(profile.manualAltLinks.size())
                .append("\n**Active identity ban:** ").append(status.active ? "Yes" : "No");
        if (status.active) {
            text.append("\n**Group:** `").append(discordSafe(status.groupId)).append("` • members ").append(status.members)
                    .append(" • anchors ").append(status.identities)
                    .append("\n**Reason:** ").append(discordSafe(status.reason))
                    .append("\n**Blocked attempts:** ").append(status.blockedAttempts);
            if (status.lastAttemptAt > 0L) text.append(" • last ").append(time(status.lastAttemptAt)).append(" by ").append(discordSafe(status.lastAttemptName));
        }
        List<String> evasion = altDetection.evasionDetails(profile, 10);
        if (!evasion.isEmpty()) {
            text.append("\n\n**Recent identity-ban events**");
            for (String line : evasion) {
                String clean = stripFormatting(line).replace(stripFormatting(prefix()), "").trim();
                if (!clean.isBlank() && !clean.toLowerCase(Locale.ROOT).startsWith("ban-evasion-protokoll")) text.append("\n").append(discordSafe(clean));
            }
        }
        return text.toString();
    }

    List<DiscordAdminController.Choice> discordAdminDeviceChoices(String query, String filter, int requestedLimit) {
        PlayerProfile profile = database.find(query);
        if (profile == null || altDetection == null) return List.of();
        String needle = filter == null ? "" : filter.toLowerCase(Locale.ROOT);
        List<DeviceRecord> devices = altDetection.devices(profile, "ALL", needle);
        List<DiscordAdminController.Choice> choices = new ArrayList<>();
        for (DeviceRecord device : devices) {
            String label = device.platform + " • " + (device.model.isBlank() ? device.os.isBlank() ? "Unknown device" : device.os : device.model)
                    + (device.blocked ? " • BLOCKED" : "") + " • " + device.id.substring(0, Math.min(10, device.id.length()));
            choices.add(new DiscordAdminController.Choice(label, device.id));
            if (choices.size() >= Math.max(1, Math.min(25, requestedLimit))) break;
        }
        return choices;
    }

