    void qolSetMaintenance(String actor, boolean enabled, String reason) {
        if (maintenance == null) return;
        boolean changed = maintenance.isActive() != enabled || enabled && !maintenance.reason().equals(reason == null ? "" : reason);
        if (enabled) {
            maintenance.enable(actor, reason);
            if (changed) broadcastPublicText(prefix() + stripFormatting("Server maintenance has been enabled by staff."));
            maintenance.kickNonStaff();
        } else {
            maintenance.disable(actor);
            if (changed) broadcastPublicText(prefix() + stripFormatting("Server maintenance has been disabled by staff."));
        }
        if (discordStatus != null) discordStatus.updateNow();
        if (discordBot != null) discordBot.updateNow();
    }
