    private boolean consumeBedrockMenu(Player player, BooleanSupplier opener) {
        if (!isBedrockClient(player)) return false;
        boolean sent = false;
        try { sent = opener.getAsBoolean(); }
        catch (Throwable error) { getLogger().warning("Natives Bedrock-Menü für " + player.getName() + " konnte nicht gesendet werden: " + rootCause(error).getClass().getSimpleName()); }
        if (!sent) menuNotice(player,prefix() + "Das native Bedrock-Menü konnte nicht gesendet werden. Bitte prüfe /sas form und die Floodgate-/Geyser-Versionen.");
        return true;
    }
