    void applyKeywordPenalty(Player player, String action, String reason) {
        if (player == null) return;
        PlayerProfile profile = database.touch(player);
        String normalized = action == null ? "BLOCK" : action.toUpperCase(Locale.ROOT);
        String publicReason = sanitizeText(reason, 180);
        if (normalized.equals("WARN")) {
            profile.warnings.add(stamp() + " System: " + publicReason);
            trim(profile.warnings, Math.max(1, getConfig().getInt("storage.max-warnings", 80)));
            player.sendMessage(playerUiText(player, prefix() + "A warning was added to your account for a blocked chat message."));
        } else if (normalized.equals("MUTE_5M")) {
            profile.internalMuteUntil = System.currentTimeMillis() + 300_000L;
            profile.internalMuteReason = publicReason;
            profile.internalMuteBy = "Chat Filter";
            player.sendMessage(playerUiText(player, prefix() + "You have been muted for 5 minutes because of a blocked chat message."));
        } else if (normalized.equals("KICK")) {
            Bukkit.getScheduler().runTask(this, () -> suiteKick(player,"A prohibited chat message was detected."));
        }
        profile.addAction("Keyword-/Regex-Filter: " + normalized + " | " + publicReason);
        database.save(profile);
        audit.log("Chat-Filter", player.getUniqueId(), "Chatfilter-Aktion " + normalized, publicReason);
        List<String> alertActions = getConfig().getStringList("discord-bot.alerts.chat-filter-actions");
        if (discordBot != null && alertActions.stream().anyMatch(value -> normalized.equalsIgnoreCase(value))) {
            StringBuilder details = new StringBuilder("**Player:** ").append(player.getName()).append(" (`").append(player.getUniqueId()).append("`)\n")
                    .append("**Action:** ").append(normalized).append("\n")
                    .append("**Platform/device:** ").append(profile.clientPlatform).append(" / ").append(profile.clientDevice.isBlank() ? "Unknown" : profile.clientDevice).append("\n")
                    .append("**Evidence:** ").append(publicReason);
            if (getConfig().getBoolean("discord-bot.alerts.include-ip", true) && !profile.lastIpMasked.isBlank()) details.append("\n**IP:** `").append(profile.lastIpMasked).append("`");
            if (getConfig().getBoolean("discord-bot.alerts.include-identifiers", true) && !profile.bedrockDeviceIdHash.isBlank()) details.append("\n**Device identifier:** `").append(profile.bedrockDeviceIdHash).append("`");
            discordBot.relaySecurityAlert("Suspicious chat-filter activity", details.toString());
        }
    }

    private static void saveYamlAtomically(YamlConfiguration yaml, File file) throws Exception {
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) parent.mkdirs();
        File temp = new File(parent == null ? new File(".") : parent, file.getName() + ".tmp");
        yaml.save(temp);
        try {
            Files.move(temp.toPath(), file.toPath(), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (Exception atomicMoveUnavailable) {
            Files.move(temp.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING);
        }
    }

