        public boolean openRules(Player player, boolean forced) {
            if (!isBedrock(player)) return false;
            List<String> rules = plugin.expansion.rulesFor(player);
            int shownVersion = plugin.expansion.rulesVersion();
            StringBuilder content = new StringBuilder("§fPlease read all server rules carefully.\n§fRules version: §e")
                    .append(shownVersion).append("\n\n");
            for (int i = 0; i < rules.size(); i++) content.append("§e").append(i + 1).append(". §f").append(rules.get(i)).append("\n\n");
            if (rules.isEmpty()) content.append("§fNo server rules have been published yet.");
            SimpleForm.Builder form = SimpleForm.builder().playerFacing().title("§l§6SERVER RULES").content(content.toString());
            if (plugin.expansion.rulesRequired(player)) {
                form.button("§aI have read all rules", response -> sync(() -> openRulesConfirmation(player, shownVersion)));
                form.button("§cI do not agree", response -> sync(() -> {
                    player.sendMessage(plugin.playerUiText(player, plugin.prefix() + "You must accept the current server rules before you can continue playing."));
                    Bukkit.getScheduler().runTaskLater(plugin, () -> openRules(player, true), 20L);
                }));
            } else form.button("§aClose", response -> { });
            return send(player, form);
        }

        private void openRulesConfirmation(Player player, int shownVersion) {
            SimpleForm.Builder form = SimpleForm.builder().playerFacing().title("§l§6CONFIRM RULES")
                    .content("§fBy confirming, you state that you have read and agree to the displayed server rules.\n\n§fRules version: §e" + shownVersion);
            form.button("§aYes, I agree", response -> sync(() -> plugin.expansion.acceptRules(player, shownVersion)));
            form.button("§cBack to the rules", response -> sync(() -> openRules(player, true)));
            send(player, form);
        }

