        public boolean openVote(Player player) {
            if (!isBedrock(player)) return false;
            SuiteExpansion.PollView poll = plugin.expansion.activePoll(player);
            if (poll == null) {
                SimpleForm.Builder none = SimpleForm.builder().playerFacing().title("§l§9SERVER VOTE")
                        .content("§fThere is no active server vote right now.\n\n§fLatest result:\n§e" + plugin.expansion.latestPollResult());
                none.button("§aClose", response -> { });
                return send(player, none);
            }
            if (poll.maxSelections <= 1) {
                SimpleForm.Builder form = SimpleForm.builder().playerFacing().title("§l§9SERVER VOTE")
                        .content("§f" + poll.question + "\n\n§fEnds in: §e" + poll.remaining + "\n§fVotes cast: §e" + poll.voterCount);
                for (int i = 0; i < poll.options.size(); i++) {
                    int option = i;
                    form.button("§b" + poll.options.get(i) + "\n§f" + poll.counts.get(i) + " vote(s)", response -> sync(() -> { plugin.expansion.castVote(player, poll.id, List.of(option)); openVote(player); }));
                }
                form.button("§cClose", response -> { });
                return send(player, form);
            }
            CustomForm.Builder form = CustomForm.builder().playerFacing().title("§l§9SERVER VOTE");
            for (int i = 0; i < poll.options.size(); i++) {
                String header = i == 0 ? "§e" + poll.question + "\n§7Ends in: §f" + poll.remaining + " §8• §7Choose up to §f" + poll.maxSelections + "\n\n" : "";
                form.toggle(header + "§f" + poll.options.get(i) + " §7(" + poll.counts.get(i) + " vote(s))", poll.selected.contains(i));
            }
            form.validResultHandler(response -> sync(() -> {
                List<Integer> selected = new ArrayList<>();
                for (int i = 0; i < poll.options.size(); i++) if (response.asToggle(i)) selected.add(i);
                plugin.expansion.castVote(player, poll.id, selected);
                openVote(player);
            })).closedOrInvalidResultHandler(() -> { });
            return send(player, form);
        }

        public boolean openPollsAdmin(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openpollsadmin")) return true;
            if (!isBedrock(admin) || !plugin.has(admin, "simplexadminsuite.polls.admin")) return false;
            SuiteExpansion.PollView poll = plugin.expansion.activePoll();
            String content;
            if (poll == null) content = "§fAktuell ist keine Umfrage aktiv.\n\n§fLetztes Ergebnis: §e" + plugin.expansion.latestPollResult() + "\n\n§fDetailauswertung:\n§e" + plugin.expansion.latestPollDetails();
            else {
                StringBuilder live = new StringBuilder("§fAktive Frage: §e").append(poll.question).append("\n§fRestzeit: §e").append(poll.remaining)
                        .append("\n§fTeilnehmer: §e").append(poll.voterCount).append("\n§fMaximale Auswahl: §e").append(poll.maxSelections)
                        .append("\n§fÄnderungen: ").append(state(poll.allowChange)).append("\n\n§fLive-Ergebnis:\n");
                for (int i = 0; i < poll.options.size(); i++) live.append("§e").append(i + 1).append(". §f").append(poll.options.get(i)).append("§7: §b").append(poll.counts.get(i)).append("\n");
                content = live.toString();
            }
            SimpleForm.Builder form = SimpleForm.builder().title("§l§9UMFRAGEN & VOTES").content(content);
            if (poll == null) form.button("§aNeue Umfrage erstellen", response -> sync(() -> openPollCreator(admin)));
            else {
                form.button("§bÖffentliche Vote-Ansicht", response -> sync(() -> openVote(admin)));
                form.button("§cUmfrage jetzt beenden", response -> sync(() -> confirm(admin, "Umfrage beenden", "Das aktuelle Ergebnis wird veröffentlicht und an Discord gesendet.", () -> { plugin.expansion.endPoll(admin.getName()); openPollsAdmin(admin); }, () -> openPollsAdmin(admin))));
            }
            form.button("§cZurück zum Hauptmenü", response -> sync(() -> openMain(admin)));
            return send(admin, form);
        }

        private void openPollCreator(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openpollcreator")) return;
            CustomForm.Builder form = CustomForm.builder().title("§l§9NEUE UMFRAGE")
                    .input("§fEnglische Frage", "Should we enable...?", "")
                    .input("§fEnglische Antworten, getrennt mit |", "Yes | No | Maybe", "Yes | No")
                    .dropdown("§fLaufzeit", List.of("1 Minute", "5 Minuten", "15 Minuten", "1 Stunde", "6 Stunden", "24 Stunden"), 3)
                    .slider("§fMaximale Antwortauswahl", 1F, 6F, 1F, 1F)
                    .toggle("§fSpieler dürfen ihre Auswahl ändern", false)
                    .validResultHandler(response -> sync(() -> {
                        long[] durations = {60L, 300L, 900L, 3600L, 21600L, 86400L};
                        int durationIndex = Math.max(0, Math.min(durations.length - 1, response.asDropdown(2)));
                        String result = plugin.expansion.createPoll(admin.getName(), response.asInput(0), response.asInput(1), durations[durationIndex], Math.round(response.asSlider(3)), response.asToggle(4));
                        admin.sendMessage(plugin.prefix() + result);
                        openPollsAdmin(admin);
                    }))
                    .closedOrInvalidResultHandler(() -> sync(() -> openPollsAdmin(admin)));
            send(admin, form);
        }

        public boolean openPointsAdmin(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openpointsadmin")) return true;
            if (!isBedrock(admin) || !plugin.has(admin, "simplexadminsuite.points.admin")) return false;
            CustomForm.Builder form = CustomForm.builder().title("§l§bSIMPLEX POINTS")
                    .toggle("§fPunktesystem aktiv", plugin.getConfig().getBoolean("simplex-points.enabled", true))
                    .slider("§fAktive Minuten pro Belohnung", 1F, 60F, 1F, plugin.getConfig().getInt("simplex-points.award-interval-minutes", 10))
                    .slider("§fPunkte pro Belohnung", 1F, 100F, 1F, plugin.getConfig().getInt("simplex-points.points-per-interval", 5))
                    .toggle("§fLuckPerms Präfix/Suffix über Namen", plugin.getConfig().getBoolean("nameplates.show-luckperms", true))
                    .toggle("§fDiscord Top-10 im Status", plugin.getConfig().getBoolean("simplex-points.discord-leaderboard", false))
                    .input("§fOptional: Spielername", "Leer = nur Einstellungen speichern", "")
                    .input("§fNeuer Kontostand", "Zahl oder RESET", "")
                    .validResultHandler(response -> sync(() -> {
                        plugin.expansion.updatePointsSettings(admin.getName(), response.asToggle(0), Math.round(response.asSlider(1)), Math.round(response.asSlider(2)), false, response.asToggle(3), response.asToggle(4));
                        String query = plugin.sanitizeText(response.asInput(5), 80);
                        String balance = plugin.sanitizeText(response.asInput(6), 32);
                        if (!query.isBlank() && !balance.isBlank()) {
                            PlayerProfile target = plugin.database.find(query);
                            if (target == null) plugin.menuNotice(admin,plugin.prefix() + "Spielerprofil für Kontostandänderung nicht gefunden.");
                            else {
                                try {
                                    long value = balance.equalsIgnoreCase("RESET") ? 0L : Long.parseLong(balance);
                                    if (value < 0L || value > 1_000_000_000L) throw new NumberFormatException("range");
                                    target.setSimplexPoints(value); plugin.database.save(target); plugin.refreshExpansionNameplate(Bukkit.getPlayer(target.uuid)); plugin.discordPointsChanged();
                                    plugin.audit.log(admin.getName(), target.uuid, "Simplex Points per Bedrock-Menü gesetzt", Long.toString(value));
                                    admin.sendMessage(plugin.prefix() + "Kontostand von " + target.name + " ist jetzt " + value + " SP.");
                                } catch (Exception error) { plugin.menuNotice(admin,plugin.prefix() + "Ungültiger Kontostand; erlaubt sind 0 bis 1.000.000.000 oder RESET."); }
                            }
                        }
                        plugin.menuNotice(admin,plugin.prefix() + "Die Simplex-Points-Einstellungen wurden gespeichert.");
                        openMain(admin);
                    }))
                    .closedOrInvalidResultHandler(() -> sync(() -> openMain(admin)));
            return send(admin, form);
        }

