        private boolean openPasswordManagement(Player admin, int requestedPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openpasswordmanagement")) return true;
            if (!isBedrock(admin) || !admin.isOp()) return false;
            List<StaffMember> members = plugin.staffWorkspace.members().stream()
                    .filter(member -> !admin.getUniqueId().equals(member.uuid)).collect(Collectors.toList());
            int pageSize = 15;
            int maxPage = Math.max(0, (members.size() - 1) / pageSize);
            int page = Math.max(0, Math.min(requestedPage, maxPage));
            SimpleForm.Builder form = SimpleForm.builder().title("§l§cADMIN-PASSWÖRTER")
                    .content("§fNur echte Server-Operatoren können persönliche Passwörter anderer Staff-Mitglieder setzen oder zurücksetzen.\n§7Seite " + (page + 1) + "/" + (maxPage + 1));
            int from = page * pageSize;
            int to = Math.min(members.size(), from + pageSize);
            for (int i = from; i < to; i++) {
                StaffMember member = members.get(i);
                boolean personal = plugin.adminSecurity.hasPersonalPassword(member.uuid);
                form.button("§e" + member.name + "\n§f" + (personal ? "Persönliches Passwort" : "Allgemeines Passwort"),
                        response -> sync(() -> openPasswordTarget(admin, member.uuid, page)));
            }
            if (page > 0) form.button("§eVorherige Seite", response -> sync(() -> openPasswordManagement(admin, page - 1)));
            if (page < maxPage) form.button("§eNächste Seite", response -> sync(() -> openPasswordManagement(admin, page + 1)));
            form.button("§cZurück", response -> sync(() -> openSecuritySettings(admin)));
            return send(admin, form);
        }

        private boolean openPasswordTarget(Player admin, UUID target, int returnPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openpasswordtarget")) return true;
            if (!isBedrock(admin) || !admin.isOp() || target == null || !plugin.isStaffAccount(target)) return false;
            PlayerProfile profile = plugin.database.get(target);
            if (profile == null) return openPasswordManagement(admin, returnPage);
            SimpleForm.Builder form = SimpleForm.builder().title("§l§cPASSWORT: §f" + profile.name)
                    .content("§fAktueller Typ: §e" + (plugin.adminSecurity.hasPersonalPassword(target) ? "Persönliches Passwort" : "Allgemeines Serverpasswort"));
            form.button("§aNeues persönliches Passwort setzen", response -> sync(() -> openOtherPasswordChange(admin, target)));
            form.button("§cAuf allgemeines Passwort zurücksetzen", response -> sync(() -> confirmPasswordReset(admin, target, returnPage)));
            form.button("§cZurück zur Auswahl", response -> sync(() -> openPasswordManagement(admin, returnPage)));
            return send(admin, form);
        }

        private boolean confirmPasswordReset(Player admin, UUID target, int returnPage) {
            PlayerProfile profile = plugin.database.get(target);
            if (profile == null || !admin.isOp()) return openPasswordManagement(admin, returnPage);
            SimpleForm.Builder form = SimpleForm.builder().title("§l§cPASSWORT ZURÜCKSETZEN")
                    .content("§fPersönliches Passwort von §e" + profile.name + " §fvollständig entfernen? Danach gilt wieder das allgemeine Serverpasswort.");
            form.button("§cJa, zurücksetzen", response -> sync(() -> {
                plugin.adminSecurity.resetPersonalPassword(target, admin.getName());
                plugin.menuNotice(admin,plugin.prefix() + "Das persönliche Passwort von " + profile.name + " wurde zurückgesetzt.");
                openPasswordTarget(admin, target, returnPage);
            }));
            form.button("§aAbbrechen", response -> sync(() -> openPasswordTarget(admin, target, returnPage)));
            return send(admin, form);
        }

