        private boolean openBedrockLagResults(Player admin, int requestedPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openbedrocklagresults")) return true;
            List<AdminPowerToolsManager.Hotspot> hotspots = plugin.powerTools.hotspotsSnapshot();
            int pageSize = 12, maxPage = Math.max(0, (hotspots.size() - 1) / pageSize), page = Math.max(0, Math.min(requestedPage, maxPage));
            SimpleForm.Builder form = SimpleForm.builder().title("§l§cLAG-HOTSPOTS §7" + (page + 1) + "/" + (maxPage + 1))
                    .content(hotspots.isEmpty() ? "§7Noch keine Hotspots gespeichert." : "§7Teleport lädt niemals einen entladenen Chunk nach.");
            int from = page * pageSize;
            for (int i = from; i < Math.min(hotspots.size(), from + pageSize); i++) {
                AdminPowerToolsManager.Hotspot hotspot = hotspots.get(i);
                int index = i;
                String color = hotspot.score >= plugin.getConfig().getInt("lag-inspector.critical-score", 180) ? "§c" : "§e";
                form.button(color + hotspot.world + " " + hotspot.chunkX + "/" + hotspot.chunkZ + " • " + hotspot.score + "\n§f" + hotspot.reason,
                        response -> sync(() -> { plugin.powerTools.teleportToHotspot(admin, index); openBedrockLagResults(admin, page); }));
            }
            if (page > 0) form.button("§eVorherige Seite", response -> sync(() -> openBedrockLagResults(admin, page - 1)));
            if (page < maxPage) form.button("§eNächste Seite", response -> sync(() -> openBedrockLagResults(admin, page + 1)));
            form.button("§cZurück zum Lag-Inspector", response -> sync(() -> openLagInspector(admin)));
            return send(admin, form);
        }

        private boolean openBedrockLagHistory(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openbedrocklaghistory")) return true;
            StringBuilder content = new StringBuilder();
            List<AdminPowerToolsManager.LagHistoryEntry> history = plugin.powerTools.lagHistorySnapshot();
            for (int i = 0; i < Math.min(20, history.size()); i++) {
                AdminPowerToolsManager.LagHistoryEntry h = history.get(i);
                content.append(h.cancelled ? "§7■ " : h.highestScore >= plugin.getConfig().getInt("lag-inspector.critical-score", 180) ? "§c■ " : "§e■ ")
                        .append(new SimpleDateFormat("dd.MM HH:mm", Locale.GERMANY).format(new Date(h.at))).append(" §f• ")
                        .append(h.chunks).append(" Chunks • ").append(h.hotspots).append(" Hotspots • Score ").append(h.highestScore).append("\n");
            }
            SimpleForm.Builder form = SimpleForm.builder().title("§l§6LAG-SCAN-VERLAUF")
                    .content(content.length() == 0 ? "§7Noch keine Scans gespeichert." : content.toString());
            form.button("§cZurück zum Lag-Inspector", response -> sync(() -> openLagInspector(admin)));
            return send(admin, form);
        }

