        public boolean openQolTasks(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqoltasks")) return true; return openQolTasks(admin, 0); }

        private boolean openQolTasks(Player admin, int requestedPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqoltasks")) return true;
            if (!qolAllowed(admin, "simplexadminsuite.qol.tasks", false)) return false;
            List<AdminQualityManager.StaffTask> tasks = plugin.adminQuality.tasksSnapshot();
            int pageSize = 12;
            int maxPage = Math.max(0, (tasks.size() - 1) / pageSize);
            int page = Math.max(0, Math.min(requestedPage, maxPage));
            SimpleForm.Builder form = SimpleForm.builder().title("§l§aSTAFF-AUFGABEN §7" + (page + 1) + "/" + (maxPage + 1))
                    .content("§fOffen: §e" + plugin.adminQuality.openTaskCount() + " §8• §fÜberfällig: §c" + plugin.adminQuality.overdueTaskCount()
                            + " §8• §fErledigt: §a" + plugin.adminQuality.doneTaskCount());
            int start = page * pageSize;
            for (int i = start; i < Math.min(tasks.size(), start + pageSize); i++) {
                AdminQualityManager.StaffTask task = tasks.get(i);
                String color = task.status == AdminQualityManager.TaskStatus.DONE ? "§a" : task.priority == AdminQualityManager.Priority.URGENT ? "§c" : "§e";
                form.button(color + "#" + task.id + " " + task.title + "\n§f" + qolTaskStatus(task) + " • " + qolPriority(task.priority),
                        response -> sync(() -> openQolTask(admin, task.id, page)));
            }
            form.button("§aNeue Aufgabe anlegen", response -> sync(() -> openQolTaskCreate(admin)));
            if (page > 0) form.button("§eVorherige Seite", response -> sync(() -> openQolTasks(admin, page - 1)));
            if (page < maxPage) form.button("§eNächste Seite", response -> sync(() -> openQolTasks(admin, page + 1)));
            form.button("§cZurück zum Team-Dashboard", response -> sync(() -> openAdminQuality(admin)));
            return send(admin, form);
        }

        private boolean openQolTaskCreate(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqoltaskcreate")) return true;
            if (!qolAllowed(admin, "simplexadminsuite.qol.tasks", false)) return false;
            List<String> priorities = List.of("Niedrig", "Normal", "Hoch", "Dringend");
            List<String> due = List.of("Keine Fälligkeit", "1 Stunde", "6 Stunden", "24 Stunden", "3 Tage", "7 Tage");
            CustomForm.Builder form = CustomForm.builder().title("§l§aNEUE STAFF-AUFGABE")
                    .input("§fTitel", "Kurzer interner Titel", "")
                    .input("§fInterne Details", "Beschreibung oder Übergabehinweis", "")
                    .dropdown("§fPriorität", priorities, 1)
                    .dropdown("§fFälligkeit", due, 3)
                    .validResultHandler(response -> sync(() -> {
                        long[] delays = new long[]{0L, 60L * 60_000L, 6L * 60L * 60_000L, 24L * 60L * 60_000L, 3L * 24L * 60L * 60_000L, 7L * 24L * 60L * 60_000L};
                        int priority = Math.max(0, Math.min(AdminQualityManager.Priority.values().length - 1, response.asDropdown(2)));
                        int dueIndex = Math.max(0, Math.min(delays.length - 1, response.asDropdown(3)));
                        long dueAt = delays[dueIndex] <= 0L ? 0L : System.currentTimeMillis() + delays[dueIndex];
                        AdminQualityManager.StaffTask created = plugin.adminQuality.createTask(admin, response.asInput(0), response.asInput(1), AdminQualityManager.Priority.values()[priority], dueAt);
                        plugin.menuNotice(admin,plugin.prefix() + (created == null ? "Die Aufgabe konnte nicht angelegt werden." : "Staff-Aufgabe #" + created.id + " wurde angelegt."));
                        openQolTasks(admin, 0);
                    })).closedOrInvalidResultHandler(() -> sync(() -> openQolTasks(admin, 0)));
            return send(admin, form);
        }

        private boolean openQolTask(Player admin, long id, int returnPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqoltask")) return true;
            AdminQualityManager.StaffTask task = plugin.adminQuality.task(id);
            if (task == null || !qolAllowed(admin, "simplexadminsuite.qol.tasks", false)) return openQolTasks(admin, returnPage);
            String due = task.dueAt <= 0L ? "Keine" : new SimpleDateFormat("dd.MM.yyyy HH:mm", Locale.GERMANY).format(new Date(task.dueAt));
            SimpleForm.Builder form = SimpleForm.builder().title("§l§aAUFGABE #" + id)
                    .content("§f" + task.title + "\n\n§7" + task.details + "\n\n§fStatus: §e" + qolTaskStatus(task)
                            + "\n§fPriorität: §e" + qolPriority(task.priority) + "\n§fZugewiesen: §e" + (task.assignedName.isBlank() ? "Niemand" : task.assignedName)
                            + "\n§fFällig: §e" + due + "\n§fErstellt von: §e" + task.createdBy);
            if (task.status != AdminQualityManager.TaskStatus.DONE) form.button(admin.getUniqueId().equals(task.assignedUuid) ? "§eZuweisung lösen" : "§aAufgabe übernehmen", response -> sync(() -> { plugin.adminQuality.claimTask(admin, id); openQolTask(admin, id, returnPage); }));
            form.button(task.status == AdminQualityManager.TaskStatus.DONE ? "§eWieder öffnen" : "§aAls erledigt markieren", response -> sync(() -> { plugin.adminQuality.toggleTaskDone(admin, id); openQolTask(admin, id, returnPage); }));
            form.button("§ePriorität wechseln", response -> sync(() -> { plugin.adminQuality.cycleTaskPriority(admin, id); openQolTask(admin, id, returnPage); }));
            form.button("§cAufgabe löschen", response -> sync(() -> confirmQol(admin, "AUFGABE LÖSCHEN", "Staff-Aufgabe #" + id + " endgültig löschen?", () -> { plugin.adminQuality.deleteTask(admin, id); openQolTasks(admin, returnPage); }, () -> openQolTask(admin, id, returnPage))));
            form.button("§cZurück zur Liste", response -> sync(() -> openQolTasks(admin, returnPage)));
            return send(admin, form);
        }

        public boolean openQolScheduler(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqolscheduler")) return true; return openQolScheduler(admin, 0); }

        private boolean openQolScheduler(Player admin, int requestedPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqolscheduler")) return true;
            if (!qolAllowed(admin, "simplexadminsuite.qol.scheduler", true)) return false;
            List<AdminQualityManager.ScheduledJob> jobs = plugin.adminQuality.jobsSnapshot();
            int pageSize = 12;
            int maxPage = Math.max(0, (jobs.size() - 1) / pageSize);
            int page = Math.max(0, Math.min(requestedPage, maxPage));
            SimpleForm.Builder form = SimpleForm.builder().title("§l§eAKTIONSPLANER §7" + (page + 1) + "/" + (maxPage + 1))
                    .content("§fAusstehend: §e" + plugin.adminQuality.pendingJobCount() + "\n§7Fällige Aktionen werden nach einem Neustart nur innerhalb des sicheren Nachholfensters ausgeführt.");
            int start = page * pageSize;
            for (int i = start; i < Math.min(jobs.size(), start + pageSize); i++) {
                AdminQualityManager.ScheduledJob job = jobs.get(i);
                String state = (job.status == AdminQualityManager.JobStatus.FAILED ? "§c" : job.status == AdminQualityManager.JobStatus.EXECUTED ? "§a" : "§e") + qolJobStatus(job.status);
                form.button("§e#" + job.id + " " + AdminQualityManager.jobActionLabel(job.action) + "\n" + state,
                        response -> sync(() -> openQolJob(admin, job.id, page)));
            }
            form.button("§aNeue Aktion planen", response -> sync(() -> openQolJobCreate(admin)));
            if (page > 0) form.button("§eVorherige Seite", response -> sync(() -> openQolScheduler(admin, page - 1)));
            if (page < maxPage) form.button("§eNächste Seite", response -> sync(() -> openQolScheduler(admin, page + 1)));
            form.button("§cZurück zum Team-Dashboard", response -> sync(() -> openAdminQuality(admin)));
            return send(admin, form);
        }

        private boolean openQolJobCreate(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqoljobcreate")) return true;
            if (!qolAllowed(admin, "simplexadminsuite.qol.scheduler", true)) return false;
            List<String> actions = Arrays.stream(AdminQualityManager.JobAction.values()).map(AdminQualityManager::jobActionLabel).collect(Collectors.toList());
            List<String> delays = List.of("30 Sekunden", "1 Minute", "5 Minuten", "15 Minuten", "30 Minuten", "1 Stunde", "3 Stunden", "24 Stunden", "3 Tage", "7 Tage");
            CustomForm.Builder form = CustomForm.builder().title("§l§eAKTION PLANEN")
                    .dropdown("§fAktion", actions, 0)
                    .dropdown("§fVerzögerung", delays, 2)
                    .input("§fEnglischer Ankündigungstext", "Nur für Server-Ankündigung erforderlich", "")
                    .validResultHandler(response -> sync(() -> {
                        long[] millis = new long[]{30_000L,60_000L,5L*60_000L,15L*60_000L,30L*60_000L,60L*60_000L,3L*60L*60_000L,24L*60L*60_000L,3L*24L*60L*60_000L,7L*24L*60L*60_000L};
                        int action = Math.max(0, Math.min(AdminQualityManager.JobAction.values().length - 1, response.asDropdown(0)));
                        int delay = Math.max(0, Math.min(millis.length - 1, response.asDropdown(1)));
                        AdminQualityManager.JobAction selected = AdminQualityManager.JobAction.values()[action];
                        long selectedDelay = millis[delay];
                        String payload = plugin.sanitizeText(response.asInput(2), 500);
                        if (selected == AdminQualityManager.JobAction.ANNOUNCEMENT && payload.isBlank()) {
                            admin.sendMessage(plugin.prefix() + "Für eine Server-Ankündigung ist ein englischer Text Pflicht.");
                            openQolJobCreate(admin);
                            return;
                        }
                        confirmQol(admin, "AKTION EINPLANEN", AdminQualityManager.jobActionLabel(selected) + " in " + AdminQualityManager.delayLabel(selectedDelay) + " verbindlich einplanen?",
                                () -> {
                                    AdminQualityManager.ScheduledJob created = plugin.adminQuality.createJob(admin, selected, selectedDelay, payload);
                                    plugin.menuNotice(admin,plugin.prefix() + (created == null ? "Die Aktion konnte nicht geplant werden." : "Aktion #" + created.id + " wurde verbindlich geplant."));
                                    openQolScheduler(admin, 0);
                                }, () -> openQolJobCreate(admin));
                    })).closedOrInvalidResultHandler(() -> sync(() -> openQolScheduler(admin, 0)));
            return send(admin, form);
        }

        private boolean openQolJob(Player admin, long id, int returnPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqoljob")) return true;
            AdminQualityManager.ScheduledJob job = plugin.adminQuality.job(id);
            if (job == null || !qolAllowed(admin, "simplexadminsuite.qol.scheduler", true)) return openQolScheduler(admin, returnPage);
            String when = new SimpleDateFormat("dd.MM.yyyy HH:mm:ss", Locale.GERMANY).format(new Date(job.executeAt));
            SimpleForm.Builder form = SimpleForm.builder().title("§l§eAKTION #" + id)
                    .content("§f" + AdminQualityManager.jobActionLabel(job.action) + "\n\n§fStatus: §e" + qolJobStatus(job.status)
                            + "\n§fAusführung: §e" + when + "\n§fErstellt von: §e" + job.createdBy
                            + (job.payload.isBlank() ? "" : "\n§fInhalt: §e" + job.payload)
                            + (job.result.isBlank() ? "" : "\n§fErgebnis: §e" + job.result));
            if (job.status == AdminQualityManager.JobStatus.PENDING) {
                form.button("§aJetzt ausführen", response -> sync(() -> confirmQol(admin, "SOFORT AUSFÜHREN", "Geplante Aktion #" + id + " jetzt ausführen?", () -> { plugin.adminQuality.executeJobNow(admin, id); openQolScheduler(admin, returnPage); }, () -> openQolJob(admin, id, returnPage))));
                form.button("§cAktion abbrechen", response -> sync(() -> confirmQol(admin, "AKTION ABBRECHEN", "Geplante Aktion #" + id + " abbrechen?", () -> { plugin.adminQuality.cancelJob(admin, id); openQolScheduler(admin, returnPage); }, () -> openQolJob(admin, id, returnPage))));
            } else form.button("§cVerlaufseintrag löschen", response -> sync(() -> confirmQol(admin, "VERLAUF LÖSCHEN", "Abgeschlossene Aktion #" + id + " aus dem Planer löschen?", () -> { plugin.adminQuality.deleteJob(admin, id); openQolScheduler(admin, returnPage); }, () -> openQolJob(admin, id, returnPage))));
            form.button("§cZurück zur Liste", response -> sync(() -> openQolScheduler(admin, returnPage)));
            return send(admin, form);
        }

