        public boolean openQolMacros(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqolmacros")) return true; return openQolMacros(admin, 0); }

        private boolean openQolMacros(Player admin, int requestedPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqolmacros")) return true;
            if (!qolAllowed(admin, "simplexadminsuite.qol.macros", true)) return false;
            List<AdminQualityManager.AdminMacro> macros = plugin.adminQuality.macrosSnapshot();
            int pageSize = 12;
            int maxPage = Math.max(0, (macros.size() - 1) / pageSize);
            int page = Math.max(0, Math.min(requestedPage, maxPage));
            SimpleForm.Builder form = SimpleForm.builder().title("§l§dSICHERE OP-MAKROS §7" + (page + 1) + "/" + (maxPage + 1))
                    .content("§fAktiv: §e" + plugin.adminQuality.enabledMacroCount() + "/" + plugin.adminQuality.macroCount()
                            + "\n§7Platzhalter: {player}, {world}, {x}, {y}, {z}, {online}\n§7Lifecycle-, OP- und verkettete Befehle sind gesperrt.");
            int start = page * pageSize;
            for (int i = start; i < Math.min(macros.size(), start + pageSize); i++) {
                AdminQualityManager.AdminMacro macro = macros.get(i);
                form.button((macro.enabled ? "§d" : "§7") + "#" + macro.id + " " + macro.name + "\n§f/" + macro.command,
                        response -> sync(() -> openQolMacro(admin, macro.id, page)));
            }
            form.button("§aNeues OP-Makro", response -> sync(() -> openQolMacroCreate(admin)));
            if (page > 0) form.button("§eVorherige Seite", response -> sync(() -> openQolMacros(admin, page - 1)));
            if (page < maxPage) form.button("§eNächste Seite", response -> sync(() -> openQolMacros(admin, page + 1)));
            form.button("§cZurück zum Team-Dashboard", response -> sync(() -> openAdminQuality(admin)));
            return send(admin, form);
        }

        private boolean openQolMacroCreate(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqolmacrocreate")) return true;
            if (!qolAllowed(admin, "simplexadminsuite.qol.macros", true)) return false;
            CustomForm.Builder form = CustomForm.builder().title("§l§dNEUES OP-MAKRO")
                    .input("§fInterner Name", "Welten sicher speichern", "")
                    .input("§fKonsolenbefehl ohne /", "save-all flush", "")
                    .toggle("§fBestätigung vor Ausführung", true)
                    .validResultHandler(response -> sync(() -> {
                        AdminQualityManager.AdminMacro created = plugin.adminQuality.createMacro(admin, response.asInput(0), response.asInput(1), response.asToggle(2));
                        plugin.menuNotice(admin,plugin.prefix() + (created == null ? "Das Makro wurde abgelehnt. Prüfe Namen und Sicherheitsregeln." : "OP-Makro #" + created.id + " wurde angelegt."));
                        openQolMacros(admin, 0);
                    })).closedOrInvalidResultHandler(() -> sync(() -> openQolMacros(admin, 0)));
            return send(admin, form);
        }

        private boolean openQolMacro(Player admin, long id, int returnPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openqolmacro")) return true;
            AdminQualityManager.AdminMacro macro = plugin.adminQuality.macro(id);
            if (macro == null || !qolAllowed(admin, "simplexadminsuite.qol.macros", true)) return openQolMacros(admin, returnPage);
            SimpleForm.Builder form = SimpleForm.builder().title("§l§dOP-MAKRO #" + id)
                    .content("§f" + macro.name + "\n\n§fBefehl: §e/" + macro.command + "\n§fStatus: " + (macro.enabled ? "§aAktiv" : "§cInaktiv")
                            + "\n§fBestätigung: §e" + (macro.confirmation ? "Pflicht" : "Direkt") + "\n§fErstellt von: §e" + macro.createdBy);
            form.button("§aMakro ausführen", response -> sync(() -> {
                if (macro.confirmation) confirmQol(admin, "MAKRO AUSFÜHREN", "Makro '" + macro.name + "' als Konsole ausführen?", () -> { plugin.adminQuality.executeMacro(admin, id); openQolMacro(admin, id, returnPage); }, () -> openQolMacro(admin, id, returnPage));
                else { plugin.adminQuality.executeMacro(admin, id); openQolMacro(admin, id, returnPage); }
            }));
            form.button("§eStatus umschalten", response -> sync(() -> { plugin.adminQuality.toggleMacro(admin, id); openQolMacro(admin, id, returnPage); }));
            form.button("§eBestätigung umschalten", response -> sync(() -> { plugin.adminQuality.toggleMacroConfirmation(admin, id); openQolMacro(admin, id, returnPage); }));
            form.button("§cMakro löschen", response -> sync(() -> confirmQol(admin, "MAKRO LÖSCHEN", "Makro '" + macro.name + "' endgültig löschen?", () -> { plugin.adminQuality.deleteMacro(admin, id); openQolMacros(admin, returnPage); }, () -> openQolMacro(admin, id, returnPage))));
            form.button("§cZurück zur Liste", response -> sync(() -> openQolMacros(admin, returnPage)));
            return send(admin, form);
        }

