        public boolean openPlayerCheck(Player admin, UUID targetUuid) {
        if (!plugin.adminMenuAllowed(admin, "suite.openplayercheck")) return true;
            if (admin == null || !isBedrock(admin) || !plugin.has(admin, "simplexadminsuite.check")) return false;
            PlayerProfile target = plugin.database.get(targetUuid);
            if (target == null) { plugin.menuNotice(admin,plugin.prefix()+"Spielerprofil nicht gefunden."); return true; }
            SimpleForm.Builder form = SimpleForm.builder().title("§l§6CLIENTPRÜFUNG")
                    .content(plugin.playerCheckText(admin, target));
            if(plugin.javaProbeTarget(target.uuid)&&plugin.has(admin,"simplexadminsuite.clientcheck"))form.button(plugin.playerText(admin,"§bClient-Prüfungen & Verlauf","§bClient probes & history"),response->sync(()->plugin.openClientProbe(admin,target.uuid)));
            if (plugin.has(admin, "simplexadminsuite.client.channels") && "JAVA".equalsIgnoreCase(target.clientPlatform)) form.button("§dJava-Mod-Kanäle\n§f" + target.javaRegisteredChannelsSnapshot().size() + " registrierte Kanäle", response -> sync(() -> openClientChannels(admin, target.uuid)));
            if (plugin.has(admin, "simplexadminsuite.alts.identities")) form.button("§bGerätehistorie verwalten\n§f" + target.devices.size() + " gespeicherte Geräte", response -> sync(() -> openBedrockDeviceHistory(admin, target.uuid, 0, "ALL", "")));
            if (plugin.has(admin, "simplexadminsuite.alts")) form.button("§cForensische Alt-Ansicht", response -> sync(() -> openAltPlayer(admin, target.uuid)));
            form.button("§cZurück zum Spielerprofil", response -> sync(() -> openPlayer(admin, target.uuid)));
            return send(admin, form);
        }

