        public boolean openSecuritySettings(Player admin) {
        if (!plugin.adminMenuAllowed(admin, "suite.opensecuritysettings")) return true;
            if (admin == null || !isBedrock(admin) || !plugin.has(admin, "simplexadminsuite.security")) return false;
            boolean active = plugin.getConfig().getBoolean("admin-security.enabled", true);
            SimpleForm.Builder form = SimpleForm.builder().title("§l§cADMIN-SICHERHEIT")
                    .content("§fPasswortschutz: " + (active ? "§aAktiv" : "§cInaktiv")
                            + "\n§fDein Passworttyp: §e" + (plugin.adminSecurity.hasPersonalPassword(admin.getUniqueId()) ? "Persönlich" : "Allgemein")
                            + "\n§fMaximale Versuche: §e" + plugin.getConfig().getInt("admin-security.max-attempts", 3)
                            + "\n§fZeitlimit: §e" + plugin.getConfig().getLong("admin-security.timeout-seconds", 90L) + " Sekunden"
                            + "\n\n§fJava-Admins melden sich über den geschützten Chat an. Bedrock-Admins verwenden dieses native Formular.");
            form.button("§bEigenes Passwort ändern", response -> sync(() -> openOwnPasswordChange(admin)));
            if (admin.isOp()) {
                form.button("§cPasswörter anderer Admins verwalten", response -> sync(() -> openPasswordManagement(admin, 0)));
                form.button(active ? "§cPasswortschutz deaktivieren" : "§aPasswortschutz aktivieren", response -> sync(() -> { plugin.getConfig().set("admin-security.enabled", !active); plugin.saveConfig(); plugin.adminSecurity.reload(); openSecuritySettings(admin); }));
                form.button("§eVersuchslimit wechseln", response -> sync(() -> { int current=plugin.getConfig().getInt("admin-security.max-attempts",3); plugin.getConfig().set("admin-security.max-attempts", current>=5?3:current+1); plugin.saveConfig(); plugin.adminSecurity.reload(); openSecuritySettings(admin); }));
                form.button("§eZeitlimit wechseln", response -> sync(() -> { long current=plugin.getConfig().getLong("admin-security.timeout-seconds",90L); long next=current<90?90:current<120?120:current<180?180:60; plugin.getConfig().set("admin-security.timeout-seconds",next); plugin.saveConfig(); plugin.adminSecurity.reload(); openSecuritySettings(admin); }));
            }
            form.button("§cZurück zur Server-Steuerung", response -> sync(() -> openServerControls(admin)));
            return send(admin, form);
        }

