            form.button("§eVerlassensnachricht: " + (plugin.adminSpy.hiddenQuit(admin) ? "§aUnterdrückt" : "§fSichtbar"), response -> sync(() -> { plugin.adminSpy.toggleHiddenQuit(admin); openStealthSettings(admin); }));
            form.button("§eKompletter Stealth-Modus: " + (plugin.adminSpy.hiddenTab(admin) ? "§aAktiv" : "§fInaktiv"), response -> sync(() -> { plugin.adminSpy.toggleHiddenTab(admin); openStealthSettings(admin); }));
