        private void openPunishmentInput(Player admin, UUID uuid, String action, boolean temporary) {
        if (!plugin.adminMenuAllowed(admin, "suite.openpunishmentinput")) return;
            PlayerProfile target = plugin.database.get(uuid); if (target == null) return;
            CustomForm.Builder form = CustomForm.builder().title("§l§c" + actionLabel(action).toUpperCase(Locale.ROOT) + ": §f" + target.name);
            DurationSelection defaults = DurationSelection.from(plugin.getConfig().getString("punishments.default-temp-duration", "1d"));
            if (temporary) {
                form.slider("§fDauer", 1F, 60F, 1F, defaults.amount);
                form.dropdown("§fEinheit", Arrays.asList("Minuten", "Stunden", "Tage"), defaults.unitIndex);
            }
            form.input("§fGrund", "No reason provided", "");
            form.validResultHandler(response -> sync(() -> {
                String duration = "";
                int reasonIndex = 0;
                if (temporary) {
                    int amount = Math.max(1, Math.min(60, Math.round(response.asSlider(0))));
                    int unit = Math.max(0, Math.min(2, response.asDropdown(1)));
                    duration = amount + (unit == 0 ? "m" : unit == 1 ? "h" : "d");
                    reasonIndex = 2;
                }
                String reason = plugin.sanitizeText(response.asInput(reasonIndex), plugin.getConfig().getInt("punishments.max-reason-length", 240));
                if (reason.isEmpty()) reason = "No reason provided";
                String finalReason = reason;
                String finalDuration = duration;
                String details = "§7Ziel: §f" + target.name + "\n§7Aktion: §f" + actionLabel(action)
                        + (temporary ? "\n§7Dauer: §f" + duration : "") + "\n§7Grund: §f" + reason;
                confirm(admin, actionLabel(action), details, () -> performPunishment(admin, target.uuid, action, finalDuration, finalReason), () -> openPunishments(admin, target.uuid));
            }));
            send(admin, form);
        }

        private static final class DurationSelection {
            private final float amount;
            private final int unitIndex;
            private DurationSelection(float amount, int unitIndex) { this.amount = amount; this.unitIndex = unitIndex; }
            private static DurationSelection from(String configured) {
                String value = plainDuration(configured);
                Matcher matcher = Pattern.compile("(?i)^(\\d+)([mhd])$").matcher(value);
                if (!matcher.matches()) return new DurationSelection(1F, 2);
                int amount;
                try { amount = Integer.parseInt(matcher.group(1)); } catch (NumberFormatException ignored) { return new DurationSelection(1F, 2); }
                amount = Math.max(1, Math.min(60, amount));
                String unit = matcher.group(2).toLowerCase(Locale.ROOT);
                return new DurationSelection(amount, unit.equals("m") ? 0 : unit.equals("h") ? 1 : 2);
            }
        }

        private void performPunishment(Player admin, UUID uuid, String action, String duration, String reason) {
            PlayerProfile target = plugin.database.get(uuid); if (target == null) return;
            boolean ok = plugin.executePunishment(admin, action, target, target.name, duration, reason);
            if (ok) {
                target.addAction("Bedrock-Menü-Strafaktion durch " + admin.getName() + ": " + action + " " + duration + " " + reason);
                plugin.database.save(target);
                plugin.audit.log(admin.getName(), target.uuid, "Strafaktion", action + " " + duration + " " + reason);
                admin.sendMessage(plugin.prefix() + "Aktion ausgeführt: " + action + " für " + target.name + ".");
            } else plugin.menuNotice(admin,plugin.prefix() + "Aktion konnte nicht ausgeführt werden. Prüfe Anbieter und Zielstatus.");
            openPunishments(admin, target.uuid);
        }

        private void openRights(Player admin, UUID uuid) {
        if (!plugin.adminMenuAllowed(admin, "suite.openrights")) return;
            if (!plugin.has(admin, "simplexadminsuite.rights")) { admin.sendMessage(plugin.prefix() + "Dafür fehlt dir simplexadminsuite.rights."); return; }
            PlayerProfile target = plugin.database.get(uuid); if (target == null) return;
            String blocked = target.blockedRights().isEmpty() ? "Keine" : target.blockedRights().stream().map(key -> RIGHT_NAMES.getOrDefault(key, key)).collect(Collectors.joining(", "));
            int temporaryCount = target.temporaryBlockedRightsSnapshot().size();
            SimpleForm.Builder form = SimpleForm.builder().title("§l§eRECHTE: §f" + target.name)
                    .content("§7Aktive Sperren: §f" + blocked + "\n§7Davon temporär: §6" + temporaryCount + "\n\n§8Im Editor bedeutet ein aktivierter Schalter: erlaubt.");
            form.button("§eRechte 1/4 bearbeiten\n§7Chat, Farben, Formatierung und Bewegung", response -> sync(() -> openRightsEditor(admin, target.uuid, 0)));
            form.button("§eRechte 2/4 bearbeiten\n§7Kampf, Dimensionen und Verbrauch", response -> sync(() -> openRightsEditor(admin, target.uuid, 1)));
            form.button("§eRechte 3/4 bearbeiten\n§7Behälter, Spezialblöcke und Welt", response -> sync(() -> openRightsEditor(admin, target.uuid, 2)));
            form.button("§eRechte 4/4 bearbeiten\n§7Bücher, Teleport und weitere Details", response -> sync(() -> openRightsEditor(admin, target.uuid, 3)));
            form.button("§6Temporäre Sperre setzen\n§7Recht und Dauer auswählen", response -> sync(() -> openTemporaryRight(admin, target.uuid)));
            if (plugin.has(admin, "simplexadminsuite.alt-rights")) form.button("§dAlt-Rechtevererbung\n§7Bestehende und zukünftige Konten", response -> sync(() -> openAltRightsPolicy(admin, target.uuid)));
            form.button("§aAlle Rechte erlauben", response -> sync(() -> confirm(admin, "Alle Rechte erlauben", "Alle Sperren für " + target.name + " entfernen?", () -> setAllRights(admin, target.uuid, false), () -> openRights(admin, target.uuid))));
            form.button("§cAlle Rechte sperren", response -> sync(() -> confirm(admin, "Alle Rechte sperren", "Wirklich alle Rechte für " + target.name + " sperren?", () -> setAllRights(admin, target.uuid, true), () -> openRights(admin, target.uuid))));
            form.button(target.isBlocked("move") ? "§aFreeze aufheben" : "§bSofort einfrieren", response -> sync(() -> { plugin.setFrozen(admin, target, !target.isBlocked("move")); openRights(admin, target.uuid); }));
            form.button("§cZurück zum Spieler", response -> sync(() -> openPlayer(admin, target.uuid)));
            send(admin, form);
        }

        private void openTemporaryRight(Player admin, UUID uuid) {
        if (!plugin.adminMenuAllowed(admin, "suite.opentemporaryright")) return;
            if (!plugin.has(admin, "simplexadminsuite.rights")) return;
            PlayerProfile target = plugin.database.get(uuid); if (target == null) return;
            List<String> labels = new ArrayList<>();
            for (String right : RIGHTS) labels.add(RIGHT_NAMES.getOrDefault(right, right) + " [" + right + "]");
            CustomForm.Builder form = CustomForm.builder().title("§l§6TEMPORÄRE RECHTSSPERRE");
            form.dropdown("§fRecht", labels, 0);
            form.slider("§fDauer", 1F, 60F, 1F, 30F);
            form.dropdown("§fEinheit", Arrays.asList("Minuten", "Stunden", "Tage"), 0);
            form.validResultHandler(response -> sync(() -> {
                int index = Math.max(0, Math.min(RIGHTS.length - 1, response.asDropdown(0)));
                int amount = Math.max(1, Math.min(60, Math.round(response.asSlider(1))));
                int unit = Math.max(0, Math.min(2, response.asDropdown(2)));
                String durationText = amount + (unit == 0 ? "m" : unit == 1 ? "h" : "d");
                DurationValue duration = DurationValue.parse(durationText);
                if (duration == null) { plugin.menuNotice(admin,plugin.prefix() + "Die ausgewählte Dauer ist ungültig."); openRights(admin, uuid); return; }
                String right = RIGHTS[index];
                plugin.setTemporaryRight(admin.getName(), target, right, durationText, duration.until(System.currentTimeMillis()));
                plugin.menuNotice(admin,plugin.prefix() + RIGHT_NAMES.getOrDefault(right, right) + " wurde für " + durationText + " gesperrt.");
                openRights(admin, uuid);
            })).closedOrInvalidResultHandler(() -> sync(() -> openRights(admin, uuid)));
            send(admin, form);
        }

        private void openRightsEditor(Player admin, UUID uuid, int requestedPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.openrightseditor")) return;
            if (!plugin.has(admin, "simplexadminsuite.rights")) return;
            PlayerProfile target = plugin.database.get(uuid); if (target == null) return;
            int pageSize = 16;
            int maxPage = Math.max(0, (RIGHTS.length - 1) / pageSize);
            int page = clamp(requestedPage, 0, maxPage);
            int from = page * pageSize;
            int to = Math.min(RIGHTS.length, from + pageSize);
            CustomForm.Builder form = CustomForm.builder().title("§l§eEINZELRECHTE §f" + (page + 1) + "/" + (maxPage + 1));
            for (int i = from; i < to; i++) {
                String right = RIGHTS[i];
                form.toggle("Erlaubt: " + RIGHT_NAMES.getOrDefault(right, right), !target.isBlocked(right));
            }
            form.validResultHandler(response -> sync(() -> {
                List<String> changes = new ArrayList<>();
                for (int i = from; i < to; i++) {
                    String right = RIGHTS[i];
                    boolean blocked = !response.asToggle(i - from);
                    if (target.isBlocked(right) != blocked) {
                        target.setBlocked(right, blocked);
                        changes.add(right + "=" + (blocked ? "gesperrt" : "erlaubt"));
                    }
                }
                if (!changes.isEmpty()) {
                    target.addAction("Rechte per Bedrock-Form durch " + admin.getName() + " geändert: " + String.join(", ", changes));
                    plugin.database.save(target); plugin.notifyRights(target);
                    plugin.audit.log(admin.getName(), target.uuid, "Rechte geändert", String.join(", ", changes));
                    if (plugin.powerTools != null) plugin.powerTools.rightsChanged(admin.getName(), target.uuid);
                    plugin.menuNotice(admin,plugin.prefix() + changes.size() + " Rechte wurden aktualisiert.");
                }
                openRights(admin, target.uuid);
            })).closedOrInvalidResultHandler(() -> sync(() -> openRights(admin, target.uuid)));
            send(admin, form);
        }

        private void setAllRights(Player admin, UUID uuid, boolean blocked) {
            if (!plugin.has(admin, "simplexadminsuite.rights")) return;
            PlayerProfile target = plugin.database.get(uuid); if (target == null) return;
            for (String right : RIGHTS) target.setBlocked(right, blocked);
            target.addAction("Alle Rechte per Bedrock-Form durch " + admin.getName() + " " + (blocked ? "gesperrt" : "erlaubt"));
            plugin.database.save(target); plugin.notifyRights(target);
            plugin.audit.log(admin.getName(), target.uuid, blocked ? "Alle Rechte gesperrt" : "Alle Rechte erlaubt", "Bedrock-Form");
            if (plugin.powerTools != null) plugin.powerTools.rightsChanged(admin.getName(), target.uuid);
            openRights(admin, target.uuid);
        }

