        private void openSnapshots(Player admin, UUID uuid, int requestedPage) {
        if (!plugin.adminMenuAllowed(admin, "suite.opensnapshots")) return;
            if (!plugin.has(admin, "simplexadminsuite.snapshots")) { admin.sendMessage(plugin.prefix() + "Dafür fehlt dir simplexadminsuite.snapshots."); return; }
            PlayerProfile target = plugin.database.get(uuid); if (target == null) return;
            File[] snapshots = plugin.snapshotFiles(uuid);
            int pageSize = pageSize("floodgate.snapshot-page-size", 15, 5, 20);
            int maxPage = Math.max(0, (snapshots.length - 1) / pageSize);
            int page = clamp(requestedPage, 0, maxPage);
            SimpleForm.Builder form = SimpleForm.builder().title("§l§dSNAPSHOTS: §f" + target.name + " §r§7(" + (page + 1) + "/" + (maxPage + 1) + ")")
                    .content("§7Inventar, Rüstung, Enderchest, Status, Spielmodus und Ort.\n§7Gespeichert: §f" + snapshots.length);
            form.button("§dNeuen Snapshot erstellen", response -> sync(() -> { plugin.createSnapshot(admin, target); openSnapshots(admin, target.uuid, 0); }));
            int start = page * pageSize;
            for (int i = start; i < Math.min(snapshots.length, start + pageSize); i++) {
                File snapshot = snapshots[i]; String name = snapshot.getName();
                form.button("§6" + plugin.readableSnapshotName(name) + "\n§7" + plugin.ageText(snapshot.lastModified()) + " • " + snapshot.length() + " Bytes", response -> sync(() -> openSnapshotOptions(admin, target.uuid, name, page)));
            }
            if (page > 0) form.button("§e◀ Vorherige Seite", response -> sync(() -> openSnapshots(admin, target.uuid, page - 1)));
            form.button("§cZurück zum Spieler", response -> sync(() -> openPlayer(admin, target.uuid)));
            if (page < maxPage) form.button("§eNächste Seite ▶", response -> sync(() -> openSnapshots(admin, target.uuid, page + 1)));
            send(admin, form);
        }

