    private static final class StaffAccess {
        private final boolean allowed;
        private final String group;
        private final String username;
        private final long checkedAt;
        private StaffAccess(boolean allowed, String group, String username, long checkedAt) {
            this.allowed = allowed; this.group = group == null || group.isBlank() ? "Unbekannt" : group;
            this.username = username == null ? "" : username; this.checkedAt = checkedAt;
        }
    }

    private static final class LuckPermsBridge {
        private final SimplexAdminSuite plugin;
        private final Map<UUID, StaffAccess> cache = new ConcurrentHashMap<>();
        private final Map<UUID,Map<String,Boolean>> permissions=new ConcurrentHashMap<>();
        private Object api;
        private boolean available;
        private volatile boolean refreshing;
        private String status;

        private LuckPermsBridge(SimplexAdminSuite plugin) {
            this.plugin = plugin;
            connect();
        }

        private void connect() {
            Plugin dependency = Bukkit.getPluginManager().getPlugin("LuckPerms");
            if (dependency == null) {
                status = "nicht installiert";
                available = false;
                return;
            }
            try {
                ClassLoader loader = dependency.getClass().getClassLoader();
                Class<?> provider = Class.forName("net.luckperms.api.LuckPermsProvider", true, loader);
                api = provider.getMethod("get").invoke(null);
                available = api != null;
                status = available ? "aktiv" : "API nicht verfügbar";
            } catch (Throwable error) {
                Throwable root = rootCause(error);
                available = false;
                status = "Fehler: " + root.getClass().getSimpleName();
                plugin.getLogger().warning("LuckPerms-Integration konnte nicht aktiviert werden: " + root.getMessage());
            }
        }

        private String status() {
            if (refreshing) return status + ", Aktualisierung läuft";
            return status + " (" + cache.size() + " Nutzer im Cache)";
        }

        private StaffAccess access(UUID uuid) { return cache.get(uuid); }

        private void refresh(List<PlayerProfile> profiles) {
            if (!available || refreshing) return;
            refreshing = true;
            List<PlayerProfile> snapshot = new ArrayList<>(profiles);
            long cutoff=System.currentTimeMillis()-60_000L;
            snapshot.removeIf(p->cache.containsKey(p.uuid)&&cache.get(p.uuid).checkedAt>cutoff);
            snapshot.sort(java.util.Comparator.comparingLong(p->cache.containsKey(p.uuid)?cache.get(p.uuid).checkedAt:0L));
            if(snapshot.isEmpty()){refreshing=false;return;}
            int max = Math.max(1, plugin.getConfig().getInt("staff-workspace.luckperms-max-profiles", 500));
            if (snapshot.size() > max) snapshot = new ArrayList<>(snapshot.subList(0, max));
            final List<PlayerProfile> selected = snapshot;
            Bukkit.getScheduler().runTaskAsynchronously(plugin, () -> {
                try {
                    Object userManager = invoke(api, "getUserManager");
                    for (PlayerProfile profile : selected) {
                        try {
                            Object user = invoke(userManager, "getUser", profile.uuid);
                            if (user == null) {
                                Object futureObject = invoke(userManager, "loadUser", profile.uuid);
                                if (futureObject instanceof Future) user = ((Future<?>) futureObject).get(8L, TimeUnit.SECONDS);
                            }
                            if (user == null) continue;
                            Object cachedData = invoke(user, "getCachedData");
                            Object permissionData = invoke(cachedData, "getPermissionData");
                            Object tristate = invoke(permissionData, "checkPermission", "simplexadminsuite.admin");
                            Object allowedObject = invoke(tristate, "asBoolean");
                            boolean allowed = Boolean.TRUE.equals(allowedObject);
                            Map<String,Boolean> resolved=new HashMap<>();for(String node:plugin.adminAccess.nodes())resolved.put(node,Boolean.TRUE.equals(invoke(invoke(permissionData,"checkPermission",node),"asBoolean")));permissions.put(profile.uuid,Map.copyOf(resolved));
                            String group = String.valueOf(invoke(user, "getPrimaryGroup"));
                            Object usernameObject = invokeOptional(user, "getUsername");
                            cache.put(profile.uuid, new StaffAccess(allowed, group, usernameObject == null ? profile.name : String.valueOf(usernameObject), System.currentTimeMillis()));
                        } catch (Throwable ignored) {}
                    }
                    status = "aktiv";
                } catch (Throwable error) {
                    Throwable root = rootCause(error);
                    status = "Abfragefehler: " + root.getClass().getSimpleName();
                } finally {
                    refreshing = false;
                    plugin.runAdminTask( () -> {
                        if (plugin.afk == null) return;
                        for (Player online : Bukkit.getOnlinePlayers()) plugin.afk.refreshDisplay(online);
                    });
                }
            });
        }

        private String decoration(Player player) {
            String prefix = stripFormatting(prefix(player)).trim();
            String suffix = stripFormatting(suffix(player)).trim();
            return (prefix + (prefix.isBlank() || suffix.isBlank() ? "" : " ") + suffix).trim();
        }

        private String prefix(Player player) {
            if (!available || player == null) return "";
            try {
                Object userManager = invoke(api, "getUserManager");
                Object user = invoke(userManager, "getUser", player.getUniqueId());
                if (user == null) return "";
                Object metaData = metaData(user, player);
                Object value = invokeOptional(metaData, "getPrefix");
                if (value != null && !String.valueOf(value).isBlank()) return String.valueOf(value);
                String group = String.valueOf(invoke(user, "getPrimaryGroup"));
                return group == null || group.isBlank() || group.equalsIgnoreCase("default") ? "" : "&7[&f" + group + "&7]";
            } catch (Throwable ignored) { return ""; }
        }

        private String suffix(Player player) {
            if (!available || player == null) return "";
            try {
                Object userManager = invoke(api, "getUserManager");
                Object user = invoke(userManager, "getUser", player.getUniqueId());
                if (user == null) return "";
                Object metaData = metaData(user, player);
                Object value = invokeOptional(metaData, "getSuffix");
                return value == null ? "" : String.valueOf(value);
            } catch (Throwable ignored) { return ""; }
        }

        private Object metaData(Object user, Player player) throws Exception {
            Object cachedData = invoke(user, "getCachedData");
            Object queryOptions = unwrapOptional(invokeOptional(user, "getQueryOptions"));
            if (queryOptions == null) {
                Object contextManager = invokeOptional(api, "getContextManager");
                queryOptions = unwrapOptional(invokeOptional(contextManager, "getQueryOptions", player));
                if (queryOptions == null) queryOptions = unwrapOptional(invokeOptional(contextManager, "getQueryOptions", player.getUniqueId()));
                if (queryOptions == null) queryOptions = unwrapOptional(invokeOptional(contextManager, "getStaticQueryOptions"));
            }
            Object metaData = queryOptions == null ? null : invokeOptional(cachedData, "getMetaData", queryOptions);
            if (metaData == null) metaData = invokeOptional(cachedData, "getMetaData");
            if (metaData == null) throw new NoSuchMethodException("LuckPerms cached metadata is unavailable for the player's query options");
            return metaData;
        }

        private static Object unwrapOptional(Object value) {
            if (value instanceof java.util.Optional) return ((java.util.Optional<?>) value).orElse(null);
            return value;
        }

        private static Object invoke(Object target, String name, Object... args) throws Exception {
            Method method = find(target.getClass(), name, args);
            if (method == null) throw new NoSuchMethodException(target.getClass().getName() + "." + name);
            method.trySetAccessible();
            return method.invoke(target, args);
        }

        private static Object invokeOptional(Object target, String name, Object... args) {
            if (target == null) return null;
            try { return invoke(target, name, args); } catch (Exception ignored) { return null; }
        }

        private static Method find(Class<?> type, String name, Object[] args) {
            for (Method method : type.getMethods()) {
                if (!method.getName().equals(name) || method.getParameterCount() != args.length) continue;
                Class<?>[] parameters = method.getParameterTypes();
                boolean compatible = true;
                for (int i = 0; i < parameters.length; i++) {
                    if (args[i] == null) continue;
                    Class<?> boxed = parameters[i].isPrimitive() ? box(parameters[i]) : parameters[i];
                    if (!boxed.isAssignableFrom(args[i].getClass())) { compatible = false; break; }
                }
                if (compatible) return method;
            }
            return null;
        }

        private static Class<?> box(Class<?> primitive) {
            if (primitive == boolean.class) return Boolean.class;
            if (primitive == int.class) return Integer.class;
            if (primitive == long.class) return Long.class;
            if (primitive == double.class) return Double.class;
            if (primitive == float.class) return Float.class;
            if (primitive == short.class) return Short.class;
            if (primitive == byte.class) return Byte.class;
            if (primitive == char.class) return Character.class;
            return primitive;
        }
    }

    private static final class WatchEntry {
        private final UUID uuid; private final String lastKnownName; private final String reason; private final String addedBy; private final long createdAt;
        private WatchEntry(UUID uuid, String lastKnownName, String reason, String addedBy, long createdAt) { this.uuid=uuid; this.lastKnownName=lastKnownName; this.reason=reason; this.addedBy=addedBy; this.createdAt=createdAt; }
    }

    private static final class WatchlistManager {
        private final SimplexAdminSuite plugin; private final File file; private final Map<UUID, WatchEntry> entries = new ConcurrentHashMap<>();
        private WatchlistManager(SimplexAdminSuite plugin) { this.plugin=plugin; this.file=new File(plugin.getDataFolder(), "watchlist.yml"); reload(); }
        private synchronized void reload() {
            entries.clear(); if (!file.exists()) return;
            YamlConfiguration y=YamlConfiguration.loadConfiguration(file);
            for (Object raw : y.getList("entries")) {
                if (!(raw instanceof Map)) continue; Map<?,?> m=(Map<?,?>)raw;
                try { UUID uuid=UUID.fromString(String.valueOf(m.get("uuid"))); entries.put(uuid,new WatchEntry(uuid,String.valueOf(m.containsKey("name") ? m.get("name") : "Unknown"),String.valueOf(m.containsKey("reason") ? m.get("reason") : "Kein Grund angegeben"),String.valueOf(m.containsKey("added-by") ? m.get("added-by") : "System"),Long.parseLong(String.valueOf(m.containsKey("created-at") ? m.get("created-at") : "0")))); } catch (Exception ignored) { }
            }
        }
        private synchronized void add(String actor, PlayerProfile profile, String reason) { if (profile==null) return; String clean=plugin.sanitizeText(reason,plugin.getConfig().getInt("watchlist.max-reason-length",240)); if(clean.isBlank()) clean="Kein Grund angegeben"; entries.put(profile.uuid,new WatchEntry(profile.uuid,profile.name,clean,actor,System.currentTimeMillis())); save(); plugin.audit.log(actor,profile.uuid,"Watchlist hinzugefügt",clean); }
        private synchronized void remove(String actor, UUID uuid) { if (uuid==null) return; entries.remove(uuid); save(); plugin.audit.log(actor,uuid,"Watchlist entfernt",""); }
        private boolean contains(UUID uuid) { return uuid!=null&&entries.containsKey(uuid); }
        private String reason(UUID uuid) { WatchEntry e=entries.get(uuid); return e==null?"-":e.reason; }
        private int size(){return entries.size();}
        private List<WatchEntry> sorted(){List<WatchEntry> out=new ArrayList<>(entries.values());out.sort(Comparator.comparingLong((WatchEntry e)->e.createdAt).reversed());return out;}
        private void notifyJoin(Player player){notifyStaff(player,"ist dem Server beigetreten");}
        private void notifyQuit(Player player){notifyStaff(player,"hat den Server verlassen");}
        private void notifyStaff(Player player,String event){WatchEntry e=player==null?null:entries.get(player.getUniqueId());if(e==null)return;String text=plugin.color("&8[&eWatchlist&8] &f"+player.getName()+" &7"+event+". &8Grund: &f"+e.reason);for(Player admin:Bukkit.getOnlinePlayers())if(plugin.has(admin,"simplexadminsuite.watchlist")&&(plugin.adminSecurity==null||!plugin.adminSecurity.isLocked(admin)))admin.sendMessage(text);}
        private String summary(){return size()+" Einträge";}
        private synchronized void save(){try{YamlConfiguration y=new YamlConfiguration();List<Map<String,Object>> list=new ArrayList<>();for(WatchEntry e:entries.values()){Map<String,Object> m=new LinkedHashMap<>();m.put("uuid",e.uuid.toString());m.put("name",e.lastKnownName);m.put("reason",e.reason);m.put("added-by",e.addedBy);m.put("created-at",e.createdAt);list.add(m);}y.set("entries",list);saveYamlAtomically(y,file);}catch(Exception error){plugin.getLogger().warning("Watchlist konnte nicht gespeichert werden: "+error.getMessage());}}
    }

    private static final class Announcement {
        private final long id; private final String text; private final int intervalMinutes; private boolean enabled; private final String createdBy; private final long createdAt; private long lastSentAt;
        private Announcement(long id,String text,int intervalMinutes,boolean enabled,String createdBy,long createdAt,long lastSentAt){this.id=id;this.text=text;this.intervalMinutes=intervalMinutes;this.enabled=enabled;this.createdBy=createdBy;this.createdAt=createdAt;this.lastSentAt=lastSentAt;}
    }

    private static final class AnnouncementManager {
        private final SimplexAdminSuite plugin; private final File file; private final Map<Long,Announcement> entries=new ConcurrentHashMap<>(); private final AtomicLong sequence=new AtomicLong(1L); private BukkitTask task;
        private AnnouncementManager(SimplexAdminSuite plugin){this.plugin=plugin;this.file=new File(plugin.getDataFolder(),"announcements.yml");reload();}
        private synchronized void reload(){stop();entries.clear();long max=0L;if(file.exists()){YamlConfiguration y=YamlConfiguration.loadConfiguration(file);for(Object raw:y.getList("entries")){if(!(raw instanceof Map))continue;Map<?,?>m=(Map<?,?>)raw;try{long id=Long.parseLong(String.valueOf(m.get("id")));Announcement a=new Announcement(id,String.valueOf(m.containsKey("text") ? m.get("text") : ""),Integer.parseInt(String.valueOf(m.containsKey("interval-minutes") ? m.get("interval-minutes") : "30")),Boolean.parseBoolean(String.valueOf(m.containsKey("enabled") ? m.get("enabled") : "true")),String.valueOf(m.containsKey("created-by") ? m.get("created-by") : "System"),Long.parseLong(String.valueOf(m.containsKey("created-at") ? m.get("created-at") : "0")),Long.parseLong(String.valueOf(m.containsKey("last-sent-at") ? m.get("last-sent-at") : "0")));if(!a.text.isBlank()){entries.put(id,a);max=Math.max(max,id);}}catch(Exception ignored){}}}sequence.set(max+1L);}
        private synchronized void start(){stop();task=Bukkit.getScheduler().runTaskTimer(plugin,this::tick,1200L,1200L);}
        private synchronized void stop(){if(task!=null){try{task.cancel();}catch(Exception ignored){}task=null;}}
        private void tick(){long now=System.currentTimeMillis();for(Announcement a:sorted()){if(!a.enabled)continue;long interval=Math.max(1,a.intervalMinutes)*60000L;if(a.lastSentAt<=0L||now-a.lastSentAt>=interval)send(a,"Scheduler");}}
        private synchronized Announcement add(String actor,String text,int minutes){String clean=plugin.sanitizeText(text,plugin.getConfig().getInt("announcements.max-length",300));if(clean.isEmpty())return null;int interval=Math.max(1,Math.min(plugin.getConfig().getInt("announcements.max-interval-minutes",1440),minutes));Announcement a=new Announcement(sequence.getAndIncrement(),clean,interval,true,actor,System.currentTimeMillis(),System.currentTimeMillis());entries.put(a.id,a);save();plugin.audit.log(actor,null,"Ankündigung angelegt","#"+a.id+" | "+clean);return a;}
        private synchronized boolean remove(String actor,long id){Announcement old=entries.remove(id);save();if(old!=null)plugin.audit.log(actor,null,"Ankündigung gelöscht","#"+id);return old!=null;}
        private synchronized boolean toggle(String actor,long id){Announcement a=entries.get(id);if(a==null)return false;a.enabled=!a.enabled;save();plugin.audit.log(actor,null,"Ankündigung umgeschaltet","#"+id+" = "+a.enabled);return a.enabled;}
        private boolean sendNow(String actor,long id){Announcement a=entries.get(id);if(a==null)return false;send(a,actor);return true;}
        private synchronized void send(Announcement a,String actor){plugin.broadcastPublicText(plugin.prefix()+stripFormatting(a.text));a.lastSentAt=System.currentTimeMillis();save();plugin.audit.log(actor,null,"Ankündigung gesendet","#"+a.id);}
        private Announcement get(long id){return entries.get(id);} private int size(){return entries.size();}
        private List<Announcement> sorted(){List<Announcement> out=new ArrayList<>(entries.values());out.sort(Comparator.comparingLong(a->a.id));return out;}
        private String summary(){return size()+" Einträge, "+entries.values().stream().filter(a->a.enabled).count()+" aktiv";}
        private synchronized void save(){try{YamlConfiguration y=new YamlConfiguration();List<Map<String,Object>> list=new ArrayList<>();for(Announcement a:sorted()){Map<String,Object>m=new LinkedHashMap<>();m.put("id",a.id);m.put("text",a.text);m.put("interval-minutes",a.intervalMinutes);m.put("enabled",a.enabled);m.put("created-by",a.createdBy);m.put("created-at",a.createdAt);m.put("last-sent-at",a.lastSentAt);list.add(m);}y.set("entries",list);saveYamlAtomically(y,file);}catch(Exception error){plugin.getLogger().warning("Ankündigungen konnten nicht gespeichert werden: "+error.getMessage());}}
    }

    private static final class DutyManager {
        private final SimplexAdminSuite plugin; private final File file; private final Set<UUID> active=Collections.synchronizedSet(new HashSet<>());
        private DutyManager(SimplexAdminSuite plugin){this.plugin=plugin;File folder=new File(plugin.getDataFolder(),"staff-workspace");if(!folder.exists())folder.mkdirs();this.file=new File(folder,"duty.yml");reload();}
        private synchronized void reload(){active.clear();if(!file.exists())return;YamlConfiguration y=YamlConfiguration.loadConfiguration(file);for(String value:y.getStringList("active"))try{active.add(UUID.fromString(value));}catch(Exception ignored){}}
        private boolean active(Player player){return player!=null&&active.contains(player.getUniqueId());}
        private synchronized boolean toggle(Player player){boolean value;if(active.remove(player.getUniqueId()))value=false;else{active.add(player.getUniqueId());value=true;}save();plugin.audit.log(player.getName(),player.getUniqueId(),"Staff-Dienst",value?"aktiviert":"beendet");broadcastStaff("&8[&6Duty&8] &f"+player.getName()+" &7ist jetzt "+(value?"&aim Dienst":"&7außer Dienst")+".");return value;}
        private int activeCount(){int count=0;for(UUID uuid:active)if(Bukkit.getPlayer(uuid)!=null)count++;return count;}
        private void notifyJoin(Player player){if(active(player))broadcastStaff("&8[&6Duty&8] &f"+player.getName()+" &7ist im Staff-Dienst wieder online.");}
        private void notifyQuit(Player player){if(active(player))broadcastStaff("&8[&6Duty&8] &f"+player.getName()+" &7ist im Staff-Dienst offline gegangen.");}
        private void broadcastStaff(String message){String formatted=plugin.color(message);for(Player admin:Bukkit.getOnlinePlayers())if(plugin.has(admin,"simplexadminsuite.duty")&&(plugin.adminSecurity==null||!plugin.adminSecurity.isLocked(admin)))admin.sendMessage(formatted);}
        private String summary(){return activeCount()+" Staff online im Dienst";}
        private synchronized void save(){try{YamlConfiguration y=new YamlConfiguration();y.set("active",active.stream().map(UUID::toString).collect(Collectors.toList()));saveYamlAtomically(y,file);}catch(Exception error){plugin.getLogger().warning("Duty-Status konnte nicht gespeichert werden: "+error.getMessage());}}
    }

    private static final class DiscordStatusManager {
        private enum Mode { ONLINE, RESTARTING, SHUTTING_DOWN }

        private final SimplexAdminSuite plugin;
        private final File stateFile;
        private final ExecutorService executor;
        private final HttpClient http;
        private final DiscordDiagnostics diagnostics;
        private BukkitTask task;
        private String messageId = "";
        private String webhookFingerprint = "";
        private volatile String lastError = "";
        private volatile long lastSuccess;
        private volatile Mode mode = Mode.ONLINE;
        private volatile int restartSeconds;
        private volatile boolean stopped;
        private volatile ServerStatistics.Live worldLive;

        private DiscordStatusManager(SimplexAdminSuite plugin) {
            this.plugin = plugin;
            this.diagnostics = new DiscordDiagnostics(plugin.getLogger()::warning);
            this.stateFile = new File(plugin.getDataFolder(), "discord-status-state.yml");
            this.executor = Executors.newSingleThreadExecutor(runnable -> {
                Thread thread = new Thread(runnable, "SimplexAdminSuite-DiscordStatus");
                thread.setDaemon(true);
                return thread;
            });
            this.http = HttpClient.newBuilder()
                    .connectTimeout(java.time.Duration.ofSeconds(4))
                    .build();
            loadState();
        }

        private synchronized void start() {
            cancelTask();
            stopped = false;
            mode = Mode.ONLINE;
            restartSeconds = 0;
            if (!enabled()) return;
            int seconds = Math.max(15, Math.min(300, plugin.getConfig().getInt("discord-status.update-interval-seconds", 15)));
            task = Bukkit.getScheduler().runTaskTimer(plugin, this::updateNow, 20L, seconds * 20L);
            updateNow();
        }

        private synchronized void reload() {
            cancelTask();
            loadState();
            start();
        }

        private synchronized void stop(boolean restarting) {
            cancelTask();
            stopped = true;
            if (!enabled()) {
                executor.shutdownNow();
                return;
            }
            mode = restarting ? Mode.RESTARTING : Mode.SHUTTING_DOWN;
            restartSeconds = 0;
            StatusSnapshot snapshot = captureSnapshot();
            String webhook = plugin.getConfig().getString("discord-status.webhook-url", "").trim();
            String body = payload(snapshot);
            // Discard queued live snapshots so the final restart/shutdown state cannot be
            // overwritten by an older asynchronous update during server shutdown.
            executor.shutdownNow();
            try { executor.awaitTermination(750L, TimeUnit.MILLISECONDS); }
            catch (InterruptedException interrupted) { Thread.currentThread().interrupt(); }
            publish(webhook, body);
        }

        private synchronized void cancelTask() {
            if (task != null) {
                try { task.cancel(); } catch (Exception ignored) { }
                task = null;
            }
        }

        private boolean enabled() {
            return plugin.getConfig().getBoolean("discord-status.enabled", false)
                    && validWebhook(plugin.getConfig().getString("discord-status.webhook-url", ""));
        }

        private synchronized void setEnabled(String actor, boolean value) {
            plugin.getConfig().set("discord-status.enabled", value);
            plugin.saveConfig();
            plugin.audit.log(actor, null, "Discord-Status", value ? "aktiviert" : "deaktiviert");
            if (value) start(); else cancelTask();
        }

        private synchronized boolean setWebhook(String actor, String value) {
            String url = value == null ? "" : value.trim();
            if (!validWebhook(url)) return false;
            String newFingerprint = fingerprint(url);
            plugin.getConfig().set("discord-status.webhook-url", url);
            plugin.getConfig().set("discord-status.enabled", true);
            plugin.saveConfig();
            if (!newFingerprint.equals(webhookFingerprint)) {
                messageId = "";
                webhookFingerprint = newFingerprint;
                saveState();
            }
            plugin.audit.log(actor, null, "Discord-Status-Webhook gesetzt", "Webhook sicher aktualisiert; Token nicht protokolliert");
            start();
            return true;
        }

        private synchronized void resetMessage(String actor) {
            messageId = "";
            webhookFingerprint = fingerprint(plugin.getConfig().getString("discord-status.webhook-url", ""));
            saveState();
            plugin.audit.log(actor, null, "Discord-Status-Nachricht zurückgesetzt", "Neue Statusnachricht wird erstellt");
            updateNow();
        }

        private synchronized void toggleDisplay(String actor, String key) {
            String path = "discord-status.display." + key;
            boolean value = !plugin.getConfig().getBoolean(path, true);
            plugin.getConfig().set(path, value);
            plugin.saveConfig();
            plugin.audit.log(actor, null, "Discord-Status-Anzeige", key + " = " + value);
            updateNow();
        }

        private synchronized void markRestarting(String actor, int seconds) {
            mode = Mode.RESTARTING;
            restartSeconds = Math.max(0, seconds);
            plugin.audit.log(actor, null, "Discord-Status Neustartmodus", seconds + " Sekunden");
            updateNow();
        }

        private synchronized void markRestartCountdown(int seconds) {
            mode = Mode.RESTARTING;
            restartSeconds = Math.max(0, seconds);
        }

        private synchronized void markRestartingNow() {
            mode = Mode.RESTARTING;
            restartSeconds = 0;
            updateNow();
        }

        private void updateNow() {
            if (!enabled() || stopped) return;
            StatusSnapshot snapshot = captureSnapshot();
            String webhook = plugin.getConfig().getString("discord-status.webhook-url", "").trim();
            String body = payload(snapshot);
            try {
                executor.execute(() -> publish(webhook, body));
            } catch (Exception ignored) { }
        }

        private synchronized String summary() {
            if (!plugin.getConfig().getBoolean("discord-status.enabled", false)) return "Deaktiviert";
            if (!validWebhook(plugin.getConfig().getString("discord-status.webhook-url", ""))) return "Webhook fehlt oder ist ungültig";
            if (!lastError.isBlank()) return "Fehler: " + plugin.sanitizeText(lastError, 70);
            if (lastSuccess > 0L) return "Aktiv • zuletzt " + plugin.time(lastSuccess) + (messageId.isBlank() ? "" : " • Nachricht vorhanden");
            return "Aktiv • wartet auf erste Aktualisierung";
        }

        private synchronized String messageIdMasked() {
            if (messageId == null || messageId.isBlank()) return "Noch keine";
            return messageId.length() <= 8 ? messageId : "…" + messageId.substring(messageId.length() - 8);
        }

        private StatusSnapshot captureSnapshot() {
            worldLive=plugin.statisticsLive();
            List<String> names = new ArrayList<>();
            for (Player player : plugin.onlinePlayersSorted()) {
                if (!hidden(player)) names.add(player.getName() + (plugin.expansionIsAfk(player) ? " 💤 AFK" : ""));
            }
            int visibleCount = names.size();
            int maxNames = Math.max(1, Math.min(80, plugin.getConfig().getInt("discord-status.display.max-player-names", 30)));
            int omitted = Math.max(0, names.size() - maxNames);
            if (names.size() > maxNames) names = new ArrayList<>(names.subList(0, maxNames));

            double[] tps = tps();
            double mspt = mspt();
            Runtime runtime = Runtime.getRuntime();
            long used = runtime.totalMemory() - runtime.freeMemory();
            long max = runtime.maxMemory();
            double cpu = cpuLoad();
            long loadedChunks = 0L;
            int worldCount = 0;
            Object worldsRaw = invokeBukkit("getWorlds");
            if (worldsRaw instanceof Collection) {
                Collection<?> worlds = (Collection<?>) worldsRaw;
                worldCount = worlds.size();
                for (Object world : worlds) {
                    try {
                        Object chunks = world.getClass().getMethod("getLoadedChunks").invoke(world);
                        if (chunks != null && chunks.getClass().isArray()) loadedChunks += java.lang.reflect.Array.getLength(chunks);
                    } catch (Throwable ignored) { }
                }
            }
            int maxPlayers = number(invokeBukkit("getMaxPlayers"), 0);
            String version = String.valueOf(valueOr(invokeBukkit("getVersion"), "Paper"));

            Mode currentMode = mode;
            int seconds = restartSeconds;
            WorldTrimManager.TrimStatus trim = plugin.worldTrimStatus();
            return new StatusSnapshot(currentMode, seconds, names, visibleCount, omitted, maxPlayers, tps, mspt,
                    used, max, cpu, ManagementFactory.getRuntimeMXBean().getUptime(), worldCount,
                    loadedChunks, version, trim, Instant.now().toString());
        }

        private boolean hidden(Player player) {
            if (player == null) return true;
            if (plugin.adminSpy != null && plugin.adminSpy.hiddenTab(player)) return true;
            try {
                Object has = player.getClass().getMethod("hasMetadata", String.class).invoke(player, "vanished");
                if (Boolean.TRUE.equals(has)) {
                    Object values = player.getClass().getMethod("getMetadata", String.class).invoke(player, "vanished");
                    if (values instanceof Collection) {
                        for (Object value : (Collection<?>) values) {
                            Object hidden = value.getClass().getMethod("asBoolean").invoke(value);
                            if (Boolean.TRUE.equals(hidden)) return true;
                        }
                    }
                }
            } catch (Throwable ignored) { }
            return false;
        }

        private double[] tps() {
            try {
                Method method = Bukkit.class.getMethod("getTPS");
                Object raw = method.invoke(null);
                if (raw instanceof double[]) {
                    double[] values = (double[]) raw;
                    if (values.length >= 3) return new double[]{values[0], values[1], values[2]};
                }
            } catch (Throwable ignored) { }
            try {
                Object server = invokeBukkit("getServer");
                if (server == null) throw new IllegalStateException("server unavailable");
                Method method = server.getClass().getMethod("getTPS");
                Object raw = method.invoke(server);
                if (raw instanceof double[]) {
                    double[] values = (double[]) raw;
                    if (values.length >= 3) return new double[]{values[0], values[1], values[2]};
                }
            } catch (Throwable ignored) { }
            return new double[]{-1D, -1D, -1D};
        }

        private double mspt() {
            try {
                Method method = Bukkit.class.getMethod("getAverageTickTime");
                Object raw = method.invoke(null);
                if (raw instanceof Number) return ((Number) raw).doubleValue();
            } catch (Throwable ignored) { }
            try {
                Object server = invokeBukkit("getServer");
                if (server == null) throw new IllegalStateException("server unavailable");
                Method method = server.getClass().getMethod("getAverageTickTime");
                Object raw = method.invoke(server);
                if (raw instanceof Number) return ((Number) raw).doubleValue();
            } catch (Throwable ignored) { }
            return -1D;
        }

        private double cpuLoad() {
            try {
                Object bean = ManagementFactory.getOperatingSystemMXBean();
                Method method;
                try { method = bean.getClass().getMethod("getProcessCpuLoad"); }
                catch (NoSuchMethodException ignored) { method = bean.getClass().getMethod("getCpuLoad"); }
                method.setAccessible(true);
                Object raw = method.invoke(bean);
                if (raw instanceof Number) {
                    double value = ((Number) raw).doubleValue();
                    return value < 0D ? -1D : Math.min(100D, value * 100D);
                }
            } catch (Throwable ignored) { }
            return -1D;
        }

        private void publish(String webhook, String payload) {
            if (!validWebhook(webhook)) return;
            String currentFingerprint = fingerprint(webhook);
            synchronized (this) {
                if (!currentFingerprint.equals(webhookFingerprint)) {
                    webhookFingerprint = currentFingerprint;
                    messageId = "";
                    saveState();
                }
            }
            try {
                String currentId;
                synchronized (this) { currentId = messageId; }
                if (!currentId.isBlank()) {
                    HttpResponse<String> response = request("PATCH", messageUrl(webhook, currentId), payload, 5);
                    if (response.statusCode() >= 200 && response.statusCode() < 300) {
                        success();
                        return;
                    }
                    if (response.statusCode() == 404) {
                        synchronized (this) { messageId = ""; saveState(); }
                    } else {
                        fail("Discord HTTP " + response.statusCode());
                        return;
                    }
                }
                HttpResponse<String> response = request("POST", appendQuery(webhook, "wait=true"), payload, 5);
                if (response.statusCode() >= 200 && response.statusCode() < 300) {
                    Matcher matcher = Pattern.compile("\\\"id\\\"\\s*:\\s*\\\"([0-9]+)\\\"").matcher(response.body());
                    if (matcher.find()) {
                        synchronized (this) {
                            messageId = matcher.group(1);
                            webhookFingerprint = currentFingerprint;
                            saveState();
                        }
                    }
                    success();
                } else fail("Discord HTTP " + response.statusCode());
            } catch (Exception error) {
                fail(error.getClass().getSimpleName());
            }
        }

        private HttpResponse<String> request(String method, String url, String payload, int timeoutSeconds) throws Exception {
            HttpRequest request = HttpRequest.newBuilder(URI.create(url))
                    .timeout(java.time.Duration.ofSeconds(timeoutSeconds))
                    .header("Content-Type", "application/json; charset=utf-8")
                    .method(method, HttpRequest.BodyPublishers.ofString(payload, StandardCharsets.UTF_8))
                    .build();
            try{
                HttpResponse<String> response=http.send(request,HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
                if(response.statusCode()/100!=2)diagnostics.failure("legacy status webhook "+method,"HTTP "+response.statusCode()+" • "+DiscordDiagnostics.detail(response.body(),""));
                return response;
            }catch(Exception error){diagnostics.failure("legacy status webhook "+method,error.getClass().getSimpleName());throw error;}
        }

        private String payload(StatusSnapshot snapshot) {
            String username = plugin.getConfig().getString("discord-status.username", "Simplex SMP Status");
            String avatar = plugin.getConfig().getString("discord-status.avatar-url", "");
            String serverName = plugin.getConfig().getString("discord-status.server-name", "Simplex SMP");
            String title;
            String description;
            int color;
            if (snapshot.mode == Mode.RESTARTING) {
                title = plugin.getConfig().getString("discord-status.text.restarting-title", "Server is restarting");
                description = plugin.getConfig().getString("discord-status.text.restarting-description", "The server is restarting. Players can reconnect shortly.");
                if (snapshot.restartSeconds > 0) description += " Restarting in **" + snapshot.restartSeconds + " seconds**.";
                color = 16705372;
            } else if (snapshot.mode == Mode.SHUTTING_DOWN) {
                title = plugin.getConfig().getString("discord-status.text.shutting-down-title", "Server is shutting down");
                description = plugin.getConfig().getString("discord-status.text.shutting-down-description", "The server is currently offline or shutting down.");
                color = 16705372;
            } else {
                title = plugin.getConfig().getString("discord-status.text.online-title", "Live Server Status");
                description = plugin.getConfig().getString("discord-status.text.online-description", "The server is online and accepting players.");
                color = 5763719;
            }
            if(snapshot.mode==Mode.ONLINE&&plugin.qolMaintenanceActive()){
                title="Server maintenance";description="The server is currently in maintenance mode. Please try again later.";color=16705372;
            }
            if (snapshot.mode == Mode.ONLINE && snapshot.trim.phase == WorldTrimManager.Phase.RUNNING) {
                title = "World trimming in progress";
                description = "The server is locked while world files are being optimized. Progress: **" + snapshot.trim.progress
                        + "%**. Estimated time remaining: **" + snapshot.trim.eta + "**.";
                color = 10181046;
            } else if (snapshot.mode == Mode.ONLINE && snapshot.trim.phase == WorldTrimManager.Phase.COUNTDOWN) {
                title = "World maintenance scheduled";
                description = "World trimming starts in **" + snapshot.trim.countdownSeconds + " seconds**.";
                color = 16705372;
            } else if (snapshot.mode == Mode.ONLINE && snapshot.trim.phase == WorldTrimManager.Phase.AWAITING_OVERRIDE) {
                title = "World trim safety decision required";
                description = "No region files are being modified. The server is locked while the initiating operator reviews the loaded-chunk emergency override.";
                color = 16705372;
            } else if (snapshot.mode == Mode.ONLINE && snapshot.trim.phase == WorldTrimManager.Phase.RECOVERY) {
                title = "World trim recovery required";
                description = "Normal joins are restricted until a server operator completes the safety check.";
                color = 15548997;
            }

            List<String[]> fields = new ArrayList<>();
            fields.add(new String[]{"Players", "**" + snapshot.visibleCount + " / " + snapshot.maxPlayers + "** visible online", "true"});
            if (plugin.getConfig().getBoolean("discord-status.display.player-list", true)) {
                String players = snapshot.names.isEmpty() ? "No visible players online" : String.join("\n", snapshot.names);
                if (snapshot.omitted > 0) players += "\n…and " + snapshot.omitted + " more";
                fields.add(new String[]{"Online players", truncate(players, 1024), "false"});
            }
            if (plugin.getConfig().getBoolean("discord-status.display.tps", true)) {
                fields.add(new String[]{"TPS (1m / 5m / 15m)", formatTps(snapshot.tps), "true"});
            }
            if (plugin.getConfig().getBoolean("discord-status.display.mspt", true)) {
                fields.add(new String[]{"MSPT", snapshot.mspt < 0D ? "Unavailable" : String.format(Locale.US, "%.2f ms", snapshot.mspt), "true"});
            }
            if (plugin.getConfig().getBoolean("discord-status.display.memory", true)) {
                fields.add(new String[]{"Memory", ServerStatistics.bar(snapshot.maxMemory>0?(double)snapshot.usedMemory/snapshot.maxMemory:-1)+"\n"+formatBytes(snapshot.usedMemory) + " / " + formatBytes(snapshot.maxMemory), "true"});
            }
            if (plugin.getConfig().getBoolean("discord-status.display.cpu", true)) {
                fields.add(new String[]{"Process CPU", ServerStatistics.bar(snapshot.cpu<0?-1:snapshot.cpu/100), "true"});
            }
            if (plugin.getConfig().getBoolean("discord-status.display.uptime", true)) {
                fields.add(new String[]{"Uptime", formatUptime(snapshot.uptime), "true"});
            }
            if (plugin.getConfig().getBoolean("discord-status.display.worlds", true)) {
                fields.add(new String[]{"Worlds", snapshot.worlds + " loaded • " + snapshot.loadedChunks + " chunks", "true"});
            }
            if (plugin.getConfig().getBoolean("discord-status.display.server-version", true)) {
                fields.add(new String[]{"Server software", truncate(snapshot.version, 1024), "false"});
            }
            if (snapshot.trim.active()) {
                String value = "State: **" + snapshot.trim.phase.name().toLowerCase(Locale.ROOT) + "**";
                if (snapshot.trim.phase == WorldTrimManager.Phase.RUNNING) value += "\nProgress: **" + snapshot.trim.progress + "%**\nETA: **" + snapshot.trim.eta + "**";
                fields.add(new String[]{"World maintenance", truncate(value, 1024), "false"});
            }

            if(worldLive!=null)fields.add(new String[]{"Main Overworld", "**"+worldLive.days()+" In-game days** • "+worldLive.phase()+" • "+worldLive.clock(),"false"});
            title=truncate(title,256);description=truncate(description,2400);serverName=truncate(serverName,100);username=truncate(username,80);
            int budget=title.length()+description.length()+serverName.length()+100;
            java.util.Iterator<String[]> fieldIterator=fields.iterator();while(fieldIterator.hasNext()){String[] f=fieldIterator.next();f[0]=truncate(f[0],256);int available=Math.min(1024,5900-budget-f[0].length());if(available<1){fieldIterator.remove();continue;}f[1]=truncate(f[1],available);budget+=f[0].length()+f[1].length();}
            StringBuilder json = new StringBuilder(2048);
            json.append('{');
            json.append("\"username\":\"").append(json(username)).append("\",");
            if (avatar != null && !avatar.isBlank()) json.append("\"avatar_url\":\"").append(json(avatar)).append("\",");
            json.append("\"allowed_mentions\":{\"parse\":[]},");
            json.append("\"embeds\":[{");
            json.append("\"author\":{\"name\":\"").append(json(serverName)).append("\"},");
            json.append("\"title\":\"").append(json(title)).append("\",");
            json.append("\"description\":\"").append(json(description)).append("\",");
            json.append("\"color\":").append(color).append(',');
            json.append("\"fields\":[");
            for (int i = 0; i < fields.size(); i++) {
                if (i > 0) json.append(',');
                String[] field = fields.get(i);
                json.append("{\"name\":\"").append(json(field[0])).append("\",\"value\":\"")
                        .append(json(field[1])).append("\",\"inline\":").append(field[2]).append('}');
            }
            json.append("],");
            json.append("\"footer\":{\"text\":\"Live status • updates every ")
                    .append(Math.max(15, plugin.getConfig().getInt("discord-status.update-interval-seconds", 15)))
                    .append(" seconds\"},");
            json.append("\"timestamp\":\"").append(json(snapshot.timestamp)).append("\"");
            json.append("}]}");
            return json.toString();
        }

        private Object invokeBukkit(String method) {
            try { return Bukkit.class.getMethod(method).invoke(null); }
            catch (Throwable ignored) { return null; }
        }

        private Object valueOr(Object value, Object fallback) { return value == null ? fallback : value; }

        private int number(Object value, int fallback) {
            return value instanceof Number ? ((Number) value).intValue() : fallback;
        }

        private String formatTps(double[] values) {
            if (values == null || values.length < 3 || values[0] < 0D) return "Unavailable";
            return String.format(Locale.US, "%.2f / %.2f / %.2f", Math.min(20D, values[0]), Math.min(20D, values[1]), Math.min(20D, values[2]));
        }

        private String formatBytes(long bytes) {
            return String.format(Locale.US, "%.2f GiB", bytes / 1073741824D);
        }

        private String formatUptime(long millis) {
            long seconds = Math.max(0L, millis / 1000L);
            long days = seconds / 86400L; seconds %= 86400L;
            long hours = seconds / 3600L; seconds %= 3600L;
            long minutes = seconds / 60L;
            if (days > 0) return days + "d " + hours + "h " + minutes + "m";
            if (hours > 0) return hours + "h " + minutes + "m";
            return minutes + "m";
        }

        private synchronized void success() {
            lastSuccess = System.currentTimeMillis();
            lastError = "";
            saveState();
        }

        private synchronized void fail(String error) {
            lastError = plugin.sanitizeText(error, 180);
            saveState();
        }

        private synchronized void loadState() {
            messageId = "";
            webhookFingerprint = "";
            lastError = "";
            lastSuccess = 0L;
            if (!stateFile.exists()) return;
            YamlConfiguration yaml = YamlConfiguration.loadConfiguration(stateFile);
            messageId = yaml.getString("message-id", "");
            webhookFingerprint = yaml.getString("webhook-fingerprint", "");
            lastSuccess = yaml.getLong("last-success", 0L);
            lastError = yaml.getString("last-error", "");
            String configured = fingerprint(plugin.getConfig().getString("discord-status.webhook-url", ""));
            if (!configured.equals(webhookFingerprint)) {
                messageId = "";
                webhookFingerprint = configured;
            }
        }

        private synchronized void saveState() {
            try {
                YamlConfiguration yaml = new YamlConfiguration();
                yaml.set("message-id", messageId);
                yaml.set("webhook-fingerprint", webhookFingerprint);
                yaml.set("last-success", lastSuccess);
                yaml.set("last-error", lastError);
                saveYamlAtomically(yaml, stateFile);
            } catch (Exception error) {
                plugin.getLogger().warning("Discord-Statuszustand konnte nicht gespeichert werden: " + error.getMessage());
            }
        }

        private boolean validWebhook(String value) {
            if (value == null) return false;
            String url = value.trim().toLowerCase(Locale.ROOT);
            return (url.startsWith("https://discord.com/api/webhooks/")
                    || url.startsWith("https://discordapp.com/api/webhooks/")
                    || url.startsWith("https://canary.discord.com/api/webhooks/"))
                    && value.split("/", -1).length >= 7;
        }

        private String messageUrl(String webhook, String id) {
            int query = webhook.indexOf('?');
            String base = query < 0 ? webhook : webhook.substring(0, query);
            String suffix = query < 0 ? "" : webhook.substring(query);
            return base.replaceAll("/+$", "") + "/messages/" + id + suffix;
        }

        private String appendQuery(String url, String query) {
            return url + (url.contains("?") ? "&" : "?") + query;
        }

        private String fingerprint(String value) {
            if (value == null || value.isBlank()) return "";
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.trim().getBytes(StandardCharsets.UTF_8));
                StringBuilder out = new StringBuilder();
                for (byte b : digest) out.append(String.format(Locale.ROOT, "%02x", b));
                return out.toString();
            } catch (Exception ignored) { return Integer.toHexString(value.hashCode()); }
        }

        private String json(String value) {
            if (value == null) return "";
            return value.replace("\\", "\\\\").replace("\"", "\\\"")
                    .replace("\n", "\\n").replace("\r", "");
        }

        private String truncate(String value, int max) {
            if (value == null) return "";
            return value.length() <= max ? value : value.substring(0, Math.max(0, max - 1)) + "…";
        }

        private static final class StatusSnapshot {
            private final Mode mode;
            private final int restartSeconds;
            private final List<String> names;
            private final int visibleCount;
            private final int omitted;
            private final int maxPlayers;
            private final double[] tps;
            private final double mspt;
            private final long usedMemory;
            private final long maxMemory;
            private final double cpu;
            private final long uptime;
            private final int worlds;
            private final long loadedChunks;
            private final String version;
            private final WorldTrimManager.TrimStatus trim;
            private final String timestamp;

            private StatusSnapshot(Mode mode, int restartSeconds, List<String> names, int visibleCount, int omitted, int maxPlayers,
                                   double[] tps, double mspt, long usedMemory, long maxMemory, double cpu, long uptime,
                                   int worlds, long loadedChunks, String version, WorldTrimManager.TrimStatus trim, String timestamp) {
                this.mode = mode;
                this.restartSeconds = restartSeconds;
                this.names = names;
                this.visibleCount = visibleCount;
                this.omitted = omitted;
                this.maxPlayers = maxPlayers;
                this.tps = tps;
                this.mspt = mspt;
                this.usedMemory = usedMemory;
                this.maxMemory = maxMemory;
                this.cpu = cpu;
                this.uptime = uptime;
                this.worlds = worlds;
                this.loadedChunks = loadedChunks;
                this.version = version;
                this.trim = trim;
                this.timestamp = timestamp;
            }
        }
    }

    private static final class RestartManager {
        private final SimplexAdminSuite plugin;
        private BukkitTask task;
        private int remainingSeconds;
        private String initiatedBy = "System";
        private boolean restartIssued;
        private String reasonDE="",reasonEN="";
        private boolean localized;

        private RestartManager(SimplexAdminSuite plugin) { this.plugin = plugin; }

        private synchronized boolean active() { return task != null; }
        private synchronized int remainingSeconds() { return Math.max(0, remainingSeconds); }
        private synchronized boolean restartIssued() { return restartIssued; }

        private synchronized boolean schedule(String actor) {
            return schedule(actor, plugin.getConfig().getInt("operations.restart.countdown-seconds", 30));
        }

        private synchronized boolean schedule(String actor, int requestedSeconds) {
            if (task != null) return false;
            initiatedBy = actor == null || actor.isBlank() ? "System" : plugin.sanitizeText(actor, 80);
            restartIssued = false;
            remainingSeconds = Math.max(1, Math.min(60, requestedSeconds));
            announce(remainingSeconds, true);
            if (plugin.discordStatus != null) plugin.discordStatus.markRestarting(initiatedBy, remainingSeconds);
            if (plugin.discordBot != null) plugin.discordBot.markRestarting(remainingSeconds);
            plugin.audit.log(initiatedBy, null, "Server-Neustart geplant", remainingSeconds + " Sekunden");
            task = Bukkit.getScheduler().runTaskTimer(plugin, this::tick, 20L, 20L);
            return true;
        }

        private synchronized boolean cancel(String actor) {
            if (task == null) return false;
            BukkitTask activeTask = task;
            task = null;
            try { activeTask.cancel(); } catch (Throwable ignored) { }
            int cancelledAt = remainingSeconds;
            remainingSeconds = 0;
            restartIssued = false;
            String cancelledBy = actor == null || actor.isBlank() ? "System" : plugin.sanitizeText(actor, 80);
            for(Player player:Bukkit.getOnlinePlayers()){player.sendMessage(plugin.playerText(player,"§aDer geplante Serverneustart wurde abgebrochen.","§aThe scheduled server restart was cancelled."));player.playSound(player.getLocation(),"block.note_block.chime",0.6f,1.2f);}
            localized=false;reasonDE="";reasonEN="";
            if (plugin.discordBot != null) plugin.discordBot.clearRestarting();
            if (plugin.discordStatus != null) plugin.discordStatus.updateNow();
            plugin.audit.log(cancelledBy, null, "Server-Neustart abgebrochen", "Verbleibend: " + cancelledAt + " Sekunden");
            return true;
        }

        private synchronized void immediate(String actor) {
            initiatedBy = actor == null || actor.isBlank() ? "Welten-Trimmer" : plugin.sanitizeText(actor, 80);
            BukkitTask activeTask = task;
            task = null;
            if (activeTask != null) try { activeTask.cancel(); } catch (Throwable ignored) { }
            remainingSeconds = 0;
            restartIssued = true;
            if (plugin.discordStatus != null) plugin.discordStatus.markRestartingNow();
            if (plugin.discordBot != null) plugin.discordBot.markRestarting(0);
            plugin.audit.log(initiatedBy, null, "Server-Neustart nach Welten-Trimming", "Sicherer Lauf abgeschlossen");
            boolean dispatched = Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "restart");
            if (!dispatched) {
                plugin.getLogger().warning("Der Paper-Befehl 'restart' war nicht verfügbar; nach dem Trimmen wird 'stop' verwendet.");
                Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "stop");
            }
        }

        private synchronized void tick() {
            if (task == null) return;
            remainingSeconds--;
            if (plugin.discordStatus != null) plugin.discordStatus.markRestartCountdown(remainingSeconds);
            if (plugin.discordBot != null) plugin.discordBot.markRestarting(remainingSeconds);
            if (remainingSeconds <= 0) {
                BukkitTask current = task;
                task = null;
                try { current.cancel(); } catch (Exception ignored) { }
                announceNow();
                restartIssued = true;
                if (plugin.discordStatus != null) plugin.discordStatus.markRestartingNow();
                if (plugin.discordBot != null) plugin.discordBot.markRestarting(0);
                plugin.audit.log(initiatedBy, null, "Server-Neustart ausgeführt", "Countdown abgeschlossen");
                boolean dispatched = Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "restart");
                if (!dispatched) {
                    plugin.getLogger().warning("Der Paper-/Spigot-Befehl 'restart' war nicht verfügbar; als sicherer Fallback wird 'stop' ausgeführt.");
                    Bukkit.dispatchCommand(Bukkit.getConsoleSender(), "stop");
                }
                return;
            }
            announce(remainingSeconds, false);
        }

        private void announce(int seconds, boolean initial) {
            if(localized){
                for(Player player:Bukkit.getOnlinePlayers()){
                    String reason=plugin.playerText(player,reasonDE.isBlank()?reasonEN:reasonDE,reasonEN.isBlank()?reasonDE:reasonEN);
                    String message=plugin.playerText(player,"Serverneustart in "+seconds+" Sekunden.","Server restart in "+seconds+" seconds.")+(reason.isBlank()?"":" "+reason);
                    if(initial||seconds<=10||seconds%10==0){player.sendMessage(message);player.playSound(player.getLocation(),"block.note_block.pling",0.6f,seconds<=5?1.5f:1f);}
                    showOverlay(player,plugin.playerText(player,"SERVERNEUSTART","SERVER RESTART"),message);
                }return;
            }
            String fallback = initial
                    ? "Server restart scheduled by staff. Restarting in {seconds} seconds."
                    : "Server restarting in {seconds} seconds.";
            String path = initial ? "operations.restart.start-message" : "operations.restart.countdown-message";
            String text = plugin.getConfig().getString(path, fallback).replace("{seconds}", Integer.toString(seconds));
            if (initial || seconds <= 10 || seconds == 15 || seconds % 10 == 0) {
                plugin.broadcastPublicText(plugin.prefix() + stripFormatting(text));
            }
            String title = plugin.getConfig().getString("operations.restart.title", "SERVER RESTART");
            String subtitle = plugin.getConfig().getString("operations.restart.subtitle", "Restarting in {seconds} seconds")
                    .replace("{seconds}", Integer.toString(seconds));
            for (Player player : Bukkit.getOnlinePlayers()) showOverlay(player, title, subtitle);
        }

        private void announceNow() {
            if(localized){for(Player player:Bukkit.getOnlinePlayers()){String text=plugin.playerText(player,"Der Server startet jetzt neu. Bitte gleich wieder verbinden.","The server is restarting now. Please reconnect shortly.");player.sendMessage(text);showOverlay(player,plugin.playerText(player,"NEUSTART","RESTARTING"),text);}return;}
            String text = plugin.getConfig().getString("operations.restart.now-message",
                    "Server is restarting now. Please reconnect shortly.");
            plugin.broadcastPublicText(plugin.prefix() + stripFormatting(text));
            String title = plugin.getConfig().getString("operations.restart.now-title", "RESTARTING NOW");
            String subtitle = plugin.getConfig().getString("operations.restart.now-subtitle", "Please reconnect shortly");
            for (Player player : Bukkit.getOnlinePlayers()) showOverlay(player, title, subtitle);
        }

        private void showOverlay(Player player, String title, String subtitle) {
            if (player == null) return;
            String cleanTitle = plugin.playerUiText(player,stripFormatting(title));
            String cleanSubtitle = plugin.playerUiText(player,stripFormatting(subtitle));
            try {
                player.getClass().getMethod("sendTitle", String.class, String.class, int.class, int.class, int.class)
                        .invoke(player, cleanTitle, cleanSubtitle, 0, 25, 5);
            } catch (Throwable ignored) { }
            String actionBar = cleanTitle + " • " + cleanSubtitle;
            if(plugin.adminRuntime!=null)actionBar=plugin.adminRuntime.decorateBar(player,actionBar);
            try {
                player.getClass().getMethod("sendActionBar", String.class).invoke(player, actionBar);
                return;
            } catch (Throwable ignored) { }
            try {
                Class<?> component = Class.forName("net.kyori.adventure.text.Component");
                Object value = component.getMethod("text", String.class).invoke(null, actionBar);
                player.getClass().getMethod("sendActionBar", component).invoke(player, value);
            } catch (Throwable ignored) { }
        }

        private synchronized void stop() {
            if (task != null) {
                try { task.cancel(); } catch (Exception ignored) { }
                task = null;
            }
            remainingSeconds = 0;
        }
    }

    private static final class ServerControlManager {
        private final SimplexAdminSuite plugin;
        private final File file;
        private boolean globalChatEnabled = true;
        private String changedBy = "System";
        private long changedAt;
        private int slowmodeSeconds;
        private boolean commandLockdown;
        private final Map<UUID, Long> lastChatAt = new ConcurrentHashMap<>();

        private ServerControlManager(SimplexAdminSuite plugin) {
            this.plugin = plugin;
            this.file = new File(plugin.getDataFolder(), "server-controls.yml");
            reload();
        }

        private synchronized void reload() {
            if (!file.exists()) { save(); return; }
            YamlConfiguration y = YamlConfiguration.loadConfiguration(file);
            globalChatEnabled = y.getBoolean("global-chat.enabled", true);
            changedBy = y.getString("global-chat.changed-by", "System");
            changedAt = y.getLong("global-chat.changed-at", 0L);
            slowmodeSeconds = Math.max(0, Math.min(120, y.getInt("slowmode.seconds", plugin.getConfig().getInt("operations.default-slowmode-seconds", 0))));
            commandLockdown = y.getBoolean("command-lockdown.enabled", false);
        }

        private synchronized boolean globalChatEnabled() { return globalChatEnabled; }

        private synchronized void setGlobalChatEnabled(String admin, boolean enabled) {
            globalChatEnabled = enabled;
            changedBy = admin == null ? "System" : plugin.sanitizeText(admin, 80);
            changedAt = System.currentTimeMillis();
            save();
            plugin.audit.log(changedBy, null, "Globaler Chat", enabled ? "aktiviert" : "deaktiviert");
            String publicText = enabled
                    ? plugin.getConfig().getString("global-chat.enabled-message", "Global chat has been enabled by staff.")
                    : plugin.getConfig().getString("global-chat.disabled-message", "Global chat has been disabled by staff.");
            plugin.broadcastPublicText(plugin.prefix() + stripFormatting(publicText));
        }

        private synchronized int slowmodeSeconds() { return slowmodeSeconds; }
        private synchronized boolean commandLockdownEnabled() { return commandLockdown; }
        private synchronized void setSlowmode(String actor, int seconds) { slowmodeSeconds=Math.max(0,Math.min(120,seconds)); lastChatAt.clear(); save(); plugin.audit.log(actor,null,"Chat-Slowmode",slowmodeSeconds+" Sekunden"); plugin.broadcastPublicText(plugin.prefix()+stripFormatting(plugin.getConfig().getString("operations.slowmode-changed-message", slowmodeSeconds<=0?"Chat slowmode has been disabled by staff.":"Chat slowmode is now {seconds} seconds.").replace("{seconds}",Integer.toString(slowmodeSeconds)))); }
        private synchronized void cycleSlowmode(String actor) { int[] values={0,3,5,10,20,30,60};int next=0;for(int i=0;i<values.length;i++)if(values[i]==slowmodeSeconds){next=values[(i+1)%values.length];break;}setSlowmode(actor,next); }
        private long slowmodeRemainingSeconds(Player player) { if(player==null||slowmodeSeconds<=0)return 0L;Long last=lastChatAt.get(player.getUniqueId());if(last==null)return 0L;long remain=slowmodeSeconds*1000L-(System.currentTimeMillis()-last);return remain<=0L?0L:(remain+999L)/1000L; }
        private void markChat(Player player){if(player!=null&&slowmodeSeconds>0)lastChatAt.put(player.getUniqueId(),System.currentTimeMillis());}
        private void forgetChat(UUID uuid){if(uuid!=null)lastChatAt.remove(uuid);}
        private synchronized void setCommandLockdown(String actor, boolean enabled){commandLockdown=enabled;save();plugin.audit.log(actor,null,"Befehls-Lockdown",enabled?"aktiviert":"deaktiviert");String text=enabled?plugin.getConfig().getString("operations.command-lockdown-enabled-message","Commands have been temporarily restricted by staff."):plugin.getConfig().getString("operations.command-lockdown-disabled-message","Command restrictions have been lifted by staff.");plugin.broadcastPublicText(plugin.prefix()+stripFormatting(text));}
        private boolean isLockdownAllowed(String lower){if(lower==null)return false;String root=lower.trim().split("\\s+",2)[0];int colon=root.indexOf(':');if(colon>0)root="/"+root.substring(colon+1);List<String> allowed=plugin.getConfig().getStringList("operations.command-lockdown-whitelist");if(allowed.isEmpty())allowed=Arrays.asList("/help","/msg","/tell","/w","/r","/report","/spawn","/home","/tpa","/tpaccept","/tpdeny","/login","/register");for(String value:allowed){String normalized=value.startsWith("/")?value.toLowerCase(Locale.ROOT):"/"+value.toLowerCase(Locale.ROOT);if(root.equals(normalized))return true;}return lower.startsWith("/sas password")||lower.startsWith("/simplexadmin password");}

        private synchronized String summary() {
            return "Globaler Chat: " + (globalChatEnabled ? "aktiv" : "deaktiviert") + " | Slowmode: " + slowmodeSeconds + "s | Befehls-Lockdown: " + (commandLockdown ? "aktiv" : "inaktiv") + " | geändert von " + changedBy
                    + (changedAt <= 0L ? "" : " am " + plugin.time(changedAt));
        }

        private synchronized void save() {
            try {
                YamlConfiguration y = new YamlConfiguration();
                y.set("global-chat.enabled", globalChatEnabled);
                y.set("global-chat.changed-by", changedBy);
                y.set("global-chat.changed-at", changedAt);
                y.set("slowmode.seconds", slowmodeSeconds);
                y.set("command-lockdown.enabled", commandLockdown);
                saveYamlAtomically(y, file);
            } catch (Exception error) {
                plugin.getLogger().warning("Server-Steuerung konnte nicht gespeichert werden: " + error.getMessage());
            }
        }
    }

    private static final class AdminSpyManager {
        private final SimplexAdminSuite plugin;
        private final File file;
        private final Set<UUID> enabled = Collections.synchronizedSet(new HashSet<>());
        private final Set<UUID> hiddenJoin = Collections.synchronizedSet(new HashSet<>());
        private final Set<UUID> commandSpy = Collections.synchronizedSet(new HashSet<>());
        private final Set<UUID> hiddenQuit = Collections.synchronizedSet(new HashSet<>());
        private final Set<UUID> hiddenTab = Collections.synchronizedSet(new HashSet<>());
        private final Map<UUID, UUID> lastPrivatePartner = new ConcurrentHashMap<>();

        private AdminSpyManager(SimplexAdminSuite plugin) {
            this.plugin = plugin;
            File folder = new File(plugin.getDataFolder(), "staff-workspace");
            if (!folder.exists()) folder.mkdirs();
            this.file = new File(folder, "admin-preferences.yml");
            reload();
            Bukkit.getScheduler().runTaskTimer(plugin, () -> {
                if (hiddenTab.isEmpty()) return;
                for (Player target : Bukkit.getOnlinePlayers()) if (hiddenTab(target)) refreshVisibility(target);
            }, 60L, 100L);
        }

        private synchronized void reload() {
            enabled.clear(); commandSpy.clear(); hiddenJoin.clear(); hiddenQuit.clear(); hiddenTab.clear();
            if (!file.exists()) return;
            YamlConfiguration y = YamlConfiguration.loadConfiguration(file);
            loadUuidSet(y.getStringList("adminspy-enabled"), enabled);
            loadUuidSet(y.getStringList("commandspy-enabled"), commandSpy);
            loadUuidSet(y.getStringList("hidden-join"), hiddenJoin);
            loadUuidSet(y.getStringList("hidden-quit"), hiddenQuit);
            loadUuidSet(y.getStringList("hidden-tab"), hiddenTab);
        }

        private static void loadUuidSet(List<String> values, Set<UUID> target) {
            for (String value : values) try { target.add(UUID.fromString(value)); } catch (Exception ignored) { }
        }

        private boolean enabled(Player player) { return player != null && enabled.contains(player.getUniqueId()); }
        private boolean commandSpyEnabled(Player player) { return player != null && commandSpy.contains(player.getUniqueId()); }
        private boolean hiddenJoin(Player player) { return player != null && hiddenJoin.contains(player.getUniqueId()); }
        private boolean hiddenQuit(Player player) { return player != null && hiddenQuit.contains(player.getUniqueId()); }
        private boolean hiddenTab(Player player) { return player != null && hiddenTab.contains(player.getUniqueId()); }

        private synchronized boolean toggleSpy(Player admin) {
            UUID uuid = admin.getUniqueId();
            boolean value;
            if (enabled.remove(uuid)) value = false; else { enabled.add(uuid); value = true; }
            save();
            plugin.audit.log(admin.getName(), uuid, "AdminSpy", value ? "aktiviert" : "deaktiviert");
            return value;
        }

        private synchronized boolean toggleCommandSpy(Player admin) { boolean v=toggle(commandSpy,admin.getUniqueId()); save(); plugin.audit.log(admin.getName(),admin.getUniqueId(),"Befehls-Spy",v?"aktiviert":"deaktiviert"); return v; }
        private void spyCommand(Player sender,String rawCommand){if(sender==null||rawCommand==null||plugin.isSensitiveCommand(rawCommand.toLowerCase(Locale.ROOT)))return;String clean=plugin.sanitizeText(rawCommand,500);String formatted=plugin.color("&8[&dCommandSpy&8] &f"+sender.getName()+"&8: &f"+clean);for(Player admin:Bukkit.getOnlinePlayers()){if(!commandSpyEnabled(admin)||!plugin.has(admin,"simplexadminsuite.commandspy"))continue;if(plugin.adminSecurity!=null&&plugin.adminSecurity.isLocked(admin))continue;admin.sendMessage(formatted);}}

        private synchronized boolean toggleHiddenJoin(Player admin) { boolean v = toggle(hiddenJoin, admin.getUniqueId()); save(); return v; }
        private synchronized boolean toggleHiddenQuit(Player admin) { boolean v = toggle(hiddenQuit, admin.getUniqueId()); save(); return v; }
        private synchronized boolean toggleHiddenTab(Player admin) {
            UUID uuid = admin.getUniqueId();
            boolean value = toggle(hiddenTab, uuid);
            if (plugin.getConfig().getBoolean("adminspy.complete-stealth-links-messages", true)) {
                if (value) { hiddenJoin.add(uuid); hiddenQuit.add(uuid); }
                else { hiddenJoin.remove(uuid); hiddenQuit.remove(uuid); }
            }
            save();
            refreshVisibility(admin);
            refreshVisibilityLater(admin, 2L);
            refreshVisibilityLater(admin, 20L);
            refreshVisibilityLater(admin, 60L);
            if (plugin.nativeScoreboard != null) plugin.nativeScoreboard.resetBoards();
            plugin.refreshVisualIdentity(admin);
            plugin.audit.log(admin.getName(), uuid, "Kompletter Stealth-Modus", value ? "aktiviert" : "deaktiviert");
            return value;
        }
        private static boolean toggle(Set<UUID> set, UUID uuid) { if (set.remove(uuid)) return false; set.add(uuid); return true; }

        private void spyPublic(Player sender, String message) {
            broadcast("&8[&dAdminSpy&8] &7Chat &f" + sender.getName() + "&8: &f" + plugin.sanitizeText(message, 500));
        }

        private void spyPrivate(Player sender, Player recipient, String message, String commandAlias) {
            String clean = plugin.sanitizeText(message, 500);
            if (clean.isEmpty()) return;
            String recipientName = recipient == null ? "Unbekannt" : recipient.getName();
            broadcast("&8[&dAdminSpy&8] &7Privat &f" + sender.getName() + " &8→ &f" + recipientName + "&8: &f" + clean);
            PlayerProfile senderProfile = plugin.database.touch(sender);
            senderProfile.addPrivateMessage("OUT → " + recipientName + " [" + commandAlias + "]: " + clean);
            plugin.database.save(senderProfile);
            if (recipient != null) {
                lastPrivatePartner.put(sender.getUniqueId(), recipient.getUniqueId());
                lastPrivatePartner.put(recipient.getUniqueId(), sender.getUniqueId());
                PlayerProfile recipientProfile = plugin.database.touch(recipient);
                recipientProfile.addPrivateMessage("IN ← " + sender.getName() + " [" + commandAlias + "]: " + clean);
                plugin.database.save(recipientProfile);
            }
        }

        private boolean capturePrivateCommand(Player sender, String rawCommand) {
            if (rawCommand == null || rawCommand.length() < 2) return false;
            String raw = rawCommand.substring(1).trim();
            if (raw.isEmpty()) return false;
            String[] parts = raw.split("\\s+", 3);
            String root = parts[0].toLowerCase(Locale.ROOT);
            int namespace = root.indexOf(':');
            if (namespace >= 0) root = root.substring(namespace + 1);
            Set<String> direct = new HashSet<>(plugin.getConfig().getStringList("adminspy.private-message-aliases"));
            if (direct.isEmpty()) direct.addAll(Arrays.asList("msg", "tell", "w", "whisper", "message", "pm", "m"));
            Set<String> replies = new HashSet<>(plugin.getConfig().getStringList("adminspy.reply-aliases"));
            if (replies.isEmpty()) replies.addAll(Arrays.asList("r", "reply"));
            if (direct.contains(root)) {
                if (parts.length < 3) return false;
                Player recipient = findOnline(parts[1]);
                spyPrivate(sender, recipient, parts[2], root);
                return true;
            }
            if (replies.contains(root)) {
                String[] replyParts = raw.split("\\s+", 2);
                if (replyParts.length < 2) return false;
                UUID partner = lastPrivatePartner.get(sender.getUniqueId());
                Player recipient = partner == null ? null : Bukkit.getPlayer(partner);
                spyPrivate(sender, recipient, replyParts[1], root);
                return true;
            }
            return false;
        }

        private Player findOnline(String query) {
            Player exact = Bukkit.getPlayerExact(query);
            if (exact != null) return exact;
            String lower = query.toLowerCase(Locale.ROOT);
            for (Player player : Bukkit.getOnlinePlayers()) if (player.getName().toLowerCase(Locale.ROOT).startsWith(lower)) return player;
            return null;
        }

        private void broadcast(String colored) {
            String formatted = plugin.color(colored);
            for (Player admin : Bukkit.getOnlinePlayers()) {
                if (!enabled(admin) || !plugin.has(admin, "simplexadminsuite.adminspy")) continue;
                if (plugin.adminSecurity != null && plugin.adminSecurity.isLocked(admin)) continue;
                admin.sendMessage(formatted);
            }
        }

        private void applyVisibilityForJoin(Player joined) {
            if (joined == null) return;
            for (Player target : Bukkit.getOnlinePlayers()) applyVisibility(joined, target, hiddenTab(target));
            if (hiddenTab(joined)) refreshVisibility(joined);
            refreshAllVisibilityLater(5L);
            refreshAllVisibilityLater(30L);
        }

        private void refreshVisibility(Player target) {
            if (target == null) return;
            boolean hidden = hiddenTab(target);
            for (Player viewer : Bukkit.getOnlinePlayers()) applyVisibility(viewer, target, hidden);
        }

        private void refreshVisibilityLater(Player target, long ticks) {
            Bukkit.getScheduler().runTaskLater(plugin, () -> {
                if (target != null && Bukkit.getPlayer(target.getUniqueId()) != null) refreshVisibility(target);
            }, Math.max(1L, ticks));
        }

        private void refreshAllVisibilityLater(long ticks) {
            Bukkit.getScheduler().runTaskLater(plugin, () -> {
                for (Player target : Bukkit.getOnlinePlayers()) if (hiddenTab(target)) refreshVisibility(target);
                if (plugin.nativeScoreboard != null) plugin.nativeScoreboard.resetBoards();
            }, Math.max(1L, ticks));
        }

        private void applyVisibility(Player viewer, Player target, boolean hidden) {
            if (viewer == null || target == null || viewer.getUniqueId().equals(target.getUniqueId())) return;
            boolean privilegedViewer = viewer.isOp() || plugin.has(viewer, "simplexadminsuite.admin");
            boolean shouldHide = (plugin.adminRuntime != null && plugin.adminRuntime.vanished(target)) || (hidden && !privilegedViewer);
            try {
                Method method = Player.class.getMethod(shouldHide ? "hidePlayer" : "showPlayer", Plugin.class, Player.class);
                method.invoke(viewer, plugin, target);
            } catch (Throwable ignored) { }
        }

        private synchronized void save() {
            try {
                YamlConfiguration y = new YamlConfiguration();
                y.set("commandspy-enabled", commandSpy.stream().map(UUID::toString).collect(Collectors.toList()));
                y.set("adminspy-enabled", enabled.stream().map(UUID::toString).collect(Collectors.toList()));
                y.set("hidden-join", hiddenJoin.stream().map(UUID::toString).collect(Collectors.toList()));
                y.set("hidden-quit", hiddenQuit.stream().map(UUID::toString).collect(Collectors.toList()));
                y.set("hidden-tab", hiddenTab.stream().map(UUID::toString).collect(Collectors.toList()));
                saveYamlAtomically(y, file);
            } catch (Exception error) {
                plugin.getLogger().warning("Admin-Einstellungen konnten nicht gespeichert werden: " + error.getMessage());
            }
        }
    }

    private static final class AdminSecurityManager {
        private static final int PASSWORD_ITERATIONS = 120_000;
        private static final int PASSWORD_BITS = 256;
        private final SimplexAdminSuite plugin;
        private final Map<UUID, AuthSession> pending = new ConcurrentHashMap<>();
        private final Set<UUID> authenticated = Collections.synchronizedSet(new HashSet<>());
        private final Map<UUID, PasswordChangeSession> passwordChanges = new ConcurrentHashMap<>();
        private final Map<UUID, PasswordRecord> personalPasswords = new ConcurrentHashMap<>();
        private final File passwordFile;
        private byte[] generalPasswordHash = new byte[0];
        private boolean enabled;
        private int maxAttempts;
        private long timeoutMillis;

        private AdminSecurityManager(SimplexAdminSuite plugin) {
            this.plugin = plugin;
            File folder = new File(plugin.getDataFolder(), "security");
            if (!folder.exists()) folder.mkdirs();
            this.passwordFile = new File(folder, "admin-passwords.yml");
            loadPersonalPasswords();
            reload();
        }

        private synchronized void reload() {
            enabled = plugin.getConfig().getBoolean("admin-security.enabled", true);
            maxAttempts = Math.max(1, plugin.getConfig().getInt("admin-security.max-attempts", 3));
            timeoutMillis = Math.max(15L, plugin.getConfig().getLong("admin-security.timeout-seconds", 90L)) * 1000L;
            String password = plugin.getConfig().getString("admin-security.general-password", "CHANGE-ME-BEFORE-USE");
            generalPasswordHash = digest(password == null ? "" : password.trim());
            if (enabled && "CHANGE-ME-BEFORE-USE".equals(password)) {
                plugin.getLogger().warning("ADMIN-SICHERHEIT: Das Standardpasswort CHANGE-ME-BEFORE-USE ist noch aktiv. Ändere es über die Serverkonsole: sas password set <neues Passwort>");
            }
            loadPersonalPasswords();
            if (!enabled) {
                pending.clear();
                authenticated.clear();
                passwordChanges.clear();
            }
        }

        private int minimumPasswordLength() {
            return Math.max(8, plugin.getConfig().getInt("admin-security.minimum-password-length", 12));
        }

        private boolean requires(Player player) {
            return enabled && player != null && (player.isOp() || plugin.has(player, "simplexadminsuite.admin"));
        }

        private boolean isLocked(Player player) {
            if(plugin.appApi!=null && plugin.appApi.remote(player))return false;
            return requires(player) && !authenticated.contains(player.getUniqueId());
        }

        private boolean isAuthenticated(Player player) {
            return !requires(player) || authenticated.contains(player.getUniqueId());
        }

        private boolean hasPersonalPassword(UUID uuid) {
            return plugin.getConfig().getBoolean("admin-security.personal-passwords-enabled", true)
                    && uuid != null && personalPasswords.containsKey(uuid);
        }

        private int remainingAttempts(Player player) {
            AuthSession session = player == null ? null : pending.get(player.getUniqueId());
            return session == null ? maxAttempts : Math.max(0, maxAttempts - session.attempts);
        }

        private void begin(Player player) {
            if (!requires(player)) return;
            UUID uuid = player.getUniqueId();
            authenticated.remove(uuid);
            passwordChanges.remove(uuid);
            AuthSession session = new AuthSession(System.currentTimeMillis(), player.getLocation());
            pending.put(uuid, session);
            PlayerProfile profile = plugin.database.touch(player);
            profile.addAction("Admin-Authentifizierung angefordert");
            plugin.database.save(profile);
            Bukkit.getScheduler().runTaskLater(plugin, () -> prompt(player), 10L);
            long startedAt = session.startedAt;
            Bukkit.getScheduler().runTaskLater(plugin, () -> {
                AuthSession current = pending.get(uuid);
                if (current != null && current.startedAt == startedAt && System.currentTimeMillis() - current.startedAt >= timeoutMillis) {
                    failAndKick(player, "Admin authentication timed out.");
                }
            }, Math.max(20L, timeoutMillis / 50L));
        }

        private void prompt(Player player) {
            if (player == null || !isLocked(player) || Bukkit.getPlayer(player.getUniqueId()) == null) return;
            AuthSession session = pending.get(player.getUniqueId());
            if (session == null) {
                begin(player);
                return;
            }
            long now = System.currentTimeMillis();
            if (now - session.lastPromptAt < 1200L) return;
            session.lastPromptAt = now;
            if (plugin.bedrockMenus.isBedrock(player)) {
                if (!plugin.bedrockMenus.openAdminAuthentication(player)) {
                    plugin.menuNotice(player,plugin.prefix() + plugin.color("&cDas Bedrock-Passwortformular konnte nicht geöffnet werden. &7Es wird erneut versucht."));
                    Bukkit.getScheduler().runTaskLater(plugin, () -> prompt(player), 40L);
                }
            } else {
                plugin.promptJavaAdminAuthentication(player);
            }
        }

        private void submit(Player player, String password) {
            if (player == null || !isLocked(player)) return;
            AuthSession session = pending.get(player.getUniqueId());
            if (session == null) {
                begin(player);
                return;
            }
            String candidate = password == null ? "" : password.trim();
            if (verifyPassword(player.getUniqueId(), candidate)) {
                pending.remove(player.getUniqueId());
                authenticated.add(player.getUniqueId());
                plugin.authNotices.remove(player.getUniqueId());
                PlayerProfile profile = plugin.database.touch(player);
                profile.lastAdminAuthenticationAt = System.currentTimeMillis();
                profile.failedAdminAuthentications = 0;
                profile.addAction("Admin-Authentifizierung erfolgreich");
                plugin.database.save(profile);
                player.closeInventory();
                plugin.menuNotice(player,plugin.prefix() + plugin.color("&aAdmin-Authentifizierung erfolgreich. &7Deine Verwaltungsrechte sind für diese Sitzung freigeschaltet."));
                if (!hasPersonalPassword(player.getUniqueId())) {
                    player.sendMessage(plugin.playerUiText(player, plugin.prefix() + plugin.color("&eDu nutzt noch das allgemeine Serverpasswort. &7Mit &f/sas password change &7kannst du optional ein persönliches Passwort setzen.")));
                    if (plugin.bedrockMenus.isBedrock(player)) {
                        Bukkit.getScheduler().runTaskLater(plugin, () -> plugin.bedrockMenus.offerPersonalPasswordSetup(player), 20L);
                    }
                }
                plugin.audit.log(player.getName(), player.getUniqueId(), "Admin-Login", "erfolgreich");
                plugin.afk.activity(player);
                plugin.deliverPostJoin(player);
                return;
            }

            session.attempts++;
            PlayerProfile profile = plugin.database.touch(player);
            profile.failedAdminAuthentications++;
            profile.addAction("Admin-Authentifizierung fehlgeschlagen (Versuch " + session.attempts + ")");
            plugin.database.save(profile);
            plugin.audit.log(player.getName(), player.getUniqueId(), "Admin-Login", "fehlgeschlagen, Versuch " + session.attempts);
            if (session.attempts >= maxAttempts) {
                failAndKick(player, plugin.getConfig().getString("admin-security.kick-message", "Admin authentication failed."));
            } else {
                player.sendMessage(plugin.playerUiText(player, plugin.prefix() + plugin.color("&cFalsches Admin-Passwort. &7Verbleibende Versuche: &f" + remainingAttempts(player))));
                Bukkit.getScheduler().runTaskLater(plugin, () -> prompt(player), plugin.bedrockMenus.isBedrock(player) ? 20L : 5L);
            }
        }

        private boolean verifyPassword(UUID uuid, String candidate) {
            PasswordRecord record = plugin.getConfig().getBoolean("admin-security.personal-passwords-enabled", true)
                    ? personalPasswords.get(uuid) : null;
            if (record != null) return record.matches(candidate);
            return MessageDigest.isEqual(generalPasswordHash, digest(candidate));
        }

        private void cancelled(Player player) {
            if (player == null || !isLocked(player)) return;
            AuthSession session = pending.get(player.getUniqueId());
            if (session == null) return;
            session.cancellations++;
            if (session.cancellations >= maxAttempts) {
                failAndKick(player, "Admin authentication was cancelled too many times.");
            } else {
                player.sendMessage(plugin.playerUiText(player, plugin.prefix() + plugin.color("&cAdmin-Anmeldung abgebrochen. &7Verbleibende Versuche: &f" + (maxAttempts - session.cancellations))));
                Bukkit.getScheduler().runTaskLater(plugin, () -> prompt(player), 20L);
            }
        }

        private void failAndKick(Player player, String publicMessage) {
            if (player == null) return;
            pending.remove(player.getUniqueId());
            authenticated.remove(player.getUniqueId());
            passwordChanges.remove(player.getUniqueId());
            plugin.suiteKick(player,stripFormatting(publicMessage == null ? "Admin authentication failed." : publicMessage));
        }

        private void quit(Player player) {
            if (player == null) return;
            pending.remove(player.getUniqueId());
            authenticated.remove(player.getUniqueId());
            passwordChanges.remove(player.getUniqueId());
        }

        private Location anchor(Player player) {
            AuthSession session = player == null ? null : pending.get(player.getUniqueId());
            return session == null ? null : session.anchor;
        }

        private boolean isPasswordChangePending(UUID actorUuid) {
            return actorUuid != null && passwordChanges.containsKey(actorUuid);
        }

        private void beginPasswordChange(Player actor, UUID targetUuid) {
            if (actor == null || targetUuid == null || !isAuthenticated(actor)) return;
            if (!actor.getUniqueId().equals(targetUuid) && (!actor.isOp() || !plugin.isStaffAccount(targetUuid))) {
                actor.sendMessage(plugin.prefix() + "Nur echte Server-Operatoren dürfen Passwörter anderer Admins ändern.");
                return;
            }
            passwordChanges.put(actor.getUniqueId(), new PasswordChangeSession(targetUuid, System.currentTimeMillis()));
            actor.closeInventory();
            actor.sendMessage(plugin.color("&8&m----------------------------------------"));
            actor.sendMessage(plugin.prefix() + plugin.color("&cGeschützte Passwortänderung"));
            actor.sendMessage(plugin.color("&7Schreibe das neue Passwort direkt in den Chat."));
            actor.sendMessage(plugin.color("&7Es muss mindestens &f" + minimumPasswordLength() + " Zeichen &7lang sein."));
            actor.sendMessage(plugin.color("&7Mit &fabbrechen &7kannst du den Vorgang beenden."));
            actor.sendMessage(plugin.color("&8&m----------------------------------------"));
            long startedAt = passwordChanges.get(actor.getUniqueId()).startedAt;
            Bukkit.getScheduler().runTaskLater(plugin, () -> {
                PasswordChangeSession current = passwordChanges.get(actor.getUniqueId());
                if (current != null && current.startedAt == startedAt) {
                    passwordChanges.remove(actor.getUniqueId());
                    if (Bukkit.getPlayer(actor.getUniqueId()) != null) actor.sendMessage(plugin.prefix() + "Passwortänderung wegen Zeitüberschreitung abgebrochen.");
                }
            }, Math.max(20L, timeoutMillis / 50L));
        }

        private void handlePasswordChangeChat(Player actor, String message) {
            if (actor == null) return;
            PasswordChangeSession session = passwordChanges.get(actor.getUniqueId());
            if (session == null) return;
            String value = message == null ? "" : message.trim();
            if (value.equalsIgnoreCase("abbrechen") || value.equalsIgnoreCase("cancel")) {
                passwordChanges.remove(actor.getUniqueId());
                actor.sendMessage(plugin.prefix() + "Passwortänderung abgebrochen.");
                return;
            }
            if (session.stage == 0) {
                String error = validatePassword(value);
                if (error != null) {
                    actor.sendMessage(plugin.prefix() + error);
                    actor.sendMessage(plugin.prefix() + "Gib ein anderes Passwort ein oder schreibe 'abbrechen'.");
                    return;
                }
                session.firstValue = value;
                session.stage = 1;
                actor.sendMessage(plugin.prefix() + plugin.color("&eGib dasselbe Passwort zur Bestätigung erneut in den Chat ein."));
                return;
            }
            if (!MessageDigest.isEqual(digest(session.firstValue), digest(value))) {
                session.firstValue = "";
                session.stage = 0;
                actor.sendMessage(plugin.prefix() + plugin.color("&cDie Passwörter stimmen nicht überein. &7Beginne erneut mit dem neuen Passwort."));
                return;
            }
            UUID targetUuid = session.targetUuid;
            passwordChanges.remove(actor.getUniqueId());
            if (!actor.getUniqueId().equals(targetUuid) && (!actor.isOp() || !plugin.isStaffAccount(targetUuid))) {
                actor.sendMessage(plugin.prefix() + "Die Berechtigung zum Ändern dieses Passworts ist nicht mehr vorhanden.");
                return;
            }
            String error = setPersonalPassword(targetUuid, value, actor.getName());
            if (error != null) {
                actor.sendMessage(plugin.prefix() + error);
                return;
            }
            PlayerProfile target = plugin.database.get(targetUuid);
            actor.sendMessage(plugin.prefix() + plugin.color("&aPersönliches Passwort für &f" + (target == null ? targetUuid : target.name) + " &awurde gespeichert."));
            if (!actor.getUniqueId().equals(targetUuid)) forceReauthentication(targetUuid);
        }

        private void completePasswordChangeForm(Player actor, UUID targetUuid, String first, String second) {
            if (actor == null || targetUuid == null || !isAuthenticated(actor)) return;
            if (!actor.getUniqueId().equals(targetUuid) && (!actor.isOp() || !plugin.isStaffAccount(targetUuid))) {
                actor.sendMessage(plugin.prefix() + "Nur echte Server-Operatoren dürfen Passwörter anderer Admins ändern.");
                return;
            }
            String cleanFirst = first == null ? "" : first.trim();
            String cleanSecond = second == null ? "" : second.trim();
            String error = validatePassword(cleanFirst);
            if (error != null) {
                actor.sendMessage(plugin.prefix() + error);
                Bukkit.getScheduler().runTaskLater(plugin, () -> {
                    if (actor.getUniqueId().equals(targetUuid)) plugin.bedrockMenus.openOwnPasswordChange(actor);
                    else plugin.bedrockMenus.openOtherPasswordChange(actor, targetUuid);
                }, 10L);
                return;
            }
            if (!MessageDigest.isEqual(digest(cleanFirst), digest(cleanSecond))) {
                actor.sendMessage(plugin.prefix() + plugin.color("&cDie beiden Passwörter stimmen nicht überein."));
                Bukkit.getScheduler().runTaskLater(plugin, () -> {
                    if (actor.getUniqueId().equals(targetUuid)) plugin.bedrockMenus.openOwnPasswordChange(actor);
                    else plugin.bedrockMenus.openOtherPasswordChange(actor, targetUuid);
                }, 10L);
                return;
            }
            error = setPersonalPassword(targetUuid, cleanFirst, actor.getName());
            if (error != null) {
                actor.sendMessage(plugin.prefix() + error);
                return;
            }
            PlayerProfile target = plugin.database.get(targetUuid);
            actor.sendMessage(plugin.prefix() + plugin.color("&aPersönliches Passwort für &f" + (target == null ? targetUuid : target.name) + " &awurde gespeichert."));
            if (!actor.getUniqueId().equals(targetUuid)) forceReauthentication(targetUuid);
        }

        private String setPersonalPassword(UUID targetUuid, String password, String changedBy) {
            if (!plugin.getConfig().getBoolean("admin-security.personal-passwords-enabled", true)) return "Persönliche Admin-Passwörter sind in der Konfiguration deaktiviert.";
            if (targetUuid == null) return "Ungültiger Admin.";
            String clean = password == null ? "" : password.trim();
            String error = validatePassword(clean);
            if (error != null) return error;
            try {
                PasswordRecord record = PasswordRecord.create(clean, changedBy);
                personalPasswords.put(targetUuid, record);
                savePersonalPasswords();
                plugin.audit.log(changedBy == null ? "SYSTEM" : changedBy, targetUuid, "Persönliches Admin-Passwort", "gesetzt");
                return null;
            } catch (Exception failure) {
                plugin.getLogger().warning("Persönliches Admin-Passwort konnte nicht gespeichert werden: " + failure.getMessage());
                return "Das Passwort konnte nicht sicher gespeichert werden.";
            }
        }

        private void resetPersonalPassword(UUID targetUuid, String changedBy) {
            if (targetUuid == null) return;
            boolean removed = personalPasswords.remove(targetUuid) != null;
            savePersonalPasswords();
            plugin.audit.log(changedBy == null ? "SYSTEM" : changedBy, targetUuid, "Persönliches Admin-Passwort", removed ? "zurückgesetzt" : "bereits allgemein");
            forceReauthentication(targetUuid);
        }

        private String validatePassword(String password) {
            String clean = password == null ? "" : password;
            if (clean.length() < minimumPasswordLength()) return "Das Passwort muss mindestens " + minimumPasswordLength() + " Zeichen lang sein.";
            if (clean.length() > 128) return "Das Passwort darf höchstens 128 Zeichen lang sein.";
            if (clean.indexOf('\n') >= 0 || clean.indexOf('\r') >= 0) return "Das Passwort darf keine Zeilenumbrüche enthalten.";
            return null;
        }

        private void forceReauthentication(UUID targetUuid) {
            if (targetUuid == null) return;
            authenticated.remove(targetUuid);
            pending.remove(targetUuid);
            passwordChanges.remove(targetUuid);
            Player target = Bukkit.getPlayer(targetUuid);
            if (target != null && requires(target)) begin(target);
        }

        private synchronized void setPasswordFromConsole(CommandSender sender, String password) {
            if (!(sender instanceof ConsoleCommandSender)) {
                sender.sendMessage(plugin.prefix() + "Das allgemeine Admin-Passwort kann ausschließlich über die Serverkonsole geändert werden.");
                return;
            }
            String clean = password == null ? "" : password.trim();
            String error = validatePassword(clean);
            if (error != null) {
                sender.sendMessage(plugin.prefix() + error);
                return;
            }
            plugin.getConfig().set("admin-security.general-password", clean);
            plugin.saveConfig();
            generalPasswordHash = digest(clean);
            plugin.menuNotice(sender,plugin.prefix() + "Das allgemeine Admin-Passwort wurde geändert. Es gilt ab dem nächsten Login für Admins ohne persönliches Passwort.");
            plugin.audit.log("CONSOLE", null, "Allgemeines Admin-Passwort", "geändert");
        }

        private synchronized void reloadPassword(CommandSender sender) {
            if (!(sender instanceof ConsoleCommandSender)) {
                sender.sendMessage(plugin.prefix() + "Die Admin-Sicherheitskonfiguration kann ausschließlich über die Serverkonsole neu geladen werden.");
                return;
            }
            plugin.reloadConfig();
            reload();
            plugin.menuNotice(sender,plugin.prefix() + "Admin-Sicherheitskonfiguration sowie persönliche Passwortdaten wurden neu geladen.");
        }

        private synchronized void loadPersonalPasswords() {
            if (!passwordFile.exists()) {
                personalPasswords.clear();
                return;
            }
            Map<UUID, PasswordRecord> loaded = new HashMap<>();
            try {
                YamlConfiguration y = YamlConfiguration.loadConfiguration(passwordFile);
                int count = y.getInt("count", 0);
                for (int i = 0; i < count; i++) {
                    String path = "records." + i;
                    UUID uuid;
                    try { uuid = UUID.fromString(y.getString(path + ".uuid", "")); }
                    catch (Exception invalid) { continue; }
                    String salt = y.getString(path + ".salt", "");
                    String hash = y.getString(path + ".hash", "");
                    int iterations = Math.max(10_000, y.getInt(path + ".iterations", PASSWORD_ITERATIONS));
                    if (salt.isBlank() || hash.isBlank()) continue;
                    loaded.put(uuid, new PasswordRecord(salt, hash, iterations,
                            y.getLong(path + ".updated-at", 0L), y.getString(path + ".updated-by", "Unbekannt")));
                }
                personalPasswords.clear();
                personalPasswords.putAll(loaded);
            } catch (Exception error) {
                plugin.getLogger().warning("Persönliche Admin-Passwörter konnten nicht geladen werden; vorhandene In-Memory-Daten bleiben aktiv: " + error.getMessage());
            }
        }

        private synchronized void savePersonalPasswords() {
            try {
                YamlConfiguration y = new YamlConfiguration();
                List<Map.Entry<UUID, PasswordRecord>> entries = new ArrayList<>(personalPasswords.entrySet());
                entries.sort(Comparator.comparing(entry -> entry.getKey().toString()));
                y.set("count", entries.size());
                for (int i = 0; i < entries.size(); i++) {
                    Map.Entry<UUID, PasswordRecord> entry = entries.get(i);
                    PasswordRecord record = entry.getValue();
                    String path = "records." + i;
                    y.set(path + ".uuid", entry.getKey().toString());
                    y.set(path + ".salt", record.saltBase64);
                    y.set(path + ".hash", record.hashBase64);
                    y.set(path + ".iterations", record.iterations);
                    y.set(path + ".updated-at", record.updatedAt);
                    y.set(path + ".updated-by", record.updatedBy);
                }
                saveYamlAtomically(y, passwordFile);
            } catch (Exception error) {
                plugin.getLogger().warning("Persönliche Admin-Passwörter konnten nicht gespeichert werden: " + error.getMessage());
            }
        }

        private static byte[] digest(String value) {
            try {
                return MessageDigest.getInstance("SHA-256").digest((value == null ? "" : value).getBytes(StandardCharsets.UTF_8));
            } catch (Exception impossible) {
                throw new IllegalStateException(impossible);
            }
        }
    }

