        private void secureFile(File file) {
            try { file.setReadable(false, false); file.setWritable(false, false); file.setExecutable(false, false); file.setReadable(true, true); file.setWritable(true, true); } catch (Exception ignored) { }
        }

        private synchronized void loadIdentifierBlocks() {
            blockedDevices.clear();
            blockedIps.clear();
            if (!blockedIdentifiersFile.exists()) return;
            YamlConfiguration y = YamlConfiguration.loadConfiguration(blockedIdentifiersFile);
            int count = y.getInt("count", 0);
            for (int i = 0; i < count; i++) {
                String path = "blocks." + i;
                String type = y.getString(path + ".type", "").toUpperCase(Locale.ROOT);
                String value = y.getString(path + ".value", "");
                if (value.isBlank()) continue;
                IdentifierBlock block = new IdentifierBlock(type, value, y.getString(path + ".actor", "Unknown"),
                        y.getString(path + ".source-name", "Unknown"), y.getLong(path + ".created-at", 0L));
                if (type.equals("DEVICE")) blockedDevices.put(value, block);
                else if (type.equals("IP")) blockedIps.put(value, block);
            }
            for (PlayerProfile profile : plugin.database.sortedProfiles()) {
                boolean changed = false;
                synchronized (profile.devices) {
                    for (DeviceRecord record : profile.devices.values()) {
                        boolean expected = "BEDROCK".equals(record.platform) && blockedDevices.containsKey(record.id);
                        if (record.blocked != expected) { record.blocked = expected; changed = true; }
                    }
                }
                if (changed) plugin.database.save(profile);
            }
        }

        private synchronized boolean saveIdentifierBlocks() {
            try {
                YamlConfiguration y = new YamlConfiguration();
                List<IdentifierBlock> blocks = new ArrayList<>();
                blocks.addAll(blockedDevices.values());
                blocks.addAll(blockedIps.values());
                y.set("schema", 1);
                y.set("count", blocks.size());
                for (int i = 0; i < blocks.size(); i++) {
                    IdentifierBlock block = blocks.get(i);
                    String path = "blocks." + i;
                    y.set(path + ".type", block.type);
                    y.set(path + ".value", block.value);
                    y.set(path + ".actor", block.actor);
                    y.set(path + ".source-name", block.sourceName);
                    y.set(path + ".created-at", block.createdAt);
                }
                saveYamlAtomically(y, blockedIdentifiersFile);
                secureFile(blockedIdentifiersFile);return true;
            } catch (Exception error) {
                plugin.getLogger().warning("Geräte-/IP-Sperren konnten nicht gespeichert werden: " + error.getMessage());return false;
            }
        }

