    public static final class PlayerDatabase {
        private final SimplexAdminSuite plugin; private final File folder; private final Map<UUID, PlayerProfile> profiles = new LinkedHashMap<>();
        private PlayerDatabase(SimplexAdminSuite plugin) { this.plugin = plugin; this.folder = new File(plugin.getDataFolder(), "players"); if (!folder.exists()) folder.mkdirs(); loadAll(); }
        private synchronized void loadAll() {
            profiles.clear();
            if (!folder.exists()) folder.mkdirs();
            File[] dirs = folder.listFiles(File::isDirectory);
            if (dirs == null) return;
            List<PlayerProfile> migrated = new ArrayList<>();
            for (File dir : dirs) {
                File file = new File(dir, "profil.yml");
                if (!file.exists()) continue;
                try {
                    PlayerProfile profile = PlayerProfile.load(file);
                    profiles.put(profile.uuid, profile);
                    if (profile.schemaVersion == 15) migrated.add(profile);
                    else if (profile.schemaVersion < 15) plugin.getLogger().warning("Altes Spielerprofil-Schema " + profile.schemaVersion
                            + " bei " + profile.name + " erkannt; 7.2.0 führt bewusst keine historischen Migrationsketten mehr aus.");
                } catch (Exception error) {
                    plugin.getLogger().warning("Konnte Spielerprofil nicht laden: " + file.getPath() + " - " + error.getMessage());
                }
            }
            for (PlayerProfile profile : migrated) {
                int oldSchema = profile.schemaVersion;
                profile.schemaVersion = CURRENT_DATA_SCHEMA;
                profile.addAction("Datenprofil automatisch von Schema " + oldSchema + " auf " + CURRENT_DATA_SCHEMA + " migriert");
                save(profile);
            }
            if (!migrated.isEmpty()) plugin.getLogger().info(migrated.size() + " Spielerprofile wurden verlustfrei auf Datenschema " + CURRENT_DATA_SCHEMA + " migriert.");
        }
        private synchronized PlayerProfile touch(Player player) { PlayerProfile profile = profiles.get(player.getUniqueId()); long now = System.currentTimeMillis(); if (profile == null) { profile = new PlayerProfile(player.getUniqueId(), player.getName()); profile.firstSeen = now; profiles.put(profile.uuid, profile); } if (!profile.name.equals(player.getName())) { profile.previousNames.add(profile.name); profile.name = player.getName(); profile.addAction("Namensänderung erkannt: " + profile.previousNames.get(profile.previousNames.size() - 1) + " → " + player.getName()); } profile.lastSeen = now; UUID accessId=profile.uuid; profile.emergencyAccess=()->plugin.emergency(accessId); if(plugin.pointsEconomy!=null)plugin.pointsEconomy.attach(profile); return profile; }
        private synchronized PlayerProfile get(UUID uuid) { return profiles.get(uuid); }
        private synchronized int staffNotesUpdatedAfter(long timestamp) {
            int count = 0;
            for (PlayerProfile profile : profiles.values()) if (profile.staffNotesUpdatedAt > timestamp) count++;
            return count;
        }
        private synchronized PlayerProfile find(String name) { if (name == null) return null; for (PlayerProfile p : profiles.values()) if (p.name.equalsIgnoreCase(name)) return p; for (PlayerProfile p : profiles.values()) if (p.name.toLowerCase(Locale.ROOT).startsWith(name.toLowerCase(Locale.ROOT))) return p; for (PlayerProfile p : profiles.values()) for (String previous : p.previousNames) if (previous.equalsIgnoreCase(name)) return p; try { return profiles.get(UUID.fromString(name)); } catch (Exception ignored) {} return null; }
        private synchronized List<String> names() { return profiles.values().stream().map(p -> p.name).sorted(String.CASE_INSENSITIVE_ORDER).collect(Collectors.toList()); }
        private synchronized List<PlayerProfile> sortedProfiles() { List<PlayerProfile> list = new ArrayList<>(profiles.values()); list.sort(Comparator.comparingLong((PlayerProfile p) -> p.lastSeen).reversed()); return list; }
        private synchronized void save(PlayerProfile profile) {
            File dir = new File(folder, profile.uuid.toString());
            if (!dir.exists()) dir.mkdirs();
            File target = new File(dir, "profil.yml");
            File temporary = new File(dir, "profil.yml.tmp");
            try {
                profile.save(temporary);
                try { Files.move(temporary.toPath(), target.toPath(), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING); }
                catch (Exception atomicMoveUnavailable) { Files.move(temporary.toPath(), target.toPath(), StandardCopyOption.REPLACE_EXISTING); }
            } catch (Exception e) {
                plugin.getLogger().warning("Konnte Profil nicht atomar speichern: " + profile.uuid + " - " + e.getMessage());
            }
        }
        private synchronized List<PlayerProfile> expireTemporaryRights(long now) {
            List<PlayerProfile> changed = new ArrayList<>();
            for (PlayerProfile profile : profiles.values()) if (profile.clearExpiredTemporaryRights(now)) changed.add(profile);
            return changed;
        }
        private synchronized void saveAll() { for (PlayerProfile profile : profiles.values()) save(profile); }
    }

    private static final class DeviceRecord {
        private final String id;
        private String platform;
        private long firstSeen;
        private long lastSeen;
        private String model = "";
        private String os = "";
        private String gameVersion = "";
        private String language = "";
        private String uiProfile = "";
        private String currentInput = "";
        private String defaultInput = "";
        private int guiScale = -1;
        private String serverAddress = "";
        private String platformOnlineId = "";
        private String platformOfflineId = "";
        private String playFabIdHash = "";
        private String armSize = "";
        private boolean thirdPartyNameOnly;
        private String lastIp = "";
        private final Map<String, Long> ipHistory = new LinkedHashMap<>();
        private int viewDistance = -1;
        private int ping = -1;
        private int protocol = -1;
        private boolean blocked;
        private final Map<String,String> diagnostics = new LinkedHashMap<>();
        private final List<String> diagnosticHistory = new ArrayList<>();
        private void updateDiagnostics(Map<String,String> incoming) {
            Map<String,String> before = new LinkedHashMap<>(diagnostics);
            if (DeviceDiagnostics.merge(diagnostics, incoming) && DeviceDiagnostics.materialChange(before, diagnostics)) {
                diagnosticHistory.add(DeviceDiagnostics.encode(diagnostics));
                while (diagnosticHistory.size() > 8) diagnosticHistory.remove(0);
            }
        }

        private DeviceRecord(String id, String platform, long firstSeen) {
            this.id = id;
            this.platform = platform;
            this.firstSeen = firstSeen;
            this.lastSeen = firstSeen;
        }

        private void addIp(String ip, long timestamp) {
            if (ip == null || ip.isBlank()) return;
            ipHistory.put(ip, timestamp);
            while (ipHistory.size() > 10) {
                String oldest = ipHistory.entrySet().stream().min(Map.Entry.comparingByValue()).map(Map.Entry::getKey).orElse(null);
                if (oldest == null) break;
                ipHistory.remove(oldest);
            }
        }

        private List<Map.Entry<String, Long>> recentIps() {
            List<Map.Entry<String, Long>> entries = new ArrayList<>(ipHistory.entrySet());
            entries.sort(Map.Entry.<String, Long>comparingByValue().reversed());
            return entries;
        }

        private String encodeIpHistory() {
            List<String> values = new ArrayList<>();
            for (Map.Entry<String, Long> entry : ipHistory.entrySet()) {
                String ip = Base64.getUrlEncoder().withoutPadding().encodeToString(entry.getKey().getBytes(StandardCharsets.UTF_8));
                values.add(ip + ":" + entry.getValue());
            }
            return String.join(",", values);
        }

        private void decodeIpHistory(String encoded) {
            if (encoded == null || encoded.isBlank()) return;
            for (String value : encoded.split(",")) {
                String[] split = value.split(":", 2);
                if (split.length != 2) continue;
                try {
                    String ip = new String(Base64.getUrlDecoder().decode(split[0]), StandardCharsets.UTF_8);
                    long timestamp = Long.parseLong(split[1]);
                    addIp(ip, timestamp);
                } catch (Exception ignored) { }
            }
        }

        private String encode() {
            return String.join("\t", id, platform, Long.toString(firstSeen), Long.toString(lastSeen), model, os,
                    gameVersion, language, uiProfile, currentInput, defaultInput, Integer.toString(guiScale),
                    serverAddress, platformOnlineId, platformOfflineId, armSize, Boolean.toString(thirdPartyNameOnly),
                    lastIp, Integer.toString(viewDistance), Integer.toString(ping), Integer.toString(protocol), Boolean.toString(blocked), encodeIpHistory(), playFabIdHash, DeviceDiagnostics.encode(diagnostics), String.join(",", diagnosticHistory));
        }

        private static DeviceRecord decode(String line) {
            if (line == null || line.isBlank()) return null;
            String[] fields = line.split("\t", -1);
            if (fields.length < 4 || fields[0].isBlank()) return null;
            DeviceRecord record = new DeviceRecord(fields[0], part(fields, 1), parseLongField(part(fields, 2), 0L));
            record.lastSeen = parseLongField(part(fields, 3), record.firstSeen);
            record.model = part(fields, 4); record.os = part(fields, 5); record.gameVersion = part(fields, 6); record.language = part(fields, 7);
            record.uiProfile = part(fields, 8); record.currentInput = part(fields, 9); record.defaultInput = part(fields, 10);
            record.guiScale = parseIntField(part(fields, 11), -1); record.serverAddress = part(fields, 12);
            record.platformOnlineId = part(fields, 13); record.platformOfflineId = part(fields, 14); record.armSize = part(fields, 15);
            record.thirdPartyNameOnly = Boolean.parseBoolean(part(fields, 16)); record.lastIp = part(fields, 17);
            record.viewDistance = parseIntField(part(fields, 18), -1); record.ping = parseIntField(part(fields, 19), -1);
            record.protocol = parseIntField(part(fields, 20), -1); record.blocked = Boolean.parseBoolean(part(fields, 21));
            record.decodeIpHistory(part(fields, 22));
            record.playFabIdHash = part(fields, 23);
            record.diagnostics.putAll(DeviceDiagnostics.decode(part(fields, 24)));
            for (String snapshot : part(fields, 25).split(",")) if (!DeviceDiagnostics.decode(snapshot).isEmpty() && record.diagnosticHistory.size() < 8) record.diagnosticHistory.add(snapshot);
            if (record.ipHistory.isEmpty() && !record.lastIp.isBlank()) record.addIp(record.lastIp, record.lastSeen);
            return record;
        }

        private static String part(String[] fields, int index) { return index < fields.length ? fields[index] : ""; }
        private static int parseIntField(String value, int fallback) { try { return Integer.parseInt(value); } catch (Exception ignored) { return fallback; } }
        private static long parseLongField(String value, long fallback) { try { return Long.parseLong(value); } catch (Exception ignored) { return fallback; } }
    }

