        private long simplexPoints; private long pointsActiveMillis;
        PointsEconomy pointsEconomy;
        synchronized void mirrorPoints(long amount){simplexPoints=amount;}
        private long lastAdminAuthenticationAt; private int failedAdminAuthentications;
        private final Set<String> blockedRights = Collections.synchronizedSet(new HashSet<>());
        private final Map<String, Long> temporaryBlockedRights = Collections.synchronizedMap(new LinkedHashMap<>());
        private final List<String> previousNames = Collections.synchronizedList(new ArrayList<>()); private final List<String> recentChat = Collections.synchronizedList(new ArrayList<>()); private final List<String> recentPrivateMessages = Collections.synchronizedList(new ArrayList<>()); private final List<String> recentActions = Collections.synchronizedList(new ArrayList<>()); private final List<String> recentCombat = Collections.synchronizedList(new ArrayList<>()); private final List<String> warnings = Collections.synchronizedList(new ArrayList<>()); private final List<String> notes = Collections.synchronizedList(new ArrayList<>());
        private PlayerProfile(UUID uuid, String name) { this.uuid = uuid; this.name = name; }
        private volatile java.util.function.BooleanSupplier emergencyAccess = () -> false;
        private synchronized boolean isBlocked(String right) {
            if(emergencyAccess.getAsBoolean())return false;
            if (blockedRights.contains(right)) return true;
            Long until = temporaryBlockedRights.get(right);
            if (until == null) return false;
            if (until > System.currentTimeMillis()) return true;
            temporaryBlockedRights.remove(right);
            return false;
        }
        synchronized String inheritedRightSnapshot(String right) { return blockedRights.contains(right)+":"+temporaryBlockedUntil(right); }
        synchronized void restoreInheritedRight(String right,String snapshot) {
            String[] parts=snapshot.split(":",2);boolean permanent=Boolean.parseBoolean(parts[0]);long until=parts.length==2?Long.parseLong(parts[1]):0L;
            setBlocked(right,permanent);if(!permanent&&until>System.currentTimeMillis())setTemporaryBlocked(right,until);
        }
        private synchronized void setBlocked(String right, boolean blocked) {
            temporaryBlockedRights.remove(right);
            if (blocked) blockedRights.add(right); else blockedRights.remove(right);
        }
        private synchronized void setTemporaryBlocked(String right, long until) {
            blockedRights.remove(right);
            if (until > System.currentTimeMillis()) temporaryBlockedRights.put(right, until); else temporaryBlockedRights.remove(right);
        }
        private synchronized long temporaryBlockedUntil(String right) {
            Long until = temporaryBlockedRights.get(right);
            if (until == null) return 0L;
            if (until > System.currentTimeMillis()) return until;
            temporaryBlockedRights.remove(right);
            return 0L;
        }
        private synchronized Map<String, Long> temporaryBlockedRightsSnapshot() {
            clearExpiredTemporaryRights(System.currentTimeMillis());
            return new LinkedHashMap<>(temporaryBlockedRights);
        }
        synchronized void replaceTemporaryBlockedRights(Map<String, Long> rights) {
            temporaryBlockedRights.clear();
            long now = System.currentTimeMillis();
            if (rights != null) for (Map.Entry<String, Long> entry : rights.entrySet()) {
                if (entry.getKey() != null && !entry.getKey().isBlank() && entry.getValue() != null && entry.getValue() > now)
                    temporaryBlockedRights.put(entry.getKey(), entry.getValue());
            }
        }
        private synchronized boolean clearExpiredTemporaryRights(long now) {
            return temporaryBlockedRights.entrySet().removeIf(entry -> entry.getValue() == null || entry.getValue() <= now);
        }
        private synchronized List<String> blockedRights() {
            clearExpiredTemporaryRights(System.currentTimeMillis());
            Set<String> combined = new LinkedHashSet<>(blockedRights);
            combined.addAll(temporaryBlockedRights.keySet());
            List<String> list = new ArrayList<>(combined); Collections.sort(list); return list;
        }
        private synchronized void addChat(String message) { lastChatAt = System.currentTimeMillis(); recentChat.add(stamp() + " " + name + ": " + message); trim(recentChat, DEFAULT_MAX_CHAT_LINES); }
        private synchronized void addPrivateMessage(String message) { recentPrivateMessages.add(stamp() + " " + message); trim(recentPrivateMessages, DEFAULT_MAX_PRIVATE_MESSAGE_LINES); }
        private synchronized void addAction(String action) { recentActions.add(stamp() + " " + action); trim(recentActions, DEFAULT_MAX_ACTION_LINES); }
        private synchronized void addCombat(String action) { recentCombat.add(stamp() + " " + action); trim(recentCombat, DEFAULT_MAX_COMBAT_LINES); }
        synchronized ServerStatistics.Profile statisticsSnapshot() {
            return new ServerStatistics.Profile(clientPlatform,"BEDROCK".equals(clientPlatform)?(currentDeviceModel==null?bedrockDeviceModel:currentDeviceModel):"","BEDROCK".equals(clientPlatform)?(clientDevice.isBlank()?bedrockDeviceOs:clientDevice):"","BEDROCK".equals(clientPlatform)?clientInput:"",clientVersion,lastSeen,firstSeen,
                Math.max(0,totalPlayMillis+(currentSessionStartedAt>0?System.currentTimeMillis()-currentSessionStartedAt:0)),Math.max(0,totalAfkMillis),sessionCount,simplexPoints,warnings.size(),internalBanActive(System.currentTimeMillis()),internalMuteActive(System.currentTimeMillis()),devices.size(),localeValue());
        }
        synchronized String localeValue() { return "BEDROCK".equals(clientPlatform)&&!clientLanguage.isBlank()?clientLanguage:javaLocale; }
        synchronized long simplexPoints() { return Math.max(0L, simplexPoints); }
        synchronized long pointsActiveMillis() { return Math.max(0L, pointsActiveMillis); }
